    s = (s or "").strip().lower()
    s2 = s[:-len(" browser")].strip() if s.endswith(" browser") else s
    return (s in _BROWSER_WORDS) or (s2 in _BROWSER_WORDS) or \
        s2 in {"chrome", "google chrome", "edge", "microsoft edge", "firefox",
               "regular", "normal", "real", "web", "internet"}


