              os.path.join(lad, "Google", "Chrome", "Application", "chrome.exe")]
    firefox = [os.path.join(pf, "Mozilla Firefox", "firefox.exe"),
               os.path.join(pf86, "Mozilla Firefox", "firefox.exe")]
