    try:
        import winreg
        exe = "msedge.exe" if "edge" in name else ("firefox.exe" if ("firefox" in name or "mozilla" in name) else "chrome.exe")
        for hive in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):
