        try:
            with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, ext) as k:
                prog, _ = winreg.QueryValueEx(k, "")
                if prog:
                    return True
        except OSError:
            pass
    except Exception:
        return True  # can't determine -> allow the (non-blocking) attempt
