        for _d in (os.path.join(_home, "Pictures", "Screenshots"),
                   os.path.join(_home, "Pictures"),
                   os.path.join(_home, "Downloads"),
                   os.path.join(_home, "Desktop"),
                   os.path.join(_home, "Documents")):
            _cand = os.path.join(_d, target)
