        cands = edge + chrome
    elif "firefox" in name or "mozilla" in name:
        cands = firefox + chrome + edge
    else:
        cands = chrome + edge  # generic "browser"/"chrome" -> Chrome, fall back to Edge
    for c in cands:
        if c and os.path.isfile(c):
            return c
