                    if p and os.path.isfile(p):
                        return p
            except OSError:
                pass
    except Exception:
        pass
    import shutil as _sh
    for cand in ("chrome", "msedge", "firefox"):
        w = _sh.which(cand)
        if w:
            return w
    for e in edge:  # Edge ships with Windows — safe final fallback
