            });
            document.querySelectorAll('button, input[type=submit], a[role=button], [role=button]').forEach(el => {
              const t = (el.innerText || el.value || el.getAttribute('aria-label') || '').trim();
              if (t) out.buttons.push(t.slice(0,50));
