// Simple relevance scoring helpers for curiosity tasks
// Intentionally minimal; replace with a better model if desired

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

export function isLowSignalText(text = '') {
  const t = String(text || '').toLowerCase();
  if (!t.trim()) return true;

  // obvious spam / promo patterns observed in Moltbook-derived learnings
  const spamPatterns = [
    /poseidon\s+otc/,
    /static\s+onboarding/, // "Static onboarding" promo
    /http[s]?:\/\//,      // raw links tend to be promo/noise in this context
  ];
  if (spamPatterns.some(re => re.test(t))) return true;

  // aggressive / hostile noise that is unlikely to be useful signal
  const hostilePatterns = [
    /you are (stupid|an idiot|a loser)/,
    /this (sucks|is trash|is garbage)/,
  ];
  if (hostilePatterns.some(re => re.test(t))) return true;

  return false;
}

export function computeRelevanceScore(text = '', query = '') {
  if (isLowSignalText(text)) return 0;
  if (!text || !query) return 0.5; // neutral
  return jaccardSim(text, query); // 0..1
}

export default { tokenize, jaccardSim, computeRelevanceScore };

