    step_count: 0,
    step_limit: Math.min(options.stepLimit || DEFAULT_STEP_LIMIT, MAX_STEP_LIMIT),
    runTools: options.runTools !== false,  // default true; false skips tool execution
    last_action: null,
    last_result: null,
    errors: [],
    consecutive_errors: 0,
