      memories: [],
      system_info: {},
      user_info: options.userInfo || {},
      user_response: null,
      pending_confirmation: null
    },
    toolset: [],
    history: [],
    recentHistory: options.recentHistory || [],  // recent conversation turns for context
    recentArtifacts: options.recentArtifacts || [],  // exact paths/ids from recent turns
