// Simple relevance scoring helpers for curiosity tasks
// Intentionally minimal; replace with a better model if desired

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

export function computeRelevanceScore(text = '', query = '') {
  if (!text || !query) return 0.5; // neutral
  const base = jaccardSim(text, query); // 0..1
  const lower = String(text || '').toLowerCase();
  const hasEvidence = /\b(evidence|source|citation|cites?|data|according to|for example|for instance|study|studies|because)\b/.test(lower);
  const disagrees = /\b(i disagree|disagree with|counterexample|contrary to|not necessarily|that may be wrong|challenge that)\b/.test(lower);
  const unsupportedAgreeableCertainty = /\b(i agree|you are right|you're right|exactly right|absolutely right)\b/.test(lower) && /\b(definitely|certainly|clearly|obviously|no doubt|always|never)\b/.test(lower) && !hasEvidence && !disagrees;
  let score = base;
  if (hasEvidence && disagrees) score += 0.15;
  if (unsupportedAgreeableCertainty) score -= 0.2;
  return Math.max(0, Math.min(1, score));
}

export default { tokenize, jaccardSim, computeRelevanceScore };

