from __future__ import annotations

import platform
import os
from .._lazyimport import lazy_module
psutil = lazy_module("psutil")   # deferred to first use
import socket
from typing import Any, Dict
from ..tool_registry import Tool, register


def _plan(args: Dict[str, Any]) -> Dict[str, Any]:
    return {"preview": "Collect comprehensive system information", "args": args}


def _run(args: Dict[str, Any], dry_run: bool) -> Dict[str, Any]:
    """Collect comprehensive system information and foreground window/session state.

    Foreground/window/session data is best-effort and uses only local, read-only APIs.
    All fields may be absent on unsupported platforms or if access fails.
    """
    # Best-effort foreground window / session state helpers
    foreground_state: Dict[str, Any] = {"supported": False}

    try:
        system = platform.system()

        if system == "Windows":
            try:
                import ctypes
                from ctypes import wintypes

                user32 = ctypes.WinDLL("user32", use_last_error=True)

                GetForegroundWindow = user32.GetForegroundWindow
                GetForegroundWindow.restype = wintypes.HWND

                GetWindowTextW = user32.GetWindowTextW
                GetWindowTextW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
                GetWindowTextW.restype = ctypes.c_int

                GetWindowThreadProcessId = user32.GetWindowThreadProcessId
                GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
                GetWindowThreadProcessId.restype = wintypes.DWORD

                GetWindowRect = user32.GetWindowRect
                GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]
                GetWindowRect.restype = wintypes.BOOL

                hwnd = GetForegroundWindow()
                if hwnd:
                    title_buf = ctypes.create_unicode_buffer(512)
                    GetWindowTextW(hwnd, title_buf, 512)
                    title = title_buf.value or None

                    pid = wintypes.DWORD()
                    GetWindowThreadProcessId(hwnd, ctypes.byref(pid))

                    process_name = None
                    if psutil and pid.value:
                        try:
                            p = psutil.Process(pid.value)
                            process_name = p.name()
                        except Exception:
                            process_name = None

                    rect = wintypes.RECT()
                    bounds = None
                    if GetWindowRect(hwnd, ctypes.byref(rect)):
                        bounds = {
                            "left": int(rect.left),
                            "top": int(rect.top),
                            "right": int(rect.right),
                            "bottom": int(rect.bottom),
                            "width": int(rect.right - rect.left),
                            "height": int(rect.bottom - rect.top),
                        }

                    foreground_state = {
                        "supported": True,
                        "platform": system,
                        "window_title": title,
                        "process_name": process_name,
                        "pid": int(pid.value) if pid.value else None,
                        "bounds": bounds,
                    }
                else:
                    foreground_state = {
                        "supported": True,
                        "platform": system,
                        "window_title": None,
                        "process_name": None,
                        "pid": None,
                        "bounds": None,
                    }
            except Exception:
                foreground_state = {"supported": False, "platform": system}

        elif system in ("Linux", "Darwin"):
            # Best-effort, non-fatal foreground detection using common CLIs.
            # These may be missing; failures are swallowed.
            import subprocess
            window_title = None
            process_name = None
            pid_val = None

            try:
                if system == "Linux":
                    # Try wmctrl for X11 environments
                    try:
                        out = subprocess.check_output(["wmctrl", "-lp"], stderr=subprocess.DEVNULL, text=True)
                        active_id = None
                        try:
                            active_id = (
                                subprocess.check_output(["xprop", "-root", "_NET_ACTIVE_WINDOW"], stderr=subprocess.DEVNULL, text=True)
                                .strip()
                                .split()[-1]
                            )
                        except Exception:
                            active_id = None
                        if active_id and active_id != "0x0":
                            for line in out.splitlines():
                                parts = line.split(None, 4)
                                if len(parts) >= 5 and parts[0] == active_id:
                                    pid_val = int(parts[2])
                                    window_title = parts[4].strip() or None
                                    break
                    except Exception:
                        pass
                elif system == "Darwin":
                    # Use AppleScript via osascript for active app and window title
                    try:
                        script = (
                            'tell application "System Events" to '
                            'get {name of first process whose frontmost is true, '
                            'name of window 1 of (first process whose frontmost is true)}'
                        )
                        out = subprocess.check_output([
                            "osascript",
                            "-e",
                            script,
                        ], stderr=subprocess.DEVNULL, text=True)
                        out = out.strip().split(", ")
                        if out:
                            process_name = out[0] or None
                        if len(out) > 1:
                            window_title = out[1] or None
                    except Exception:
                        pass

                if pid_val and psutil:
                    try:
                        p = psutil.Process(pid_val)
                        process_name = process_name or p.name()
                    except Exception:
                        pass

                foreground_state = {
                    "supported": True,
                    "platform": system,
                    "window_title": window_title,
                    "process_name": process_name,
                    "pid": int(pid_val) if pid_val is not None else None,
                    "bounds": None,  # Not reliably portable without extra deps
                }
            except Exception:
                foreground_state = {"supported": False, "platform": system}
        else:
            foreground_state = {"supported": False, "platform": system}
    except Exception:
        foreground_state = {"supported": False}

    # Basic session / OS state
    session_state: Dict[str, Any] = {
        "platform": platform.system(),
        "hostname": platform.node(),
        "user": os.getenv("USERNAME") or os.getenv("USER"),
        "cwd": os.getcwd(),
        "tty": os.getenv("TERM"),
        "display": os.getenv("DISPLAY"),
    }

    try:
        # Basic system info
    try:
        # Basic system info
        system_info = {
            "status": "ok",
            "os": {
                "system": platform.system(),
                "release": platform.release(),
                "version": platform.version(),
                "machine": platform.machine(),
                "processor": platform.processor(),
                "architecture": platform.architecture(),
                "node": platform.node(),
                "python": platform.python_version(),
            },
        }

        # Add detailed system info if psutil is available
        if psutil:
            # CPU Information
            system_info["cpu"] = {
                "physical_cores": psutil.cpu_count(logical=False),
                "total_cores": psutil.cpu_count(logical=True),
                "max_frequency": f"{psutil.cpu_freq().max:.2f}MHz" if psutil.cpu_freq() else "Unknown",
                "current_frequency": f"{psutil.cpu_freq().current:.2f}MHz" if psutil.cpu_freq() else "Unknown",
                "cpu_usage": f"{psutil.cpu_percent(interval=1):.1f}%",
            }

            # Memory Information
            memory = psutil.virtual_memory()
            swap = psutil.swap_memory()
            system_info["memory"] = {
                "total": f"{memory.total / (1024**3):.2f} GB",
                "available": f"{memory.available / (1024**3):.2f} GB",
                "used": f"{memory.used / (1024**3):.2f} GB",
                "percentage": f"{memory.percent:.1f}%",
                "swap_total": f"{swap.total / (1024**3):.2f} GB",
                "swap_used": f"{swap.used / (1024**3):.2f} GB",
            }

            # Disk Information
            disks = []
            for partition in psutil.disk_partitions():
                try:
                    partition_usage = psutil.disk_usage(partition.mountpoint)
                    disks.append({
                        "device": partition.device,
                        "mountpoint": partition.mountpoint,
                        "file_system": partition.fstype,
                        "total": f"{partition_usage.total / (1024**3):.2f} GB",
                        "used": f"{partition_usage.used / (1024**3):.2f} GB",
                        "free": f"{partition_usage.free / (1024**3):.2f} GB",
                        "percentage": f"{(partition_usage.used / partition_usage.total * 100):.1f}%",
                    })
                except PermissionError:
                    continue
            system_info["storage"] = disks

            # Network Information
            network_info = []
            for interface, addresses in psutil.net_if_addrs().items():
                interface_info = {"interface": interface, "addresses": []}
                for address in addresses:
                    if address.family == socket.AF_INET:  # IPv4
                        interface_info["addresses"].append({
                            "type": "IPv4",
                            "address": address.address,
                            "netmask": address.netmask,
                        })
                    elif address.family == socket.AF_INET6:  # IPv6
                        interface_info["addresses"].append({
                            "type": "IPv6",
                            "address": address.address,
                            "netmask": address.netmask,
                        })
                if interface_info["addresses"]:
                    network_info.append(interface_info)
            system_info["network"] = network_info

            # Boot time
            import datetime
            boot_time = datetime.datetime.fromtimestamp(psutil.boot_time())
            system_info["boot_time"] = boot_time.strftime("%Y-%m-%d %H:%M:%S")

        return system_info

    except Exception as e:
        return {
            "status": "error", 
            "message": f"Failed to collect system info: {str(e)}",
            "basic_info": {
                "system": platform.system(),
                "release": platform.release(),
                "python": platform.python_version(),
            }
        }


TOOL = Tool(
    name="sys_ops",
    summary="Comprehensive system information: OS details, CPU specs, memory, storage, network interfaces, hardware info. Use this for ANY system information requests.",
    plan=_plan,
    run=_run,
)

register(TOOL)

