+// Moving-average state per agent (agentId -> history)
+// Each entry: { scores: number[], errors: number[], weight: number }
+const agentHistory = new Map();

+/**
+ * Record an execution outcome for an agent.
+ * @param {string} agentId
+ * @param {boolean} hadError - whether the action produced a path-not-allowed or similar tool violation
+ * @param {number} rawScore - the base curiosity score before boost (0..1)
+ * @returns {number} boosted final score
+ */
+export function recordExecution(agentId, hadError, rawScore) {
+  let h = agentHistory.get(agentId);
+  if (!h) {
+    h = { scores: [], errors: [], weight: 1 };
+    agentHistory.set(agentId, h);
+  }
+  // Keep last 5 entries for moving average
+  const MAX_HISTORY = 5;
+  h.scores.push(rawScore);
+  h.errors.push(hadError ? 1 : 0);
+  if (h.scores.length > MAX_HISTORY) {
+    h.scores.shift();
+    h.errors.shift();
+  }
+  // Weighted moving average — recent errors matter more
+  let totalWeight = 0;
+  let weightedScore = 0;
+  for (let i = 0; i < h.scores.length; i++) {
+    const w = h.weight * (i + 1); // linear recency boost
+    weightedScore += h.scores[i] * w;
+    totalWeight += w;
+  }
+  const avgScore = totalWeight > 0 ? weightedScore / totalWeight : rawScore;
+  // Error-reduction bonus: if last 3 of 5 are error-free, give +0.15 boost
+  const recentClean = h.errors.filter(e => e === 0).length >= 3;
+  const boost = recentClean ? 0.15 : 0;
+  const final = Math.min(avgScore + boost, 1);
+  return final;
+}
+
+/**
+ * Clear all stored agent history (for testing or reset).
+ */
+export function resetHistory() {
+  agentHistory.clear();
+}
+
+export default { tokenize, jaccardSim, computeRelevanceScore, recordExecution, resetHistory };
