// voiceBus — a tiny in-process pub/sub so internal modules (conversationLogger,
// toolsService, /respond) can publish "what AVA is doing" events without importing
// the voice route (avoids circular imports). voice.js subscribes and fans these out
// to connected WebSocket UI clients.
import { EventEmitter } from 'events';
import { exec } from 'child_process';

const bus = new EventEmitter();
bus.setMaxListeners(100);

// Capture the foreground window title and process name via PowerShell (Windows).
// Stores the result on the provided request object as `foregroundApp`.
// Designed to be called after processing a voice command for live context.
const _capturedForegroundApp = {}; // shared state so getForegroundApp() always has latest

/**
 * Asynchronously captures the current foreground application title and process name.
 * Updates internal state; the result can be accessed via getForegroundApp().
 * @param {Object} [req] - Optional request object to attach foregroundApp property to.
 * @returns {Promise<{title: string, processName: string} | null>}
 */
function _captureForegroundApp(req) {
  return new Promise((resolve) => {
    exec(
      'powershell -command "Get-Process | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1 MainWindowTitle, ProcessName | ConvertTo-Json"',
      { timeout: 5000 },
      (error, stdout) => {
        if (error || !stdout.trim()) {
          resolve(null);
          return;
        }
        try {
          const parsed = JSON.parse(stdout.trim());
          const result = {
            title: (parsed.MainWindowTitle || '').trim(),
            processName: (parsed.ProcessName || '').trim()
          };
          _capturedForegroundApp.title = result.title;
          _capturedForegroundApp.processName = result.processName;
          _capturedForegroundApp.timestamp = Date.now() / 1000;
          if (req) {
            req.foregroundApp = result;
          }
          resolve(result);
        } catch {
          resolve(null);
        }
      }
    );
  });
}

/**
 * Get the most recently captured foreground application info.
 * Returns { title, processName, timestamp } or null if never captured.
 */
export function getForegroundApp() {
  if (!_capturedForegroundApp.title) return null;
  return { ..._capturedForegroundApp };
}

/**
 * Publish a voice/activity event. Shape matches what voice.js broadcasts:
 *   { type, timestamp(sec), data, source }
 */
export async function emitVoiceEvent(type, data = {}, source = 'server') {
  const event = { type, timestamp: Date.now() / 1000, data: data || {}, source };
  try {
    bus.emit('event', event);
    // Capture foreground app context after each voice event (fire-and-forget, never fails)
    _captureForegroundApp(event).catch(() => {});
  } catch { /* never let telemetry break the caller */ }
  return event;
}

export function onVoiceEvent(handler) {
  bus.on('event', handler);
}

export default bus;

