        task = {
            "id": task_id,
            "type": task_type,
            "schedule": schedule_str,
            "data": task_data,
            "created_at": datetime.now().isoformat()
        }

        # Parse schedule string and add to scheduler
        # Examples: "every 1 hour", "every day at 10:00", "every monday"
        if "every" in schedule_str:
