      stage.error = res.result;
      wf.log.push({ ts: Date.now(), stage: stage.title, status: 'failed', error: res.result });
      if (stage.attempts < MAX_STAGE_ATTEMPTS) {
        stage.status = 'pending';  // retry
        _checkpoint(wf);
        continue;
      }
      stage.status = 'failed';
      if ((wf.replans || 0) >= MAX_REPLANS) {
