function list() {
  const map = _loadAll();
  return Object.values(map).sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))
    .map(w => ({ id: w.id, goal: w.goal, status: w.status, stages: w.stages.length, done: w.stages.filter(s => s.status === 'done').length, updatedAt: w.updatedAt }));
}
