function resume(id) { const wf = get(id); if (!wf) return { ok: false, error: 'not found' }; if (wf.status === 'done') return { ok: true, status: 'done' }; setImmediate(() => run(id).catch(() => {})); return { ok: true, id, status: 'resuming' }; }

