            return {"status": "error", "message": "Window title or title_match required"}

        # Find windows matching the title (case-insensitive partial match)
        windows = gw.getWindowsWithTitle(title_match)

        if not windows:
            # Try case-insensitive search
            all_windows = gw.getAllWindows()
            windows = [w for w in all_windows if title_match.lower() in w.title.lower()]

        if not windows:
            return {"status": "error", "message": f"No window found matching: {title_match}"}

        # Use first matching window
        window = windows[0]

        if action == "focus":
            hwnd = getattr(window, "_hWnd", None)
            ok = _force_foreground(hwnd)
            if not ok:
                try:
                    window.activate()
                    ok = True
                except Exception:
                    ok = False
            return {"status": "ok" if ok else "error",
                    "message": (f"Focused window: {window.title}" if ok
                                else f"Found '{window.title}' but couldn't bring it to the foreground"),
                    "title": window.title, "foreground": ok}

        elif action == "minimize":
            window.minimize()
            return {"status": "ok", "message": f"Minimized window: {window.title}"}

        elif action == "maximize":
            window.maximize()
            return {"status": "ok", "message": f"Maximized window: {window.title}"}

        elif action == "restore":
            window.restore()
            return {"status": "ok", "message": f"Restored window: {window.title}"}

        elif action == "close":
            window.close()
            return {"status": "ok", "message": f"Closed window: {window.title}"}

        elif action == "move":
            x = args.get("x", window.left)
            y = args.get("y", window.top)
            window.moveTo(x, y)
            return {"status": "ok", "message": f"Moved window to ({x}, {y})"}

        elif action == "resize":
            width = args.get("width", window.width)
            height = args.get("height", window.height)
            window.resizeTo(width, height)
            return {"status": "ok", "message": f"Resized window to {width}x{height}"}

        elif action == "move_resize":
            x = args.get("x", window.left)
            y = args.get("y", window.top)
            width = args.get("width", window.width)
            height = args.get("height", window.height)
            window.moveTo(x, y)
            window.resizeTo(width, height)
            return {"status": "ok", "message": f"Moved to ({x},{y}) and resized to {width}x{height}"}

        else:
            return {"status": "error", "message": f"Unknown action: {action}"}

    except Exception as e:
        return {"status": "error", "message": f"Window operation error: {str(e)}"}

TOOL = Tool(
    name="window_ops",
    summary=("Window management — list, active (the foreground window's title), focus, close, minimize, "
             "maximize, move, resize. action='focus' title=<app/window name> RELIABLY brings a window to "
             "the foreground (verified) and reports foreground:true/false. action='active' returns the title "
             "of whatever window is in front right now. To CLOSE an app/window pass action='close' and "
             "title=<app or window name> (partial, case-insensitive, e.g. title='paint'); closing sends a "
             "normal close so the app still prompts to save if needed. To send a SAVE/PRINT/NEXT-PAGE/etc. "
             "command to an app, prefer app_control (it focuses first, then sends the command)."),
    plan=_plan,
    run=_run,
)

register(TOOL)


def _get_process_name(hwnd):
    """Return the executable name for the process owning *hwnd*, or empty string."""
    if not _WIN32_IMPORTS_OK:
        return ""
    try:
        _, pid = win32process.GetWindowThreadProcessId(hwnd)
        import psutil
        return psutil.Process(pid).name()
    except Exception:
        return ""


def get_foreground_info() -> Dict[str, Any]:
    """
    Return structured info about the currently foreground window.

    Returns a dict with keys:
        handle (int)  – window HWND
        title  (str)  – window text
        process (str) – executable name (e.g. "notepad.exe")
        timestamp (float) – time.time() when retrieved

    If win32gui is unavailable the dict carries an error key and empty values.
    """
    if not _WIN32_IMPORTS_OK:
        return {
            "error": "win32gui not available — install pywin32",
            "handle": None,
            "title": "",
            "process": "",
            "timestamp": _time_module.time(),
        }
    try:
        hwnd = win32gui.GetForegroundWindow()
        if not hwnd:
            return {
                "error": "no foreground window",
                "handle": None,
                "title": "",
                "process": "",
                "timestamp": _time_module.time(),
            }
        title = win32gui.GetWindowText(hwnd)
        process = _get_process_name(hwnd)
        return {
            "handle": int(hwnd),
            "title": title,
            "process": process,
            "timestamp": _time_module.time(),
        }
    except Exception as exc:
        return {
            "error": str(exc),
            "handle": None,
            "title": "",
            "process": "",
            "timestamp": _time_module.time(),
        }


def get_open_windows() -> List[Dict[str, Any]]:
    """
    Return a list of dicts for every visible top-level window that has a non-empty title.

    Each entry contains:
        handle    (int)
        title     (str)
        process   (str)
        timestamp (float)

    Falls back to pygetwindow enumeration when win32gui is absent.
    """
    windows = []
    now = _time_module.time()

    def _enum_callback(hwnd, _lParam):
        if not win32gui.IsWindowVisible(hwnd):
            return True
        length = win32gui.GetWindowTextLength(hwnd)
        if length == 0:
            return True
        title = win32gui.GetWindowText(hwnd)
        if not title.strip():
            return True
        process = _get_process_name(hwnd)
        windows.append({
            "handle": int(hwnd),
            "title": title,
            "process": process,
            "timestamp": now,
        })
        return True

    if _WIN32_IMPORTS_OK:
        try:
            win32gui.EnumWindows(_enum_callback, None)
            return windows
        except Exception:
            pass  # fall through to pygetwindow path

    # Fallback using pygetwindow
    try:
        for w in gw.getAllWindows():
            if w.title and w.visible:
                windows.append({
                    "handle": getattr(w, "_hWnd", None),
                    "title": w.title,
                    "process": "",
                    "timestamp": now,
                })
    except Exception:
        pass
    return windows


# Expose the new functions via the existing _tool_list so callers that
# enumerate tools can discover them.
_FOREGROUND_TOOL = Tool(
    name="get_foreground_info",
    summary=("Return the currently active (foreground) window's title, process name, and handle. "
             "No arguments needed. Returns structured dict."),
    plan=lambda args: {"preview": "Get foreground window info", "args": args},
    run=lambda args, dry_run: (
        {"status": "dry-run", "message": "Would get foreground window info"}
        if dry_run else {"status": "ok", **get_foreground_info()}
    ),
)
_OPEN_WINDOWS_TOOL = Tool(
    name="get_open_windows",
    summary=("List all visible top-level windows with non-empty titles. Returns an array of "
             "structured entries each containing handle, title, process, and timestamp."),
    plan=lambda args: {"preview": "List all open windows", "args": args},
    run=lambda args, dry_run: (
        {"status": "dry-run", "message": "Would list open windows"}
        if dry_run else {"status": "ok", "windows": get_open_windows(), "count": len(get_open_windows())}
    ),
)
register(_FOREGROUND_TOOL)
register(_OPEN_WINDOWS_TOOL)

