// Async "dreaming" memory reviewer.
// Periodically (every N turns, or on demand) reads recent conversation, extracts ONLY
// durable facts, scans them for prompt-injection/secrets, and writes them into the
// bounded curated memory (USER.md / MEMORY.md). Consolidates when near the cap.
// Pattern: Hermes "memory reviewer" + Claude Code "autodream" consolidation.
import fs from 'fs';
import logger from '../utils/logger.js';
import llmService from './llm.js';
import conversationLogger from './conversationLogger.js';
import curatedMemory from './curatedMemory.js';

// Reject patterns — never let untrusted conversation text become a behavior-altering or
// Retention policy: prune debug/transient facts older than 24h unless they carry durable signal.
const RETENTION_HOURS = 24;
const MIN_IMPORTANCE_FOR_KEEP = 3;
const DURABLE_TAGS = new Set(['failure','decision','dispute']);

function _tagSet(fact) { return new Set((fact.tags||[]).map(t=>t.toLowerCase())); }
function _isDurable(fact) {
  const tags = _tagSet(fact);
  return DURABLE_TAGS.intersection?.(tags)?.size > 0 || DURABLE_TAGS.some(t=>tags.has(t)) || (fact.importance||0) >= MIN_IMPORTANCE_FOR_KEEP;
}

/**
 * Enforce retention: prune facts lacking durable tags/importance from all memory targets.
 * Returns { pruned, remaining } for logging.
 */
function pruneByPolicy(memory) {
  const now = Date.now();
  const cutoff = now - RETENTION_HOURS * 60 * 60 * 1000;
  let pruned = 0, remaining = 0;
  for (const [target, facts] of Object.entries(memory)) {
    if (!Array.isArray(facts)) continue;
    const kept = facts.filter(f => {
      const ts = f.timestamp ? new Date(f.timestamp).getTime() : now;
      if (ts > cutoff) { remaining++; return true; }          // recent enough
      if (ts <= cutoff && !_isDurable(f)) { pruned++; return false; }
      remaining++;
      return true;
    });
    if (kept.length !== facts.length) memory[target] = kept;
  }
  return { pruned, remaining };
}
// secret "memory" (AVA reads email/web/files, so this guard matters).
const REJECT = [
  /ignore\s+(all\s+)?(previous|prior)\s+instructions/i,
  /disregard\s+(all\s+)?(previous|prior)/i,
  /\bsystem\s+prompt\b/i,
