// voiceBus — a tiny in-process pub/sub so internal modules (conversationLogger,
// toolsService, /respond) can publish "what AVA is doing" events without importing
// the voice route (avoids circular imports). voice.js subscribes and fans these out
// to connected WebSocket UI clients.
import { EventEmitter } from 'events';

const bus = new EventEmitter();
bus.setMaxListeners(100);

/**
 * Publish a voice/activity event. Shape matches what voice.js broadcasts:
 *   { type, timestamp(sec), data, source, foregroundApp }
 */
export function emitVoiceEvent(type, data = {}, source = 'server') {
  const event = { type, timestamp: Date.now() / 1000, data: data || {}, source };
  // Attach live foreground window info from global state if available
  if (typeof global !== 'undefined' && global.__avaForegroundApp) {
    event.foregroundApp = global.__avaForegroundApp;
  }
  try { bus.emit('event', event); } catch { /* never let telemetry break the caller */ }
  return event;
}

export function onVoiceEvent(handler) {
  bus.on('event', handler);
}

/**
 * Capture the foreground app info from the window_ops tool and store it in
 * global.__avaForegroundApp so it's available to emitVoiceEvent and any other
 * service (tools.js, doctor.js, environmentContext.js) without extra Python calls.
 * Uses pythonWorker.executeTool — the only correct method per the codebase API.
 */
export async function captureForegroundApp() {
  try {
    const { default: pythonWorker } = await import('./pythonWorker.js');
    const result = await pythonWorker.executeTool('window_ops.get_foreground_info', {});
    if (result && (result.title || result.process)) {
      global.__avaForegroundApp = { title: result.title || 'unknown', process: result.process || 'unknown' };
    }
  } catch {
    // Silently ignore failures — foreground awareness is best-effort
  }
}

// Trigger once on load for immediate availability
captureForegroundApp();

// Re-capture every 30 seconds for freshness
setInterval(captureForegroundApp, 30000);

export default bus;

