// Simple relevance scoring helpers for curiosity tasks
// Intentionally minimal; replace with a better model if desired

// In-memory error-history store: skill -> failure count (e.g., 'voice' -> 2)
const errorHistory = new Map();

// Maximum boost applied for repeated failures
const MAX_ERROR_BOOST = 0.3;

// Decay factor per error (diminishing returns)
const ERROR_DECAY = 1.5;

export function recordFailure(skill = '') {
  if (!skill) return;
  const key = skill.trim().toLowerCase();
  const current = errorHistory.get(key) || 0;
  errorHistory.set(key, current + 1);
}

export function clearErrorHistory(skill) {
  if (skill) {
    errorHistory.delete(skill.trim().toLowerCase());
  } else {
    errorHistory.clear();
  }
}

export function getErrorCount(skill) {
  return errorHistory.get(skill.trim().toLowerCase()) || 0;
}

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

// Maps a message/text to likely skill areas (e.g. 'quota' -> 'voice', 'access denied' -> 'file')
const SKILL_HINTS = {
  '429': 'voice',
  'quota': 'voice',
  'rate limit': 'voice',
  'path not allowed': 'file',
  'access denied': 'file',
  'permission': 'file',
  'timeout': 'network',
  'unavailable': 'network',
  'fail': 'general'
};

function inferSkillFromText(text = '') {
  const lower = text.toLowerCase();
  for (const [keyword, skill] of Object.entries(SKILL_HINTS)) {
    if (lower.includes(keyword)) return skill;
  }
  return '';
}

export function computeRelevanceScore(text = '', query = '') {
  if (!text || !query) return 0.5; // neutral
  const base = jaccardSim(text, query); // 0..1
  // Boost score if text reflects a skill with error history
  const skill = inferSkillFromText(text);
  if (skill) {
    const failures = errorHistory.get(skill) || 0;
    if (failures > 0) {
      const boost = Math.min(failures / (failures + ERROR_DECAY), MAX_ERROR_BOOST);
      return Math.min(base + boost, 1.0);
    }
  }
  return base;
}

export default { tokenize, jaccardSim, computeRelevanceScore, recordFailure, clearErrorHistory, getErrorCount };

