def _check_browser_available(executable: str = "chrome") -> dict:
    """Check if a browser executable is available and capture its version."""
    result = {"available": False, "version": None, "error": None}
    if not _HAS_SUBPROCESS:
        result["error"] = "subprocess module not available"
        return result
    # Common browser executable names to try
    candidates = [executable, "google-chrome", "google-chrome-stable", "chromium", "chromium-browser", "edge"]
