"""
Enhanced Voice - ElevenLabs TTS, custom voice models, voice cloning
"""

import os
import subprocess
import tempfile
from elevenlabs import VoiceSettings, Voice
from elevenlabs.client import ElevenLabs
from typing import Any, Dict
from ..tool_registry import Tool, register

# Fallback TTS: gTTS (offline-capable via Google's free API, no account needed)
try:
    from gtts import gTTS
except ImportError:
    gTTS = None  # gracefully degrade if not installed

from playsound import playsound

# ElevenLabs configuration
ELEVENLABS_API_KEY = os.getenv('ELEVENLABS_API_KEY', '')
# Default voice for TTS. Configurable via env so it isn't hardwired; falls back to
# ElevenLabs "Rachel" if unset. Set ELEVENLABS_VOICE_ID to e.g. Vella's cloned voice.
DEFAULT_VOICE_ID = os.getenv('ELEVENLABS_VOICE_ID', '21m00Tcm4TlvDq8ikWAM')

class VoiceManager:
    def __init__(self):
        self.client = None
        self.available_voices = []

    def get_client(self):
        """Get ElevenLabs client"""
        if not self.client and ELEVENLABS_API_KEY:
            self.client = ElevenLabs(api_key=ELEVENLABS_API_KEY)
        return self.client

    def list_voices(self):
        """List available voices"""
        client = self.get_client()

        if not client:
            # Return default voice options if API not configured
            return [
                {"name": "Rachel", "voice_id": "21m00Tcm4TlvDq8ikWAM", "category": "premade"},
                {"name": "Domi", "voice_id": "AZnzlk1XvdvUeBnXmlld", "category": "premade"},
                {"name": "Bella", "voice_id": "EXAVITQu4vr4xnSDxMaL", "category": "premade"},
                {"name": "Antoni", "voice_id": "ErXwobaYiN019PkySvjV", "category": "premade"},
                {"name": "Elli", "voice_id": "MF3mGyEYCl7XYWbV9V6O", "category": "premade"},
                {"name": "Josh", "voice_id": "TxGEqnHWrfWFTfGW9XjX", "category": "premade"},
                {"name": "Arnold", "voice_id": "VR6AewLTigWG4xSOukaG", "category": "premade"},
                {"name": "Adam", "voice_id": "pNInz6obpgDQGcFmaJgB", "category": "premade"},
                {"name": "Sam", "voice_id": "yoZ06aMxZJJ28mfd3POQ", "category": "premade"}
            ]

        # Use the raw REST endpoint instead of client.voices.get_all(): the v1 SDK's
        # pydantic model fails to parse the current /voices response (fine_tuning.message),
        # which previously made this return None and crash on len(). REST + manual parse
        # is robust and returns the real account voices (incl. the Vella clone).
        try:
            import requests
            r = requests.get("https://api.elevenlabs.io/v1/voices",
                             headers={"xi-api-key": ELEVENLABS_API_KEY}, timeout=20)
            data = r.json()
            voices = [{"name": v.get("name"), "voice_id": v.get("voice_id"),
                       "category": v.get("category", "unknown")} for v in data.get("voices", [])]
            if voices:
                return voices
            raise ValueError("empty voice list")
        except Exception:
            # Safe fallback (a valid list, never None) so callers never crash.
            return [
                {"name": "Rachel", "voice_id": "21m00Tcm4TlvDq8ikWAM", "category": "premade"},
                {"name": "Vella", "voice_id": DEFAULT_VOICE_ID, "category": "cloned"},
            ]

    def speak(self, text, voice_id=DEFAULT_VOICE_ID, output_path=None, stability=0.5, similarity_boost=0.75):
        """Generate speech using ElevenLabs"""
        client = self.get_client()

        if not client:
            raise Exception("ElevenLabs not configured. Set ELEVENLABS_API_KEY environment variable.")

        try:
            # Generate audio. Pass a Voice object (voice_id directly) so the SDK does
            # NOT call voices.get_all() to resolve a name — that endpoint has a schema
            # parse bug in elevenlabs 1.0.0 and would make ElevenLabs error out and
            # silently fall back to local SAPI. This keeps the Vella voice_id working.
            audio = client.generate(
                text=text,
                voice=Voice(
                    voice_id=voice_id,
                    settings=VoiceSettings(
                        stability=stability,
                        similarity_boost=similarity_boost
                    )
                ),
                model="eleven_monolingual_v1"
            )

            # Save or return audio
            if output_path:
                # Save audio to file
                with open(output_path, 'wb') as f:
                    for chunk in audio:
                        f.write(chunk)
                return output_path
            else:
                # Return audio data
                audio_data = b''.join(audio)
                return audio_data

        except Exception as e:
            raise Exception(f"ElevenLabs TTS error: {str(e)}")

    def _fallback_gtts(self, text: str, output_path: str = None) -> bytes:
        """Generate speech using gTTS (offline, no API key needed). Returns WAV bytes."""
        if gTTS is None:
            raise ImportError("gTTS not installed; install with 'pip install gtts'")
        tts = gTTS(text=text, lang='en', slow=False)
        # gTTS writes to a file or BytesIO; we use a temp file for simplicity
        with tempfile.NamedTemporaryFile(suffix=".mp3", delete=False) as tmp:
            tmpname = tmp.name
            tts.save(tmpname)
        with open(tmpname, 'rb') as f:
            data = f.read()
        os.unlink(tmpname)
        if output_path:
            with open(output_path, 'wb') as f:
                f.write(data)
        return data

voice_manager = VoiceManager()

def _plan(args: Dict[str, Any]) -> Dict[str, Any]:
    action = args.get("action", "speak")

    if action == "speak":
        return {"preview": f"Generate speech with ElevenLabs", "args": args}
    elif action == "list_voices":
        return {"preview": "List available voices", "args": args}
    elif action == "clone_voice":
        return {"preview": "Clone voice from audio samples", "args": args}
    else:
        return {"preview": f"Voice action: {action}", "args": args}

def _run(args: Dict[str, Any], dry_run: bool) -> Dict[str, Any]:
    if dry_run:
        return {"status": "dry-run", "message": "Would perform voice operation", "plan": _plan(args)}

    action = args.get("action", "speak")

    try:
        if action == "speak":
            text = args.get("text")
            voice_id = args.get("voice_id", DEFAULT_VOICE_ID)  # default via ELEVENLABS_VOICE_ID (Vella)
            output_path = args.get("output_path")
            stability = args.get("stability", 0.5)
            similarity_boost = args.get("similarity_boost", 0.75)

            if not text:
                return {"status": "error", "message": "text required"}

            try:
                result = voice_manager.speak(text, voice_id, output_path, stability, similarity_boost)

                if output_path:
                    file_size = os.path.getsize(output_path) / 1024  # KB
                    return {
                        "status": "ok",
                        "message": f"Speech generated and saved",
                        "file_path": output_path,
                        "size_kb": round(file_size, 2),
                        "voice_id": voice_id
                    }
                else:
                    return {
                        "status": "ok",
                        "message": "Speech generated",
                        "audio_size_bytes": len(result),
                        "voice_id": voice_id
                    }
            except Exception as voice_error:
                # Fallback: try gTTS-based synthesis (offline, no API key, works on 429/quotas)
                try:
                    # Detect quota/429 errors from ElevenLabs to trigger gTTS
                    err_lower = str(voice_error).lower()
                    if '429' in err_lower or 'quota' in err_lower or 'too many requests' in err_lower or 'rate limit' in err_lower:
                        try:
                            audio_bytes = voice_manager._fallback_gtts(text, output_path)
                            if output_path:
                                file_size = os.path.getsize(output_path) / 1024
                                return {
                                    "status": "ok",
                                    "message": "Speech generated via gTTS fallback (ElevenLabs quota exhausted)",
                                    "file_path": output_path,
                                    "size_kb": round(file_size, 2),
                                    "engine": "gtts"
                                }
                            else:
                                return {
                                    "status": "ok",
                                    "message": "Speech generated via gTTS fallback (ElevenLabs quota exhausted)",
                                    "audio_size_bytes": len(audio_bytes),
                                    "engine": "gtts"
                                }
                        except Exception as gtts_err:
                            # If gTTS also fails, play via local Windows TTS as last resort
                            try:
                                safe = str(text).replace("'", "''")
                                ps = ("Add-Type -AssemblyName System.Speech; "
                                      "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer; "
                                      f"$s.Speak('{safe}')")
                                subprocess.run(["powershell", "-NoProfile", "-Command", ps],
                                               timeout=60, capture_output=True)
                                return {
                                    "status": "ok",
                                    "message": "Spoken via local Windows TTS (ElevenLabs quota, gTTS fallback failed)",
                                    "engine": "windows-sapi"
                                }
                            except Exception as sapi_err:
                                return {
                                    "status": "error",
                                    "message": f"All TTS paths failed (ElevenLabs: {str(voice_error)[:80]}, gTTS: {str(gtts_err)[:80]}, SAPI: {str(sapi_err)[:80]})"
                                }
                    else:
                        # Non-quota error: try gTTS directly
                        try:
                            audio_bytes = voice_manager._fallback_gtts(text, output_path)
                            if output_path:
                                file_size = os.path.getsize(output_path) / 1024
                                return {
                                    "status": "ok",
                                    "message": "Speech generated via gTTS (ElevenLabs error: " + str(voice_error)[:60] + ")",
                                    "file_path": output_path,
                                    "size_kb": round(file_size, 2),
                                    "engine": "gtts"
                                }
                            else:
                                return {
                                    "status": "ok",
                                    "message": "Speech generated via gTTS (ElevenLabs error: " + str(voice_error)[:60] + ")",
                                    "audio_size_bytes": len(audio_bytes),
                                    "engine": "gtts"
                                }
                        except Exception as gtts_err:
                            return {
                                "status": "error",
                                "message": f"TTS failed (ElevenLabs: {str(voice_error)[:80]}; gTTS fallback: {str(gtts_err)[:80]})"
                            }
                except Exception as fallback_err:
                    return {
                        "status": "error",
                        "message": f"TTS fallback chain error: {str(fallback_err)[:80]}"
                    }

        elif action == "list_voices":
            voices = voice_manager.list_voices()

            return {
                "status": "ok",
                "voices": voices,
                "count": len(voices),
                "message": f"Found {len(voices)} available voice(s)"
            }

        elif action == "clone_voice":
            client = voice_manager.get_client()

            if not client:
                return {
                    "status": "error",
                    "message": "ElevenLabs not configured",
                    "note": "To setup ElevenLabs: Set ELEVENLABS_API_KEY environment variable"
                }

            name = args.get("name", "Custom Voice")
            description = args.get("description", "Cloned voice")
            files = args.get("files", [])  # List of audio file paths

            if not files:
                return {"status": "error", "message": "files (audio samples) required for voice cloning"}

            try:
                # Voice cloning API call
                voice = client.clone(
                    name=name,
                    description=description,
                    files=files
                )

                return {
                    "status": "ok",
                    "message": f"Voice cloned: {name}",
                    "voice_id": voice.voice_id,
                    "name": voice.name
                }
            except Exception as clone_error:
                return {"status": "error", "message": f"Voice cloning error: {str(clone_error)}"}

        elif action == "delete_voice":
            client = voice_manager.get_client()

            if not client:
                return {"status": "error", "message": "ElevenLabs not configured"}

            voice_id = args.get("voice_id")

            if not voice_id:
                return {"status": "error", "message": "voice_id required"}

            try:
                client.voices.delete(voice_id)
                return {"status": "ok", "message": f"Voice {voice_id} deleted"}
            except Exception as delete_error:
                return {"status": "error", "message": f"Delete error: {str(delete_error)}"}

        elif action == "get_voice_settings":
            voice_id = args.get("voice_id", DEFAULT_VOICE_ID)

            # Return recommended voice settings
            settings = {
                "stability": {
                    "description": "Controls consistency (0.0-1.0)",
                    "recommended": 0.5,
                    "current": args.get("stability", 0.5)
                },
                "similarity_boost": {
                    "description": "Controls how much voice matches original (0.0-1.0)",
                    "recommended": 0.75,
                    "current": args.get("similarity_boost", 0.75)
                }
            }

            return {
                "status": "ok",
                "settings": settings,
                "voice_id": voice_id
            }

        else:
            return {"status": "error", "message": f"Unknown action: {action}"}

    except Exception as e:
        return {"status": "error", "message": f"Voice ops error: {str(e)}"}

TOOL = Tool(
    name="voice_ops",
    summary="Enhanced voice - ElevenLabs TTS with multiple voices, voice cloning, custom voice settings (stability, similarity)",
    plan=_plan,
    run=_run,
    # Enable audio playback for gTTS output (plays AudioSegment via local player)
    playback={"enabled": True, "player": "auto"}
)

register(TOOL)

