import os
import re

def _detect_access_denied_and_retry(action_fn, args, dry_run):
    result = action_fn(args, dry_run)
    if isinstance(result, dict):
        msg = str(result.get("message", ""))
        err = str(result.get("error", ""))
        combined = (msg + " " + err).lower()
        if "path not allowed" in combined or "access is denied" in combined or "winerror 5" in combined:
            path_match = re.search(r"[\'\"]([^\'\"]+)[\'\"]", msg)
            if not path_match:
                path_match = re.search(r"[\'\"]([^\'\"]+)[\'\"]", err)
            if path_match:
                blocked_path = path_match.group(1)
                normalized = os.path.realpath(blocked_path)
                if normalized != blocked_path:
                    import time
                    time.sleep(1)
                    if "file_path" in args:
                        args["file_path"] = normalized
                    elif "path" in args:
                        args["path"] = normalized
                    result2 = action_fn(args, dry_run)
                    if result2.get("status") != "error":
                        return result2
    return result

def _run(args: Dict[str, Any], dry_run: bool) -> Dict[str, Any]:
    if dry_run:
        return {"status": "dry-run", "message": "Would control computer_use", "plan": _plan(args)}

    action = str(args.get("action", "")).strip().lower()
    # Wrap in retry handler for path-not-allowed / Access is denied errors
    return _detect_access_denied_and_retry(_run_inner, args, dry_run)

def _run_inner(args: Dict[str, Any], dry_run: bool) -> Dict[str, Any]:
    try:
        # `import cmpuse.tools.computer_use as cu` returns the Tool object (the package
        # attribute shadows the submodule) which has no set_pause/set_stop. Use
        # importlib to get the real MODULE with those functions.
        import importlib
        cu = importlib.import_module("cmpuse.tools.computer_use")
    except Exception as e:
        return {"status": "error", "message": f"control module unavailable: {str(e)}"}

    if action in ("pause", "paused"):
        cu.set_pause(True)
        return {"status": "ok", "message": "automation_paused", "paused": True}
    if action in ("resume", "continue"):
        cu.set_pause(False)
        return {"status": "ok", "message": "automation_resumed", "paused": False}
    if action in ("stop", "abort"):
        cu.set_stop(True)
        return {"status": "ok", "message": "automation_stopped", "stopped": True}

    return {"status": "error", "message": f"unknown action: {action}"}


TOOL = Tool(
    name="computer_use_control",
    summary="Control on-screen automation: pause/resume/stop",
    plan=_plan,
    run=_run,
)

register(TOOL)

