function rewriteArgs(args) {
  const out = { ...(args || {}) };
  for (const k of ['file_path', 'path', 'filepath', 'dir', 'directory', 'save_path', 'dest', 'destination', 'video_path', 'target']) {
    if (typeof out[k] === 'string') out[k] = rewritePath(out[k]);
  }
  return out;
}

