    if (!fs.existsSync(convDir)) return [];
    const since = Date.now() - 72 * 3600 * 1000;
    const out = [];
    for (const f of fs.readdirSync(convDir).filter(x => x.endsWith('.jsonl'))) {
      let content = '';
