        const first = Array.isArray(disks) ? disks[0] : (disks && Object.values(disks)[0]);
        if (first && first.percentage) _cache.disk = `${first.mountpoint || first.device || 'disk'} ${first.percentage}`;
      } catch { /* optional */ }
