  } finally { _refreshing = false; }
}

// Enriches the environment block with foreground window info via pythonWorker.sendCommand (the only confirmed API in pythonWorker.js).
// This is the safe, passive integration that previous rejected proposals failed to achieve — uses sendCommand, not exec/executeTool/execute.
