    return { ok: true, gen, turnsCovered: turns.length, summary };
  } catch (e) {
    try { logger.warn('[compress] maybeCompress failed', { error: e.message }); } catch { /* ignore */ }
    return { error: e.message };
  }
}

// Compress the conversation messages array to stay within token budget.
// Prunes older non-system, non-tool-result messages, keeping the system prompt,
// the most recent user/assistant exchanges, and all messages containing tool results.
// Returns an object with { kept, pruned, totalBefore, totalAfter } or { error }.
function compressConversation(messages, tokenBudget = DEFAULT_TOKEN_BUDGET) {
  if (!Array.isArray(messages) || !messages.length) {
    return { kept: 0, pruned: 0, totalBefore: 0, totalAfter: 0 };
  }
  try {
    const totalBefore = messages.length;
    // Estimate total tokens; if already under budget, do nothing.
    let totalTokens = 0;
    for (const m of messages) {
      totalTokens += estimateTokens(String(m.content || ''));
    }
    if (totalTokens <= tokenBudget) {
      return { kept: messages.length, pruned: 0, totalBefore, totalAfter: totalBefore };
    }
    // Identify protected messages: system prompt, any containing tool results, and the last few exchanges.
    const protectedIdx = new Set();
    for (let i = 0; i < messages.length; i++) {
      const m = messages[i];
      if (m.role === 'system') protectedIdx.add(i);
      // Check for tool results: role 'tool' or content containing tool markers.
      if (m.role === 'tool' || (m.tool_call_id) ||
          (typeof m.content === 'string' && m.content.includes('tool_result'))) {
        protectedIdx.add(i);
      }
    }
    // Protect the last 3 exchanges (user + assistant pairs, up to 6 messages).
    const lastN = Math.min(messages.length, 6);
    for (let i = messages.length - lastN; i < messages.length; i++) {
      protectedIdx.add(i);
    }
    // Build pruned array: keep only protected messages.
    const kept = messages.filter((_, idx) => protectedIdx.has(idx));
    const pruned = totalBefore - kept.length;
    // Log compression stats.
    const afterTokens = kept.reduce((acc, m) => acc + estimateTokens(String(m.content || '')), 0);
    logger.info('[compressConversation] pruned messages', {
      totalBefore,
      totalAfter: kept.length,
      pruned,
      tokensBefore: totalTokens,
      tokensAfter: afterTokens
    });
    // Replace original array content (mutation) and return stats.
    messages.length = 0;
    messages.push(...kept);
    return { kept: kept.length, pruned, totalBefore, totalAfter: kept.length };
  } catch (e) {
    logger.warn('[compressConversation] failed', { error: e.message });
    return { error: e.message };
  }
}

// Automatically integrate compressConversation into addMessage: decorate the conversationLogger
// so that after each push, we run compression on the session's message array if needed.
// This is a one-time decoration that preserves the original addMessage behavior.
let _decorated = false;
function _decorateAddMessage() {
  if (_decorated) return;
  _decorated = true;
  // If conversationLogger has an addMessage method, wrap it.
  if (typeof conversationLogger.addMessage === 'function') {
    const originalAddMessage = conversationLogger.addMessage.bind(conversationLogger);
    conversationLogger.addMessage = function(...args) {
      const result = originalAddMessage(...args);
      // Attempt to get the session's message array for compression.
      try {
        // The sessionId is usually the last argument or a property of the message object.
        let sessionId = 'default';
        const lastArg = args[args.length - 1];
        if (typeof lastArg === 'object' && lastArg !== null) {
          sessionId = lastArg.sessionId || lastArg.metadata?.sessionId || sessionId;
        }
        const messages = conversationLogger.getRecentHistoryAcrossDays(400) || [];
        const sessionMessages = messages.filter(m => String(m.metadata?.sessionId || 'default') === String(sessionId));
        if (sessionMessages.length > 0) {
          // Convert to a mutable array for compressConversation to modify.
          const mutableMessages = [...sessionMessages];
          const stats = compressConversation(mutableMessages);
          if (stats.pruned > 0) {
            logger.info('[compressConversation] post-addMessage compression', { sessionId, stats });
          }
        }
      } catch (e) {
        // Best-effort: don't break message logging.
      }
      return result;
    };
  }
}

// Initialize decoration once at module load.
_decorateAddMessage();

export { summaryFor, lineage, maybeCompress, compressConversation };
export default { summaryFor, lineage, maybeCompress, compressConversation };

