// voiceBus — a tiny in-process pub/sub so internal modules (conversationLogger,
// toolsService, /respond) can publish "what AVA is doing" events without importing
// the voice route (avoids circular imports). voice.js subscribes and fans these out
// to connected WebSocket UI clients.
import { EventEmitter } from 'events';
import pythonWorker from './pythonWorker.js';

const bus = new EventEmitter();
bus.setMaxListeners(100);

/**
 * Publish a voice/activity event. Shape matches what voice.js broadcasts:
 *   { type, timestamp(sec), data, source }
 */
export function emitVoiceEvent(type, data = {}, source = 'server') {
  const event = { type, timestamp: Date.now() / 1000, data: data || {}, source };
  try { bus.emit('event', event); } catch { /* never let telemetry break the caller */ }
  return event;
}

export function onVoiceEvent(handler) {
  bus.on('event', handler);
}

// ---- foreground window awareness ----
let _cachedForeground = null;
let _cachedForegroundTime = 0;
const TTL_FOREGROUND = 5000; // 5 seconds

/**
 * Call the existing window_ops.get_foreground tool via pythonWorker.sendCommand,
 * cache the result with a 5-second TTL, and return { title, process, pid }.
 * Falls back gracefully to empty fields if the tool is unavailable or returns errors.
 */
export async function getForegroundInfo() {
  const now = Date.now();
  if (_cachedForeground && (now - _cachedForegroundTime < TTL_FOREGROUND)) {
    return _cachedForeground;
  }
  try {
    const result = await pythonWorker.sendCommand('window_ops.get_foreground', {});
    let windowInfo = {};
    if (result && typeof result === 'object') {
      const data = result.data || result;
      windowInfo = {
        title: data.title || data.window_title || '',
        process: data.process || data.process_name || '',
        pid: data.pid || data.process_id || 0
      };
    } else if (typeof result === 'string') {
      windowInfo = { title: result, process: '', pid: 0 };
    }
    _cachedForeground = windowInfo;
    _cachedForegroundTime = now;
    return windowInfo;
  } catch (err) {
    // Tool not available or request failed — return empty info
    const fallback = { title: '', process: '', pid: 0 };
    _cachedForeground = fallback;
    _cachedForegroundTime = now;
    return fallback;
  }
}

// Expose the cache as a property mirror for convenience (e.g., direct read from other modules)
export const lastForeground = () => _cachedForeground ? { ..._cachedForeground } : null;

export default bus;

