  async executeBuiltinTool(name, args, dryRun = false) {
    if (dryRun) {
      return { ok: true, dry_run: true, would_execute: { name, args } };
    }

    switch (name) {
      case 'status':
        return {
          ok: true,
          result: {
            status: 'healthy',
            uptime: process.uptime(),
            memory: process.memoryUsage(),
            node_version: process.version,
            platform: process.platform,
            timestamp: new Date().toISOString()
          }
        };

      case 'memory_search':
        // Full-text search over curated memory (USER.md/MEMORY.md) + conversation logs.
        try {
          const out = memorySearch.search(args.query || args.q || '', args.limit || 8);
          return { ok: true, result: out };
        } catch (e) {
          return { ok: false, result: { status: 'error', message: e.message } };
        }

