      case 'commitment':
        try {
          const act = (args.action || 'list').toLowerCase();
          if (act === 'add') { const c = commitments.add(args.text, { due: args.due }); return { ok: true, result: c ? { added: c.text, id: c.id } : { error: 'nothing to add' } }; }
