    const e = { hash: fresh[i].hash, text: fresh[i].text, source: source || url, url, topic, jurisdiction, retrievedAt: at, vec: vecs[i] };
    idx.push(e);
    try { fs.appendFileSync(KB_PATH, JSON.stringify(e) + '\n'); stored++; } catch { /* ignore */ }
