// Simple relevance scoring helpers for curiosity tasks
// Augmented with execution-history context for per-agent decay-based bonus
// Also uses engagement signals (interruptions, repeated questions, tool retries) for real curiosity prioritization

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

// Stores per-agent execution results: agentId -> [{success:bool, timestamp:ms}]
const executionHistory = new Map();

// Engagement signals per topic (lowercased text): { interruptionCount, repeatCount, toolRetryCount, lastAsked }
const engagementSignals = new Map();

// Records an observable engagement signal for a given topic text
/**
 * @param {string} text - topic or query text
 * @param {'interruption'|'repeat'|'tool_retry'} signalType
 */
export function recordEngagementSignal(text, signalType) {
  if (!text) return;
  const key = text.toLowerCase().trim();
  if (!engagementSignals.has(key)) {
    engagementSignals.set(key, { interruptionCount: 0, repeatCount: 0, toolRetryCount: 0, lastAsked: 0 });
  }
  const signal = engagementSignals.get(key);
  if (signalType === 'interruption') signal.interruptionCount++;
  else if (signalType === 'repeat') signal.repeatCount++;
  else if (signalType === 'tool_retry') signal.toolRetryCount++;
  signal.lastAsked = Date.now();
}

// Clears engagement signals (for testing or reset)
export function clearEngagementSignals() {
  engagementSignals.clear();
}

// Computes a curiosity score for a topic based on engagement signals and execution history
// Returns a number 0..1
function _computeEngagementScore(text) {
  if (!text) return 0;
  const key = text.toLowerCase().trim();
  const signal = engagementSignals.get(key);
  if (!signal) return 0;
  const now = Date.now();
  const ageHours = (now - signal.lastAsked) / 3600000;
  // Strong recency weight: decay halflife 4 hours
  const recencyWeight = Math.max(0, 1 - ageHours / 4);
  const interruptionBoost = Math.min(1, signal.interruptionCount * 0.3);
  const repeatBoost = Math.min(1, signal.repeatCount * 0.2);
  const retryBoost = Math.min(1, signal.toolRetryCount * 0.25);
  const raw = recencyWeight * (0.4 + interruptionBoost + repeatBoost + retryBoost);
  return Math.max(0, Math.min(1, raw));
}

// Records an execution outcome for a given agent for later scoring influence
/**
 * @param {string} agentId
 * @param {boolean} success
 */
// Updated to also capture tool retry as an engagement signal if agentId looks like a topic
/**
 * @param {string} agentId - may be a topic text or agent identifier
 * @param {boolean} success
 */
export function recordExecution(agentId, success) {
  if (!agentId) return;
  // If the agentId looks like natural language (has spaces), treat as topic signal
  if (agentId.includes(' ') && !success) {
    recordEngagementSignal(agentId, 'tool_retry');
  }

  if (!agentId) return;
  if (!executionHistory.has(agentId)) {
    executionHistory.set(agentId, []);
  }
  const entries = executionHistory.get(agentId);
  // Keep last 20 entries for scoring
  entries.push({ success, timestamp: Date.now() });
  if (entries.length > 20) entries.shift();
}

// Clears execution history for a given agent (useful for reset or testing)
export function clearHistory(agentId) {
  if (agentId) {
    executionHistory.delete(agentId);
  } else {
    executionHistory.clear();
  }
}

// Get the decay-based modifier from execution history: reward recent successes, penalize consecutive failures
function _getHistoryModifier(agentId) {
  // No longer used directly; kept for backward compatibility. Use scoreCuriosity instead.

  if (!agentId || !executionHistory.has(agentId)) return 0;
  const entries = executionHistory.get(agentId);
  // Apply time-based decay: recent 60s = full weight, older entries fade linearly
  const now = Date.now();
  const DECAY_MS = 60_000;
  let weightedSuccess = 0;
  let totalWeight = 0;
  for (const e of entries) {
    const age = now - e.timestamp;
    const weight = age <= DECAY_MS ? (1 - age / DECAY_MS) : 0;
    if (weight <= 0) continue;
    weightedSuccess += (e.success ? 1 : 0) * weight;
    totalWeight += weight;
  }
  // Count consecutive failures at the tail (most recent entries, up to last 5)
  let consecutiveFailures = 0;
  for (let i = entries.length - 1; i >= 0 && i >= entries.length - 5; i--) {
    if (!entries[i].success) consecutiveFailures++;
    else break;
  }
  // Decay penalty: -0.15 per consecutive failure beyond 3
  const failPenalty = consecutiveFailures > 3 ? (consecutiveFailures - 3) * -0.15 : 0;
  // Boost if most recent weighted success ratio is high (>80%)
  let successRatio = totalWeight > 0 ? weightedSuccess / totalWeight : 0.5;
  const boostBonus = successRatio > 0.8 ? 0.2 : 0;
  return failPenalty + boostBonus;
}

export function computeRelevanceScore(text = '', query = '', agentId = '') {
  if (!text || !query) return 0.5; // neutral
  const base = jaccardSim(text, query); // 0..1
  const modifier = _getHistoryModifier(agentId); // -0.6 .. +0.2
  const engScore = _computeEngagementScore(text); // 0..1
  const result = Math.max(0, Math.min(1, base + modifier + engScore * 0.3));
  return result;
}

export function scoreCuriosity(text, signals) {
  /**
   * Real curiosity score that uses engagement signals and execution history.
   * @param {string} text - topic text to score
   * @param {object} [signals] - optional override signals (for testing)
   * @returns {number} 0..1
   */
  if (!text) return 0;
  const engScore = _computeEngagementScore(text);
  if (signals) {
    // Allow override for testing or manual boost
    const overrides = Object.assign({ interruptionCount: 0, repeatCount: 0, toolRetryCount: 0, lastAsked: 0 }, signals);
    const fakeSignal = overrides;
    const now = Date.now();
    const ageHours = (now - fakeSignal.lastAsked) / 3600000;
    const recencyWeight = Math.max(0, 1 - ageHours / 4);
    const interruptionBoost = Math.min(1, fakeSignal.interruptionCount * 0.3);
    const repeatBoost = Math.min(1, fakeSignal.repeatCount * 0.2);
    const retryBoost = Math.min(1, fakeSignal.toolRetryCount * 0.25);
    return Math.max(0, Math.min(1, recencyWeight * (0.4 + interruptionBoost + repeatBoost + retryBoost)));
  }
  return engScore;
}

export default { tokenize, jaccardSim, computeRelevanceScore, recordExecution, clearHistory, recordEngagementSignal, clearEngagementSignals, scoreCuriosity };

