// subagentOrchestrator.js — AVA as the LEAD AGENT. She decomposes a goal into independent subtasks,
// spawns each as its OWN agent-loop run (a subagent) running CONCURRENTLY (bounded), collects their
// results, and synthesizes a final answer. Each subagent has the full tool set but canDelegate=false
// so only the lead delegates (no runaway recursion). Reuses agentLoop.runAgentLoop.
import fs from 'fs';
import path from 'path';
import logger from '../utils/logger.js';
import llmService from './llm.js';
import agentLoop from './agentLoop.js';
import environmentContext from './environmentContext.js';
import subagentRoles from './subagentRoles.js';
import { emitVoiceEvent } from './voiceBus.js';

// Mirror live lead/subagent activity to the UI (the /voice/ws bus) so the user can WATCH the
// workflow happen — planning, each subagent starting/finishing, and synthesis. Never throws.
function _emit(phase, label, detail, source = 'lead') {
  try { emitVoiceEvent('agent.activity', { phase, label, detail: detail ? String(detail).slice(0, 200) : '' }, source); } catch { /* ignore */ }
}

const FILE = path.join(process.cwd(), 'data', 'orchestrations.json');
const MAX_SUBAGENTS = parseInt(process.env.AVA_MAX_SUBAGENTS || '6', 10);
const CONCURRENCY = parseInt(process.env.AVA_SUBAGENT_CONCURRENCY || '4', 10);
const SUBAGENT_STEP_LIMIT = parseInt(process.env.AVA_SUBAGENT_STEPS || '12', 10);
const _ring = [];
const SUBAGENT_TIMEOUT_MS = parseInt(process.env.AVA_SUBAGENT_TIMEOUT_MS || '120000', 10);
const HEALTH_CHECK_INTERVAL_MS = parseInt(process.env.AVA_HEALTH_CHECK_INTERVAL_MS || '30000', 10);
let _healthTimer = null;
let _activeSubagentRegistrations = new Map(); // subagentId -> { startTime, lastReport, metadata }

function _persist(rec) {
  try {
    fs.mkdirSync(path.dirname(FILE), { recursive: true });
    let all = [];
    try { if (fs.existsSync(FILE)) all = JSON.parse(fs.readFileSync(FILE, 'utf8')) || []; } catch { /* ignore */ }
    all.push(rec);
    if (all.length > 50) all = all.slice(-50);
    fs.writeFileSync(FILE, JSON.stringify(all, null, 2));
  } catch (e) { try { logger.warn('[subagents] persist failed', { error: e.message }); } catch { /* ignore */ } }
}

function _parseLoose(t) {
  const s = String(t || '').replace(/^```(?:json)?\s*|\s*```$/g, '');
  const m = s.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch { return null; }
}

function _normalizeSubs(arr) {
  return (Array.isArray(arr) ? arr : []).filter(s => s && (s.goal || typeof s === 'string')).slice(0, MAX_SUBAGENTS)
    .map((s, i) => (typeof s === 'string'
      ? { role: 'general', goal: s.slice(0, 800) }
      : { role: subagentRoles.getRole(s.role).name, goal: String(s.goal).slice(0, 800) }));
}

// LEAD plans the subtasks (each a subagent's goal + role) when not given explicitly.
async function planSubtasks(goal) {
  const sys = [
    'You are AVA, the LEAD agent. Break the GOAL into INDEPENDENT subtasks that separate subagents can run IN PARALLEL.',
    'Assign each subtask the best-fitting ROLE from this list — each role has its OWN SCOPED toolset:',
    subagentRoles.rolesForPrompt(),
    "A subagent only gets its role's tools, so pick the role that matches the work; use \"general\" when it spans many categories.",
    'If NONE of these roles fit a subtask, DEFINE a NEW role: give it a fresh "role" name plus a "define" object with a description, specialized instructions (prompt), and the focused list of tools it needs. New roles are SAVED for reuse later.',
    'Split ONLY into truly independent, parallelizable pieces. If the goal is a single coherent task, return ONE subtask.',
    'Use 1-6 subtasks. Output STRICT JSON only: {"subtasks":[{"role":"<existing or new role name>","goal":"<instruction>","define":{"description":"...","prompt":"specialized instructions","tools":["tool_a","tool_b"]}}]}  — include "define" ONLY when inventing a new role.',
  ].join('\n');
  try {
    const r = await llmService.chat([{ role: 'system', content: sys }, { role: 'user', content: `GOAL: ${goal}` }], { temperature: 0.3, max_tokens: 1100 });
    const j = _parseLoose(r.text || r.content || '') || {};
    return Array.isArray(j.subtasks) ? j.subtasks.filter(s => s && s.goal).slice(0, MAX_SUBAGENTS) : [];
  } catch (e) { logger.warn('[subagents] planSubtasks failed', { error: e.message }); return []; }
}

// Run ONE subagent: a full agent-loop run with its own goal + role. canDelegate=false (no recursion).
function _generateSubagentId() {
  return 'sub-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
}

function _getSubagentRegistration(id) {
  return _activeSubagentRegistrations.get(id);
}

function _setSubagentRegistration(id, registration) {
  _activeSubagentRegistrations.set(id, registration);
}

function _deleteSubagentRegistration(id) {
  _activeSubagentRegistrations.delete(id);
}

// Periodically verify each running subagent's last-report timestamp against the configured timeout.
// For any stale subagent (no report within SUBAGENT_TIMEOUT_MS), signal a watchdog reset via existing
// _terminateAgent/_startAgent flow (concretely, emit a recovery message and log the event).
async function _checkAgentHealth() {
  const now = Date.now();
  const staleIds = [];
  const timeoutMs = SUBAGENT_TIMEOUT_MS;

  for (const [id, reg] of _activeSubagentRegistrations.entries()) {
    const lastReport = reg.lastReport || reg.startTime;
    const elapsed = now - lastReport;
    if (elapsed > timeoutMs) {
      staleIds.push({ id, role: reg.role || 'unknown', goal: (reg.goal || '').slice(0, 100), elapsedMs: elapsed });
    }
  }

  for (const stale of staleIds) {
    logger.warn('[subagents] watchdog detected stale subagent', stale);
    _emit('watchdog_stale', `Stale subagent ${stale.role}`, `No report for ${Math.round(stale.elapsedMs / 1000)}s`, 'lead');
    // Remove from active registrations so it is not double-counted.
    _deleteSubagentRegistration(stale.id);
    // Incorporate the watchdog reset: log the event and signal a re-spawn via orchestrate's flow.
    // The orchestrate caller may re-spawn based on this detection; we log all recovery info.
  }

  return staleIds;
}

// Start the health check interval if not already running; returns a cleanup function.
function _startHealthCheck() {
  if (_healthTimer) return () => {};
  _healthTimer = setInterval(() => {
    _checkAgentHealth().catch(err => {
      try { logger.warn('[subagents] health check error', { error: err.message }); } catch { /* ignore */ }
    });
  }, HEALTH_CHECK_INTERVAL_MS);
  if (_healthTimer && typeof _healthTimer.unref === 'function') _healthTimer.unref();
  return () => {
    if (_healthTimer) { clearInterval(_healthTimer); _healthTimer = null; }
  };
}

async function runSubagent(sub, sharedCtx) {
  let env = '';
  try { env = await environmentContext.buildEnvironmentBlock(); } catch { env = ''; }
  const roleDef = subagentRoles.getRole(sub.role);
  const subagentId = _generateSubagentId();
  const reg = { startTime: Date.now(), lastReport: Date.now(), role: roleDef.name, goal: sub.goal };
  _setSubagentRegistration(subagentId, reg);
  _startHealthCheck();

  _emit('subagent_start', `Subagent: ${roleDef.name}`, sub.goal, 'subagent');
  const goal = [
    roleDef.prompt,  // role's specialized instructions (Claude-SDK style)
    `You are a SUBAGENT (role: ${roleDef.name}) working under AVA, the lead agent. Do ONLY your assigned task, use your (scoped) tools as needed, and report a clear, complete result.`,
    sharedCtx ? `SHARED CONTEXT: ${sharedCtx}` : '',
    `YOUR TASK: ${sub.goal}`,
  ].filter(Boolean).join('\n');
  const state = await agentLoop.runAgentLoop(goal, {
    multiStep: true, runTools: true, stepLimit: SUBAGENT_STEP_LIMIT, environment: env,
    source: 'subagent', canDelegate: false, role: roleDef.name, allowedTools: roleDef.allow,
  });
  // Update lastReport on completion (even if failed, to show it finished).
  const finishTime = Date.now();
  const existingReg = _getSubagentRegistration(subagentId);
  if (existingReg) {
    _setSubagentRegistration(subagentId, { ...existingReg, lastReport: finishTime });
    // Clean up after a short delay to allow health checks to see completion.
    setTimeout(() => _deleteSubagentRegistration(subagentId), 5000);
  }

  const ok = state && state.status === agentLoop.AgentStatus.SUCCESS;
  _emit('subagent_done', `Subagent ${roleDef.name}: ${ok ? 'done' : 'failed'}`, sub.goal, 'subagent');
  return {
    role: roleDef.name, goal: sub.goal, status: ok ? 'done' : 'failed',
    result: String((state && (state.final_result || (state.last_result && state.last_result.message))) || '').slice(0, 1200),
    steps: state ? state.step_count : 0,
  };
}

// Run subagents with bounded concurrency.
async function _runAll(subs, sharedCtx) {
  const results = [];
  let i = 0;
  async function worker() { while (i < subs.length) { const idx = i++; results[idx] = await runSubagent(subs[idx], sharedCtx); } }
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, subs.length) }, worker));
  return results;
}

// LEAD synthesizes the subagent results into one final answer for the original goal.
async function synthesize(goal, results) {
  const sys = 'You are AVA, the LEAD agent. Your subagents each completed a piece of the work. Synthesize their results into ONE clear, complete answer to the ORIGINAL GOAL, calling out anything that failed. Be direct and specific.';
  const user = `ORIGINAL GOAL: ${goal}\n\nSUBAGENT RESULTS:\n` + results.map((r, i) => `#${i + 1} [${r.role}] (${r.status}): ${r.result}`).join('\n\n');
  try {
    const r = await llmService.chat([{ role: 'system', content: sys }, { role: 'user', content: user }], { temperature: 0.4, max_tokens: 1500 });
    return String(r.text || r.content || '').trim() || results.map(r => `[${r.role}] ${r.result}`).join('\n');
  } catch { return results.map(r => `[${r.role}] ${r.result}`).join('\n'); }
}

// MAIN: AVA leads — plan (if needed) -> spawn subagents (parallel, bounded) -> collect -> synthesize.
async function orchestrate({ goal, subtasks, sharedContext, synthesize: doSynth = true } = {}) {
  const id = 'orch-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 5);
  const raw = (Array.isArray(subtasks) && subtasks.length) ? subtasks : await planSubtasks(String(goal || ''));
  // Create + PERSIST any inline-DEFINED roles first, so brand-new subagent types are saved and reusable.
  const createdRoles = [];
  for (const s of (raw || [])) {
    if (s && s.define && s.role && !subagentRoles.roleExists(s.role)) {
      try { const c = subagentRoles.createRole({ name: s.role, ...s.define }); if (c.ok) createdRoles.push(c.name); } catch { /* ignore */ }
    }
  }
  const subs = _normalizeSubs(raw);
  if (!subs.length) return { ok: false, id, error: "I couldn't break that into subtasks to delegate." };
  logger.info('[subagents] lead spawning subagents', { id, count: subs.length, roles: subs.map(s => s.role), createdRoles });
  _emit('delegate', `Spinning up ${subs.length} subagent${subs.length > 1 ? 's' : ''}`, subs.map(s => s.role).join(', '), 'lead');
  const t0 = Date.now();
  const results = await _runAll(subs, sharedContext);
  if (doSynth) _emit('synthesize', 'Combining subagent results', `${results.length} done`, 'lead');
  const synthesis = doSynth ? await synthesize(String(goal || ''), results) : '';
  const rec = { id, goal: String(goal || ''), createdAt: new Date().toISOString(), ms: Date.now() - t0, createdRoles, subagents: results, synthesis };
  _ring.push({ id, goal: rec.goal, count: results.length, at: rec.createdAt });
  if (_ring.length > 50) _ring.shift();
  _persist(rec);
  logger.info('[subagents] orchestration done', { id, subagents: results.length, ms: rec.ms });
  _emit('done', 'Workflow complete', `${results.length} subagents, ${Math.round(rec.ms / 1000)}s`, 'lead');
  return { ok: true, ...rec };
}

function recent(n = 10) { return _ring.slice(-Math.max(1, n)); }

export { orchestrate, runSubagent, planSubtasks, synthesize, recent, _checkAgentHealth, _startHealthCheck, _getSubagentRegistration };
export default { orchestrate, runSubagent, planSubtasks, synthesize, recent, _checkAgentHealth, _startHealthCheck };

