// voiceBus — a tiny in-process pub/sub so internal modules (conversationLogger,
// toolsService, /respond) can publish "what AVA is doing" events without importing
// the voice route (avoids circular imports). voice.js subscribes and fans these out
// to connected WebSocket UI clients.
import { EventEmitter } from 'events';

const bus = new EventEmitter();
bus.setMaxListeners(100);

// Cache for foreground application info with TTL
let cachedForegroundApp = null;
let cachedForegroundAppExpiry = 0;
const CACHE_TTL_MS = 2000;

/**
 * Fetch and cache the currently active foreground application info.
 * Uses the confirmed pythonWorker.sendCommand('get_foreground_info') API.
 * Returns { title, process, pid } or null on failure.
 */
function getCachedForegroundApp() {
  const now = Date.now();
  if (cachedForegroundApp && now < cachedForegroundAppExpiry) {
    return cachedForegroundApp;
  }
  // Lazy-import to avoid circular dependency at module top level
  const { default: pythonWorker } = require('./pythonWorker.js');
  try {
    const result = pythonWorker.sendCommand('get_foreground_info', {});
    if (result && (result.title || result.process || result.pid)) {
      cachedForegroundApp = { title: result.title || null, process: result.process || null, pid: result.pid || null };
      cachedForegroundAppExpiry = now + CACHE_TTL_MS;
    } else {
      cachedForegroundApp = null;
      cachedForegroundAppExpiry = 0;
    }
  } catch {
    cachedForegroundApp = null;
    cachedForegroundAppExpiry = 0;
  }
  return cachedForegroundApp;
}

/**
 * Publish a voice/activity event. Shape matches what voice.js broadcasts:
 *   { type, timestamp(sec), data, source }
 * Automatically enriches bufferedAudio events with foreground app context.
 */
export function emitVoiceEvent(type, data = {}, source = 'server') {
  // Enrich bufferedAudio segments with live foreground application info
  if (type === 'bufferedAudio' && data) {
    const fg = getCachedForegroundApp();
    if (fg && (fg.title || fg.process || fg.pid)) {
      data.foregroundApp = fg;
    }
  }
  const event = { type, timestamp: Date.now() / 1000, data: data || {}, source };
  try { bus.emit('event', event); } catch { /* never let telemetry break the caller */ }
  return event;
}

export function onVoiceEvent(handler) {
  bus.on('event', handler);
}

export default bus;

