// turnGuard.js -- clean task-switch / interrupt handling + fullscreen concurrency gate.
// Each conversational turn for a session gets a monotonically increasing token. If a NEWER turn
// begins for the same session while an older one is still working (barge-in, or the user types
// while voice is mid-thought), the older turn detects it's been superseded at its emit point and
// drops its now-stale reply instead of speaking over the new one. In-memory only, per session.
// Also blocks tool execution when the foreground window is a blocked fullscreen app (games,
// presentations, screen-sharing) unless explicitly permitted via a per-session override.
const _gen = new Map();
const _pending = new Map(); // sessionId -> Set<token>

// ---- Fullscreen concurrency gate ----
// Blocklist: normalized process names (lowercase) that should block tool execution
// when they own the foreground fullscreen window.
const _blockedApps = new Set([
  'presentation_host.exe',    // common presentation apps
  'screenconnect.exe',        // screen-sharing
  'teamviewer.exe',           // remote desktop
  'anydesk.exe',
  'zoom.exe',
  'chrome.exe'                // fullscreen YouTube/Netflix in Chrome
]);

// Per-session overrides: if true, fullscreen gate is disabled for that session.
const _sessionOverride = new Map(); // sessionId -> boolean

// Lazily cached pythonWorker instance (set once via configure).
let _pythonWorker = null;

// Cache foreground info within a turn to avoid repeated sendCommand calls.
let _fgCache = null; // { title, process, pid } or null if stale
let _fgCacheTurn = null; // the begin() token for which cache is valid

// Internal helper: fetch foreground window info using pythonWorker.sendCommand.
// Returns { title, process, pid } or null on failure.
async function _fetchForegroundInfo() {
  if (!_pythonWorker) return null;
  try {
    const result = await _pythonWorker.sendCommand('window_ops.get_foreground_info', {});
    if (!result || typeof result !== 'object') return null;
    return {
      title: (result.title || '').toLowerCase(),
      process: (result.process || result.process_name || result.processPath || '').toLowerCase(),
      pid: result.pid || 0
    };
  } catch (e) {
    // Silently fail if the window_ops tool is not available; gate remains open.
    return null;
  }
}

// Check whether the current foreground window should block tool execution.
// Returns a block message string if blocked, or null if allowed.
async function _checkForegroundBlock(sessionId) {
  // If session has override allowing fullscreen tools, skip check.
  if (_sessionOverride.get(String(sessionId || 'default'))) return null;

  // Fetch foreground info (with per-turn caching).
  const s = String(sessionId || 'default');
  const currentToken = _gen.get(s) || 0;
  if (_fgCacheTurn !== currentToken) {
    _fgCache = await _fetchForegroundInfo();
    _fgCacheTurn = currentToken;
  }
  if (!_fgCache) return null;

  const { title, process, pid } = _fgCache;
  // Check if the process is in our blocklist.
  if (!_blockedApps.has(process)) return null;

  // If the window is not actually fullscreen (e.g., small windowed mode), allow.
  // We check this by seeing if the title is very short (likely just app name) OR
  // the window has no recognizable fullscreen indicators. Since we don't have
  // window geometry from get_foreground_info, we use a heuristic: if the title
  // contains a common fullscreen indicator substring or is very brief.
  const fullscreenIndicators = ['presentation', 'slideshow', 'full screen', 'screen share',
    'remote control', 'meeting'];
  const hasIndicator = fullscreenIndicators.some(ind => title.includes(ind));
  // Also block if title is extremely short (likely just the app name, common in games).
  const isBriefTitle = title.length < 20 && !title.includes(' - ');

  if (!hasIndicator && !isBriefTitle) return null;

  return `[FULLSCREEN BLOCK] Foreground app "${process}" (PID ${pid}) is a blocked fullscreen application. ` +
    `Tool execution paused until user switches away or permits this session via turnGuard.allowFullscreenTools("${sessionId}").`;
}

// ---- Public API ----

export function configure(pythonWorkerInstance) {
  _pythonWorker = pythonWorkerInstance;
}

// Add or remove a process from the fullscreen blocklist.
export function blockApp(processName) {
  _blockedApps.add(processName.toLowerCase());
}
export function unblockApp(processName) {
  _blockedApps.delete(processName.toLowerCase());
}
export function isAppBlocked(processName) {
  return _blockedApps.has(processName.toLowerCase());
}
export function listBlockedApps() {
  return Array.from(_blockedApps);
}

// Permit tools during fullscreen for a specific session (e.g., when user explicitly confirms).
export function allowFullscreenTools(sessionId) {
  _sessionOverride.set(String(sessionId || 'default'), true);
}
export function disallowFullscreenTools(sessionId) {
  _sessionOverride.set(String(sessionId || 'default'), false);
}
export function areFullscreenToolsAllowed(sessionId) {
  return !!_sessionOverride.get(String(sessionId || 'default'));
}

export function begin(sessionId) {
  const s = String(sessionId || 'default');
  const n = (_gen.get(s) || 0) + 1;
  _gen.set(s, n);
  // Track this token as pending; any prior pending tokens for this session remain tracked
  // but will be auto-dropped when they emit and fail isCurrent. Also clean up old pending.
  if (!_pending.has(s)) _pending.set(s, new Set());
  _pending.get(s).add(n);
  // Invalidate foreground cache for the new turn.
  _fgCache = null;
  _fgCacheTurn = null;
  return n;
}

// True if `token` is still the latest turn for this session (i.e. not superseded).
export function isCurrent(sessionId, token) {
  return (_gen.get(String(sessionId || 'default')) || 0) === token;
}

// Register that a completion (belonging to `token`) has finished emitting (success or discard).
// This removes it from the pending set to allow eventual GC of the session's pending set.
export function complete(sessionId, token) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  if (set) {
    set.delete(token);
    if (set.size === 0) _pending.delete(s);
  }
}

// Returns the number of pending (in-flight) completions for a session, useful for diagnostic logging.
export function pendingCount(sessionId) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  return set ? set.size : 0;
}

// Check if tools should be blocked for the given session due to fullscreen app.
// Returns null if allowed, or a block reason string if blocked.
export async function checkToolBlocked(sessionId) {
  return await _checkForegroundBlock(sessionId);
}

export default { begin, isCurrent, complete, pendingCount, configure, blockApp, unblockApp,
  isAppBlocked, listBlockedApps, allowFullscreenTools, disallowFullscreenTools,
  areFullscreenToolsAllowed, checkToolBlocked };

