// Multi-signal curiosity scoring for self-improvement prioritization
// Incorporates self-reflection loops, proposal outcomes, and rejection reasons.
// Augmented with execution-history context for per-agent decay-based bonus

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

// Stores per-agent execution results: agentId -> [{success:bool, timestamp:ms}]
const executionHistory = new Map();

// Reflection loops: agentId -> {topic -> count}
const reflectionLoops = new Map();

// Proposal outcomes: topic -> {accepted: number, rejected: number, reasons: string[]}
const proposalResults = new Map();

// Rejection penalty map: repeated reason strings -> penalty boost
const rejectionPenalties = new Map();

// Records an execution outcome for a given agent for later scoring influence
/**
 * @param {string} agentId
 * @param {boolean} success
 */
export function recordExecution(agentId, success) {
  if (!agentId) return;
  if (!executionHistory.has(agentId)) {
    executionHistory.set(agentId, []);
  }
  const entries = executionHistory.get(agentId);
  // Keep last 20 entries for scoring
  entries.push({ success, timestamp: Date.now() });
  if (entries.length > 20) entries.shift();
}

// Clears execution history for a given agent (useful for reset or testing)
export function clearHistory(agentId) {
  if (agentId) {
    executionHistory.delete(agentId);
  } else {
    executionHistory.clear();
  }
}

// Records a self-reflection loop occurrence for a topic
/**
 * @param {string} agentId
 * @param {string} topic
 */
export function recordReflectionLoop(agentId, topic) {
  if (!agentId || !topic) return;
  if (!reflectionLoops.has(agentId)) {
    reflectionLoops.set(agentId, new Map());
  }
  const topicMap = reflectionLoops.get(agentId);
  const count = (topicMap.get(topic) || 0) + 1;
  topicMap.set(topic, count);
}

// Records proposal outcome for a topic
/**
 * @param {string} topic
 * @param {boolean} accepted - true if proposal was accepted
 * @param {string} [rejectionReason] - reason if rejected
 */
export function recordProposalOutcome(topic, accepted, rejectionReason = '') {
  if (!topic) return;
  if (!proposalResults.has(topic)) {
    proposalResults.set(topic, { accepted: 0, rejected: 0, reasons: [] });
  }
  const entry = proposalResults.get(topic);
  if (accepted) {
    entry.accepted++;
  } else {
    entry.rejected++;
    if (rejectionReason) {
      entry.reasons.push(rejectionReason);
      // Track repeated rejection reasons for extra penalty
      const cleanReason = rejectionReason.toLowerCase().replace(/[^a-z ]/g, '').trim();
      if (rejectionPenalties.has(cleanReason)) {
        rejectionPenalties.set(cleanReason, rejectionPenalties.get(cleanReason) + 1);
      } else {
        rejectionPenalties.set(cleanReason, 1);
      }
    }
  }
}

// Clears all recorded signals for a given agent
/**
 * @param {string} [agentId]
 */
export function clearAllSignals(agentId) {
  if (agentId) {
    executionHistory.delete(agentId);
    reflectionLoops.delete(agentId);
    // note: proposalResults are topic-based, not agent-scoped, so we don't clear them
  } else {
    executionHistory.clear();
    reflectionLoops.clear();
    proposalResults.clear();
    rejectionPenalties.clear();
  }
}

// Get the decay-based modifier from execution history: reward recent successes, penalize consecutive failures
function _getHistoryModifier(agentId) {
  if (!agentId || !executionHistory.has(agentId)) return 0;
  const entries = executionHistory.get(agentId);
  // Apply time-based decay: recent 60s = full weight, older entries fade linearly
  const now = Date.now();
  const DECAY_MS = 60_000;
  let weightedSuccess = 0;
  let totalWeight = 0;
  for (const e of entries) {
    const age = now - e.timestamp;
    const weight = age <= DECAY_MS ? (1 - age / DECAY_MS) : 0;
    if (weight <= 0) continue;
    weightedSuccess += (e.success ? 1 : 0) * weight;
    totalWeight += weight;
  }
  // Count consecutive failures at the tail (most recent entries, up to last 5)
  let consecutiveFailures = 0;
  for (let i = entries.length - 1; i >= 0 && i >= entries.length - 5; i--) {
    if (!entries[i].success) consecutiveFailures++;
    else break;
  }
  // Decay penalty: -0.15 per consecutive failure beyond 3
  const failPenalty = consecutiveFailures > 3 ? (consecutiveFailures - 3) * -0.15 : 0;
  // Boost if most recent weighted success ratio is high (>80%)
  let successRatio = totalWeight > 0 ? weightedSuccess / totalWeight : 0.5;
  const boostBonus = successRatio > 0.8 ? 0.2 : 0;
  return failPenalty + boostBonus;
}

// Multi-signal relevance score: combines base similarity, execution history, reflection loops, and proposal outcomes.
/**
 * @param {string} text
 * @param {string} query
 * @param {string} [agentId]
 * @param {string} [topic] - optional topic key for reflection/proposal signals
 * @returns {number} 0..1 score
 */
export function computeRelevanceScore(text = '', query = '', agentId = '', topic = '') {
  if (!text || !query) return 0.5; // neutral
  const base = jaccardSim(text, query); // 0..1
  const historyModifier = _getHistoryModifier(agentId); // -0.6 .. +0.2

  // Reflection loop penalty: topics revisited more than twice get up to -0.3
  let reflectionPenalty = 0;
  if (agentId && topic && reflectionLoops.has(agentId)) {
    const topicMap = reflectionLoops.get(agentId);
    const loopCount = topicMap.get(topic) || 0;
    if (loopCount > 2) {
      reflectionPenalty = Math.min((loopCount - 2) * 0.1, 0.3);
    }
  }

  // Proposal outcome modifier: accepted proposals boost +0.2, rejected ones penalize
  let outcomeModifier = 0;
  if (topic && proposalResults.has(topic)) {
    const entry = proposalResults.get(topic);
    const total = entry.accepted + entry.rejected;
    if (total > 0) {
      const acceptRate = entry.accepted / total;
      if (acceptRate >= 0.7) {
        outcomeModifier = 0.2;
      } else if (acceptRate <= 0.3) {
        outcomeModifier = -0.2;
      }
      // Additional penalty if there are repeated rejection reasons
      let repeatPenalty = 0;
      for (const reason of entry.reasons) {
        const cleanReason = reason.toLowerCase().replace(/[^a-z ]/g, '').trim();
        const count = rejectionPenalties.get(cleanReason) || 0;
        if (count > 2) {
          repeatPenalty += (count - 2) * 0.05;
        }
      }
      outcomeModifier = Math.max(outcomeModifier - repeatPenalty, -0.5);
    }
  }

  const totalModifier = historyModifier + reflectionPenalty + outcomeModifier;
  const result = Math.max(0, Math.min(1, base + totalModifier));
  return result;
}

export default { tokenize, jaccardSim, computeRelevanceScore, recordExecution, clearHistory, recordReflectionLoop, recordProposalOutcome, clearAllSignals };

