import fs from 'fs';
import path from 'path';
import { spawn } from 'child_process';
import logger from '../utils/logger.js';
import pythonWorker from './pythonWorker.js';
import { default as llmProvider } from '../llm.js';

let restartScheduled = false;
let healthCheckInterval = null;
let failedHealthChecks = 0;
const MAX_FAILED_CHECKS = 2;
const HEALTH_CHECK_INTERVAL_MS = 60000;
const ECHO_COMMAND = 'json_ops.echo';

function dataDir() {
  return path.join(process.cwd(), 'data');
}

function writeRestartRecord(record) {
  try {
    fs.mkdirSync(dataDir(), { recursive: true });
    fs.writeFileSync(
      path.join(dataDir(), 'pending-server-restart.json'),
      JSON.stringify(record, null, 2),
      'utf8'
    );
  } catch {}
}

function scheduleServerRestart({ reason = 'approved self-modification', delayMs = 2500 } = {}) {
  if (process.env.AVA_SELF_RESTART_OFF === '1') {
    return { scheduled: false, reason: 'disabled by AVA_SELF_RESTART_OFF' };
  }
  if (restartScheduled) {
    return { scheduled: true, alreadyScheduled: true, reason: 'restart already scheduled' };
  }

  const serverEntry = path.join(process.cwd(), 'src', 'server.js');
  const helper = path.join(process.cwd(), 'scripts', 'restart-server-after-delay.cjs');
  if (!fs.existsSync(serverEntry) || !fs.existsSync(helper)) {
    return { scheduled: false, reason: 'restart helper or server entry not found' };
  }

  const record = {
    requestedAt: new Date().toISOString(),
    reason,
    parentPid: process.pid,
    serverEntry,
    delayMs
  };
  writeRestartRecord(record);

  try {
    const child = spawn(process.execPath, [helper, serverEntry, String(delayMs)], {
      cwd: process.cwd(),
      detached: true,
      stdio: 'ignore',
      env: { ...process.env, AVA_RESTART_PARENT_PID: String(process.pid) }
    });
    child.unref();
    restartScheduled = true;
    logger.warn('[selfRestart] server restart scheduled', record);
    setTimeout(() => process.exit(0), 700);
    return { scheduled: true, delayMs, reason };
  } catch (e) {
    logger.warn('[selfRestart] failed to schedule server restart', { error: e.message });
    return { scheduled: false, reason: e.message };
  }
}

function _checkProviderHealth() {
  const health = { pythonWorker: false, llm: false };
  return new Promise((resolve) => {
    let resolved = false;
    const resolveOnce = (ok) => {
      if (!resolved) { resolved = true; resolve(ok); }
    };
    const timeout = setTimeout(() => resolveOnce(false), 8000);
    Promise.all([
      pythonWorker.sendCommand(ECHO_COMMAND, {}).then(() => {
        health.pythonWorker = true;
      }).catch(() => {}),
      (() => {
        try {
          return llmProvider.providerCall({ messages: [{ role: 'user', content: 'ping' }], maxTokens: 8, provider: 'openai' });
        } catch { return Promise.reject(); }
      })().then(() => {
        health.llm = true;
      }).catch(() => {})
    ]).then(() => {
      clearTimeout(timeout);
      resolveOnce(health.pythonWorker && health.llm);
    }).catch(() => {
      clearTimeout(timeout);
      resolveOnce(false);
    });
  });
}

async function _runHealthCheckLoop() {
  logger.info('[selfRestart] health check loop started');
  while (!restartScheduled) {
    try {
      const ok = await _checkProviderHealth();
      if (!ok) {
        failedHealthChecks++;
        logger.warn('[selfRestart] health check failed', { failedHealthChecks, max: MAX_FAILED_CHECKS });
        if (failedHealthChecks >= MAX_FAILED_CHECKS) {
          logger.warn('[selfRestart] max failures reached, scheduling restart');
          scheduleServerRestart({ reason: 'health check failure', delayMs: 5000 });
          return;
        }
      } else {
        failedHealthChecks = 0;
      }
    } catch (e) {
      logger.warn('[selfRestart] health check error', { error: e.message });
    }
    if (restartScheduled) return;
    await new Promise(r => setTimeout(r, HEALTH_CHECK_INTERVAL_MS));
  }
}

function startHealthCheck() {
  if (healthCheckInterval) return;
  healthCheckInterval = setInterval(() => {
    if (!restartScheduled) _runHealthCheckLoop();
  }, HEALTH_CHECK_INTERVAL_MS);
  _runHealthCheckLoop();
}

function stopHealthCheck() {
  if (healthCheckInterval) {
    clearInterval(healthCheckInterval);
    healthCheckInterval = null;
  }
}

export { scheduleServerRestart, startHealthCheck, stopHealthCheck };
export default { scheduleServerRestart, startHealthCheck, stopHealthCheck };

