// Digest Scheduler - auto-flush digest at quiet-hours digest time, with drift-aware cadence alignment
import digestQueue from './digestQueue.js';
import autonomyLib from './autonomyPolicy.js';
import logger from '../utils/logger.js';

const DEFAULT_DIGEST_INTERVAL_MS = 2 * 60 * 60 * 1000; // 2 hours

function hhmm(date = new Date()) {
  const hh = String(date.getHours()).padStart(2, '0');
  const mm = String(date.getMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

function isDigestTime() {
  try {
    const { getAutonomy } = autonomyLib; const autonomy = getAutonomy(logger);
    const policy = autonomy.getPolicy();
    const qh = policy.quiet_hours || {};
    const digest = (qh.during_quiet_hours && qh.during_quiet_hours.digest_time) || '07:15';
    return hhmm() === digest;
  } catch { return false; }
}

function getDigestIntervalMs() {
  const envVal = parseInt(process.env.DIGEST_INTERVAL_MS, 10);
  return Number.isFinite(envVal) && envVal > 0 ? envVal : DEFAULT_DIGEST_INTERVAL_MS;
}

let _timer = null;
let _lastMinute = '';
let _lastRunTimestamp = null;
let _currentTimeout = null;

function scheduleNextDigest() {
  const intervalMs = getDigestIntervalMs();
  const now = Date.now();

  if (_lastRunTimestamp !== null) {
    const elapsed = now - _lastRunTimestamp;
    if (elapsed >= intervalMs) {
      // Already overdue: fire now, then reschedule cleanly
      _lastRunTimestamp = now;
      _currentTimeout = setTimeout(() => {
        try {
          const items = digestQueue.flush();
          if (items.length > 0) {
            digestQueue.setLastDelivered(items);
            logger.info(`[digest] Auto-delivered ${items.length} item(s) at interval.`);
          }
        } catch (e) {
          logger.warn('[digest] scheduler error', { error: e.message });
        }
        scheduleNextDigest();
      }, 100);
      return;
    }
    // Drift-aware: align next fire to a clean interval boundary from the last run
    const drift = elapsed % intervalMs;
    const delayUntilBoundary = intervalMs - drift;
    if (_currentTimeout) clearTimeout(_currentTimeout);
    _currentTimeout = setTimeout(() => {
      _lastRunTimestamp = Date.now();
      try {
        const items = digestQueue.flush();
        if (items.length > 0) {
          digestQueue.setLastDelivered(items);
          logger.info(`[digest] Auto-delivered ${items.length} item(s) at interval.`);
        }
      } catch (e) {
        logger.warn('[digest] scheduler error', { error: e.message });
      }
      scheduleNextDigest();
    }, delayUntilBoundary);
    return;
  }

  // First run: schedule immediately
  _lastRunTimestamp = now;
  _currentTimeout = setTimeout(() => {
    _lastRunTimestamp = Date.now();
    try {
      const items = digestQueue.flush();
      if (items.length > 0) {
        digestQueue.setLastDelivered(items);
        logger.info(`[digest] Auto-delivered ${items.length} item(s) at interval.`);
      }
    } catch (e) {
      logger.warn('[digest] scheduler error', { error: e.message });
    }
    scheduleNextDigest();
  }, 100);
}

export function startDigestScheduler() {
  // Guard: skip scheduler when voice mode is active
  if (process.env.DISABLE_AUTONOMY === '1') {
    logger.info('[autonomy] disabled (voice mode) — digest scheduler will not start');
    return;
  }
  if (_timer) return;
  // Use a one-second poll for the minute-aligned quiet-hours check, but drive the digest interval via drift-aware schedule.
  _lastRunTimestamp = null;
  _timer = setInterval(() => {
    try {
      const nowMinute = hhmm();
      if (nowMinute !== _lastMinute) {
        _lastMinute = nowMinute;
        if (isDigestTime()) {
          // Force a digest run now, then resync schedule
          if (_currentTimeout) clearTimeout(_currentTimeout);
          _lastRunTimestamp = Date.now();
          const items = digestQueue.flush();
          if (items.length > 0) {
            digestQueue.setLastDelivered(items);
            logger.info(`[digest] Auto-delivered ${items.length} item(s) at digest time.`);
          }
          scheduleNextDigest();
        }
      }
    } catch (e) {
      logger.warn('[digest] scheduler error', { error: e.message });
    }
  }, 1000);
  // Kick off the first scheduled digest
  scheduleNextDigest();
  logger.info(`[digest] Drift-aware scheduler started with interval ${getDigestIntervalMs()}ms.`);
}

export function stopDigestScheduler() {
  if (_timer) {
    clearInterval(_timer);
    _timer = null;
  }
  if (_currentTimeout) {
    clearTimeout(_currentTimeout);
    _currentTimeout = null;
  }
  _lastRunTimestamp = null;
  logger.info('[digest] Scheduler stopped.');
}

export default { startDigestScheduler, stopDigestScheduler };

