// turnGuard.js -- clean task-switch / interrupt handling.
// Each conversational turn for a session gets a monotonically increasing token. If a NEWER turn
// begins for the same session while an older one is still working (barge-in, or the user types
// while voice is mid-thought), the older turn detects it's been superseded at its emit point and
// drops its now-stale reply instead of speaking over the new one. In-memory only, per session.
// Also includes a concurrency guard that blocks tool execution when a fullscreen application
// (browser in fullscreen, game, video player) is in the foreground, using pythonWorker to check.
import { pythonWorker } from '../pythonWorker.js';

const _gen = new Map();
const _pending = new Map(); // sessionId -> Set<token>

// Cache for foreground info to avoid hammering pythonWorker on every tool call
let _lastForegroundCheck = 0;
let _cachedForegroundBlocked = false;
const FOREGROUND_CACHE_MS = 5000; // 5 second cache

// Configurable list of regex patterns that indicate a fullscreen or blocking app
const FULLSCREEN_PATTERNS = [
  /\b(fullscreen|full screen)\b/i,
  /\b(game|gaming|play\b)/i,
  /\b(video|movie|player|netflix|youtube|twitch|vlc|mpc\-hc)\b/i,
  /\b(presentation|slideshow|powerpoint|keynote)\b/i
];

// List of process names that are always allowed (not blocked)
const ALLOWED_PROCESSES = [
  'explorer.exe',
  'taskmgr.exe',
  'code.exe',
  'chrome.exe',
  'firefox.exe',
  'msedge.exe',
  'brave.exe'
];

async function _checkForegroundBlocked() {
  const now = Date.now();
  if (now - _lastForegroundCheck < FOREGROUND_CACHE_MS) {
    return _cachedForegroundBlocked;
  }
  try {
    const result = await pythonWorker.sendCommand('window_ops.get_foreground_info', {});
    if (!result || result.error) {
      // On error, assume not blocked (fail open)
      _cachedForegroundBlocked = false;
    } else {
      const title = (result.foreground?.title || '').toLowerCase();
      const process = (result.foreground?.process_name || '').toLowerCase();
      // Check if process is in allowed list (never block these)
      if (ALLOWED_PROCESSES.some(p => process.includes(p.replace('.exe', '')))) {
        _cachedForegroundBlocked = false;
      } else {
        // Check title against fullscreen patterns
        _cachedForegroundBlocked = FULLSCREEN_PATTERNS.some(pattern => pattern.test(title));
      }
    }
  } catch (err) {
    // Fail open on any error
    _cachedForegroundBlocked = false;
  }
  _lastForegroundCheck = now;
  return _cachedForegroundBlocked;
}

export function begin(sessionId) {
  const s = String(sessionId || 'default');
  const n = (_gen.get(s) || 0) + 1;
  _gen.set(s, n);
  // Track this token as pending; any prior pending tokens for this session remain tracked
  // but will be auto-dropped when they emit and fail isCurrent. Also clean up old pending.
  if (!_pending.has(s)) _pending.set(s, new Set());
  _pending.get(s).add(n);
  return n;
}

// True if `token` is still the latest turn for this session (i.e. not superseded).
export function isCurrent(sessionId, token) {
  return (_gen.get(String(sessionId || 'default')) || 0) === token;
}

// Register that a completion (belonging to `token`) has finished emitting (success or discard).
// This removes it from the pending set to allow eventual GC of the session's pending set.
export function complete(sessionId, token) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  if (set) {
    set.delete(token);
    if (set.size === 0) _pending.delete(s);
  }
}

// Returns the number of pending (in-flight) completions for a session, useful for diagnostic logging.
export function pendingCount(sessionId) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  return set ? set.size : 0;
}

export default { begin, isCurrent, complete, pendingCount };

