// skillCapture — after a successful, non-trivial task, distill a reusable skill.
// skill_guard scans the candidate before saving; the store's maturity counter promotes
// a skill to "proven" after it's been captured a few times.
import logger from '../utils/logger.js';
import llmService from './llm.js';
import conversationLogger from './conversationLogger.js';
import skillStore from './skillStore.js';
import fs from 'fs';
import path from 'path';

// Reject destructive, secret, or injection content from ever becoming a saved skill.
const REJECT = [
  /rm\s+-rf/i, /del\s+\/[fsq]/i, /format\s+[a-z]:/i, /deltree/i, /rmdir\s+\/s/i,
  /\bshutdown\b/i, /reg(\.exe)?\s+delete/i, /diskpart/i, /mkfs/i,
  /ignore\s+(all\s+)?(previous|prior)\s+instructions/i,
  /\bpassword\b|\bapi[_\- ]?key\b|\bsecret\s+key\b|\bprivate\s+key\b|\btoken\s*[:=]/i,
  /[A-Za-z0-9+/]{40,}={0,2}/,            // long base64-ish blob
  /https?:\/\/\S*[:@]\S+/i,              // creds in URL
];
function guardOk(text) { return !REJECT.some((r) => r.test(text)); }

let _running = false;
let _toolLog = [];
const CAPTURE_TIMEOUT_MS = 10000;
const SKILL_CAPTURE_FILE = path.resolve('./data/skill_capture_log.json');

// Load existing tool log from disk if available
try {
  const raw = fs.readFileSync(SKILL_CAPTURE_FILE, 'utf8');
  const parsed = JSON.parse(raw);
  if (Array.isArray(parsed)) _toolLog = parsed;
} catch { /* first run */ }

function _persistToolLog() {
  try {
    const dir = path.dirname(SKILL_CAPTURE_FILE);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(SKILL_CAPTURE_FILE, JSON.stringify(_toolLog, null, 2), 'utf8');
  } catch (e) {
    logger?.warn?.('[skillCapture] persist failure', { error: e.message });
  }
}

export async function reviewAndCapture(opts = {}) {
  // Before main capture, run deduplicated tool-sequence capture
  _captureToolSequence();


  if (_running) return { captured: false, reason: 'already running' };
  _running = true;
  try {
    let transcript = opts.transcript;
    if (!transcript) {
      try {
        const h = conversationLogger.getRecentHistoryAcrossDays(opts.maxTurns || 14) || [];
        transcript = h.map((e) => ({ d: (e.direction || e.role), c: e.content }))
          .filter((x) => x.c).slice(-14)
          .map((x) => `${x.d === 'assistant' ? 'AVA' : 'User'}: ${String(x.c).slice(0, 400)}`)
          .join('\n');
      } catch { /* optional */ }
    }
    if (!transcript || !transcript.trim()) return { captured: false, reason: 'no transcript' };

    const sys = `You capture REUSABLE skills from a completed task. If the task involved a NON-TRIVIAL, repeatable procedure (multiple steps, specific tools, or trial-and-error worth remembering for next time), output ONE skill as JSON:
{"title":"short imperative title","when":"when to use this","steps":["step 1","step 2", ...],"tags":["..."]}
Explicit user corrections or preference-pattern phrases (for example, "no, I meant...", "actually...", or "when I say X, do Y") are reusable lessons: capture them as a skill with the corrected/preferred behavior in steps, even if they are not a completed task.
If the task was trivial, one-off, or has no reusable procedure or explicit correction/preference pattern, output exactly: null
Never include secrets, credentials, or destructive commands in the steps.`;
    const usr = `GOAL: ${opts.goal || '(infer from the transcript)'}\n\nTRANSCRIPT:\n${transcript}`;

    let text = '';
    try {
      const r = await llmService.chat([{ role: 'system', content: sys }, { role: 'user', content: usr }], { temperature: 0.2, max_tokens: 500 });
      text = (r.text || r.content || '').trim();
    } catch (e) { return { captured: false, error: e.message }; }

    if (/^null\b/i.test(text) || text.toLowerCase() === 'null') return { captured: false, reason: 'nothing reusable' };
    let skill = null;
    try { const m = text.match(/\{[\s\S]*\}/); skill = m ? JSON.parse(m[0]) : null; } catch { skill = null; }
    if (!skill || !skill.title || !skill.steps) return { captured: false, reason: 'no skill parsed' };

    const serialized = `${skill.title}\n${skill.when || ''}\n${Array.isArray(skill.steps) ? skill.steps.join('\n') : skill.steps}`;
    if (!guardOk(serialized)) {
      logger?.warn?.('[skillCapture] rejected unsafe skill', { title: skill.title });
      return { captured: false, reason: 'guard_rejected' };
    }

    const res = skillStore.saveSkill({ title: skill.title, when: skill.when, steps: skill.steps, tags: skill.tags });
    logger?.info?.('[skillCapture] captured', { title: skill.title, uses: res.uses, proven: res.proven });
    return { captured: true, title: skill.title, uses: res.uses, proven: res.proven, isNew: res.created };
  } finally {
    _running = false;
  }
}

/**
 * Read tool-call patterns from conversationLogger's internal _logEntries,
 * deduplicate by sequence fingerprint, and persist to skillStore.
 * Uses a timeout to prevent hung cycles — clears _running on abort.
 */
function _captureToolSequence() {
  let entries = [];
  try {
    // Safely access conversationLogger's internal log if present
    if (conversationLogger._logEntries && Array.isArray(conversationLogger._logEntries)) {
      entries = conversationLogger._logEntries;
    } else if (typeof conversationLogger.getBuffer === 'function') {
      entries = conversationLogger.getBuffer() || [];
    }
  } catch { entries = []; }

  if (entries.length < 3) return; // too few to form a meaningful sequence

  // Extract recent tool-call pairs (direction+content) as simplified sequences
  const rawTools = [];
  for (const e of entries) {
    const content = e.content || '';
    if (content.startsWith('[') && e.direction === 'assistant') {
      rawTools.push({ role: e.direction || 'assistant', content: content.slice(0, 200) });
    }
  }
  if (rawTools.length < 2) return;

  // Generate fingerprint: concatenation of tool names/subjects (first word of each)
  const fingerprint = rawTools.map(t => t.content.split(/[:=(]/)[0].trim().toLowerCase()).filter(Boolean).join('|');
  if (!fingerprint) return;

  // Deduplicate against in-memory tool log (already persisted)
  if (_toolLog.some(t => t.fingerprint === fingerprint)) return;

  // Prepare skill entry from sequence
  const steps = rawTools.map(t => `${t.role} used: ${t.content}`);
  const title = `Tool sequence: ${fingerprint.replace(/\|/g, ' -> ')}`;
  const when = 'When the user requests a task that matches this tool sequence';
  const tags = ['tool-sequence', ...fingerprint.split('|').slice(0, 3)];

  // Guard check
  const serialized = `${title}\n${when}\n${steps.join('\n')}`;
  if (!guardOk(serialized)) {
    logger?.info?.('[skillCapture] tool sequence rejected by guard');
    return;
  }

  // Use timeout to prevent hung capture cycles
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    _running = false;
    logger?.warn?.('[skillCapture] tool sequence capture timed out');
  }, CAPTURE_TIMEOUT_MS);

  try {
    if (timedOut) return;
    const result = skillStore.saveSkill({ title, when, steps, tags });
    // Record to tool log and persist to disk
    _toolLog.push({ fingerprint, capturedAt: new Date().toISOString(), title });
    if (_toolLog.length > 100) _toolLog = _toolLog.slice(-50); // keep recent 50
    _persistToolLog();
    logger?.info?.('[skillCapture] tool sequence captured', { title, uses: result.uses });
  } catch (e) {
    logger?.warn?.('[skillCapture] tool sequence capture error', { error: e.message });
    _running = false; // abort on failure
  } finally {
    clearTimeout(timer);
  }
}

export default { reviewAndCapture };

// Expose tool log for debugging/inspection
export function getToolCaptureLog() {
  return _toolLog;
}

