// turnGuard.js -- clean task-switch / interrupt handling.
// Each conversational turn for a session gets a monotonically increasing token. If a NEWER turn
// begins for the same session while an older one is still working (barge-in, or the user types
// while voice is mid-thought), the older turn detects it's been superseded at its emit point and
// drops its now-stale reply instead of speaking over the new one. In-memory only, per session.
import pythonWorker from './pythonWorker.js';

const _gen = new Map();
const _pending = new Map(); // sessionId -> Set<token>
const _fullscreenCache = { value: false, ts: 0 }; // 2s ttl cache
const _lastForeground = { title: '', process: '' };

export function begin(sessionId) {
  const s = String(sessionId || 'default');
  const n = (_gen.get(s) || 0) + 1;
  _gen.set(s, n);
  // Track this token as pending; any prior pending tokens for this session remain tracked
  // but will be auto-dropped when they emit and fail isCurrent. Also clean up old pending.
  if (!_pending.has(s)) _pending.set(s, new Set());
  _pending.get(s).add(n);
  return n;
}

// True if `token` is still the latest turn for this session (i.e. not superseded).
export function isCurrent(sessionId, token) {
  return (_gen.get(String(sessionId || 'default')) || 0) === token;
}

// Returns true if a full-screen application (video player, presentation, game) is currently
// the foreground window. Uses Python worker's window_ops.get_foreground_info method.
export async function isFullscreenApp() {
  const now = Date.now();
  if (now - _fullscreenCache.ts < 2000) return _fullscreenCache.value;
  try {
    const info = await pythonWorker.call('window_ops.get_foreground_info', {});
    if (info && info.foreground) {
      _lastForeground.title = info.foreground.title || '';
      _lastForeground.process = info.foreground.process || '';
      const titleLower = _lastForeground.title.toLowerCase();
      const processLower = _lastForeground.process.toLowerCase();
      // Common full-screen applications: video players, presentation software, games
      const fullscreenKeywords = [
        'fullscreen', 'video', 'player', 'vlc', 'mpv', 'media player',
        'presentation', 'slideshow', 'powerpoint', 'keynote', 'slides',
        'game', 'unity', 'unreal', 'steam', 'epic games',
        'netflix', 'hbo', 'youtube', 'twitch', 'plex',
        'browser fullscreen', ' - full screen', 'movie', 'playing'
      ];
      const processKeywords = [
        'vlc.exe', 'mpv.exe', 'wmplayer.exe', 'powerpnt.exe', 'keynote',
        'steam.exe', 'ue4', 'unity', 'chrome.exe', 'firefox.exe'
      ];
      const matchTitle = fullscreenKeywords.some(k => titleLower.includes(k));
      const matchProcess = processKeywords.some(k => processLower.includes(k));
      // A simple heuristic: if the window title or process matches known full-screen apps
      _fullscreenCache.value = matchTitle || matchProcess;
      // For safety, also check if the title is exceptionally short (like a game window)
      if (_fullscreenCache.value === false && titleLower.length > 0 && titleLower.length < 16) {
        // Many full-screen apps/games have short single-word window titles
        _fullscreenCache.value = true;
      }
    } else {
      _fullscreenCache.value = false;
    }
  } catch (err) {
    // If the Python worker is not available, be permissive (allow responses)
    _fullscreenCache.value = false;
  }
  _fullscreenCache.ts = now;
  return _fullscreenCache.value;
}

// Register that a completion (belonging to `token`) has finished emitting (success or discard).
// This removes it from the pending set to allow eventual GC of the session's pending set.
export function complete(sessionId, token) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  if (set) {
    set.delete(token);
