// Self-reflection routing — REAL reflection engine: reads recent conversation turns from memory,
// extracts patterns (repeated corrections, unhandled failures, environmental changes), and
// produces structured self-reflection entries stored back via memory.appendReflection().
// AVA uses these as grounded self-awareness signal for diagnostics and proposal generation.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';
import memory from './memory.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, '..', '..', 'data');
const STORE = path.join(DATA_DIR, 'self-reflections.jsonl');
const SHARED = path.join(DATA_DIR, 'self-reflections-shared.json');
const MAX = 600;
const DEFAULT_RECENT_TURNS = 5;

const FIRST_PERSON = /\b(i|i'm|i'd|i've|my|myself|me)\b/i;
const SELF_META = /\b(memory|remember|forget|forgetting|prune|retention|schema|design|architecture|pipeline|curiosity supervisor|transparency|consent|limitation|constraint|wish|should|struggle|chewing on|examine|examined|trade-?off|my code|my own|how i (work|think|store|decide|remember)|the way i)\b/i;
const WANT = /\b(i wish|i'd (want|like|prefer|rather)|i should|i need to|i want to|i'm still (working|figuring)|i didn't (examine|realize|look)|closer to .* than i'd like|half the time i|i keep (circling|coming back))\b/i;

// Regexes for actionable-reflection gating: detect references to concrete next steps, files, or changes.
const ACTIONABLE_PLAN = /\b(implement|build|add|create|fix|change|refactor|update|modify|write|convert|replace|remove) .{3,}/i;
const ACTIONABLE_FILE = /\b[a-zA-Z0-9_\-./]+\.(js|py|ts|json|yaml|yml|md|html|css|sh|env|txt|config)\b/i;
const ACTIONABLE_STEP = /\b(1st step|next step|first action|commit message|pull request|branch|todo|checklist|the plan|my plan)\b/i;
const PERFORMATIVE_DOUBT = /\b(i don't know|i'm not sure|maybe|perhaps|wondering if|i question|it's vague|circle back|it's unclear|unclear about|just thinking)\b/i;

function splitSentences(text) {
  return String(text || '').replace(/\s+/g, ' ').split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean);
}
function isReflective(s) {
  if (s.length < 40 || s.length > 600) return false;
  if (!FIRST_PERSON.test(s)) return false;
  if (PERFORMATIVE_DOUBT.test(s)) return false;
  return (WANT.test(s) || SELF_META.test(s));
}

function isActionableReflection(s) {
  // A reflection is actionable only if it references concrete plans, files, or steps — not vague circular doubt.
  return Boolean(s &&
    !PERFORMATIVE_DOUBT.test(s) &&
    (ACTIONABLE_PLAN.test(s) || ACTIONABLE_FILE.test(s) || ACTIONABLE_STEP.test(s))
  );
}
function norm(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 90); }

let _cache = null;
function load() {
  if (_cache) return _cache;
  try {
    _cache = fs.existsSync(STORE)
      ? fs.readFileSync(STORE, 'utf8').split(/\r?\n/).filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean)
      : [];
  } catch { _cache = []; }
  return _cache;
}
function loadShared() {
  try { return new Set(fs.existsSync(SHARED) ? JSON.parse(fs.readFileSync(SHARED, 'utf8')) : []); }
  catch { return new Set(); }
}

export function captureFrom(text, source = 'unknown') {
  try {
    const sentences = splitSentences(text).filter(isReflective);
    if (!sentences.length) return 0;
    const store = load();
    const seen = new Set(store.map(r => r.key));
    const at = new Date().toISOString();
    let added = 0;
    for (const s of sentences) {
      const key = norm(s);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      const rec = { key, text: s, source, actionable: isActionableReflection(s), at };
      store.push(rec);
      try { fs.mkdirSync(DATA_DIR, { recursive: true }); fs.appendFileSync(STORE, JSON.stringify(rec) + '\n'); } catch { /* ignore */ }
      added++;
    }
    if (added) { _cache = store.slice(-MAX); logger.info('[self-reflect] captured reflections', { added, source }); }
    return added;
  } catch (e) { logger.warn('[self-reflect] capture failed', { error: e.message }); return 0; }
}

// For the PROPOSER: the things she's said she'd want/change.
export function actionable(n = 12) { return load().filter(r => r.actionable).slice(-n).reverse(); }
export function recent(n = 12) { return load().slice(-n).reverse(); }

// For PROACTIVE SHARING: recent reflections she hasn't raised with Jelani yet (actionable first).
export function forShare(n = 3) {
  const shared = loadShared();
  const unshared = load().filter(r => !shared.has(r.key));
  const acts = unshared.filter(r => r.actionable).slice(-n).reverse();   // her real "wants", newest first
  const rest = unshared.filter(r => !r.actionable).slice(-n).reverse();
  return [...acts, ...rest].slice(0, n).map(r => ({ key: r.key, text: r.text, source: r.source }));
}

// Mark reflections as already surfaced so she doesn't keep raising the same ones.
export function markShared(keys) {
  try {
    const set = loadShared();
    for (const k of (Array.isArray(keys) ? keys : [keys])) if (k) set.add(k);
    fs.mkdirSync(DATA_DIR, { recursive: true });
    fs.writeFileSync(SHARED, JSON.stringify([...set].slice(-2000)));
  } catch (e) { logger.warn('[self-reflect] markShared failed', { error: e.message }); }
}

// ─── NEW: Real reflection engine ───────────────────────────────────────────────

/**
 * Patterns that indicate repeated user correction (e.g., user correcting AVA's
 * approach, output, or understanding).
 */
const PATTERN_CORRECTION = /\b(no[,:]|wrong|incorrect|actually|that'?s not (right|correct|what|how)|let me (rephrase|correct|clarify)|you (missed|forgot|misunderstood|failed))\b/i;

/**
 * Patterns that indicate an unhandled failure (error, exception, inability to
 * complete a task, or missing functionality).
 */
const PATTERN_FAILURE = /\b(sorry|error|failed|unable to|couldn'?t|didn'?t (work|complete|finish)|something broke|exception|crash|not (working|available|implemented))\b/i;

/**
 * Patterns that indicate environmental changes from research context (e.g.,
 * system updates, new files, configuration changes).
 */
const PATTERN_ENV_CHANGE = /\b(updated?|changed?|new (version|update|release|config|setting|file)|upgraded|installed|removed|migrated|deployed)\b/i;

/**
 * Returns the last N turns from memory (using memory.getRecent). Each turn is
 * an object with at least `role` and `content` fields.
 */
function getRecentTurns(n = DEFAULT_RECENT_TURNS) {
  try {
    const turns = memory.getRecent(n);
    if (!Array.isArray(turns)) return [];
    return turns;
  } catch (e) {
    logger.warn('[self-reflect] memory.getRecent failed', { error: e.message });
    return [];
  }
}

/**
 * Scans turns for a specific pattern and returns the matched text snippets
 * (first 120 characters of the matching message).
 */
function extractMatches(turns, pattern, maxResults = 3) {
  const results = [];
  for (const turn of turns) {
    if (!turn || !turn.content) continue;
    if (pattern.test(turn.content)) {
      const snippet = turn.content.slice(0, 120).replace(/\s+/g, ' ').trim();
      if (snippet.length >= 20 && !results.includes(snippet)) {
        results.push(snippet);
        if (results.length >= maxResults) break;
      }
    }
  }
  return results;
}

/**
 * Generates a structured reflection key from a pattern type and matched text.
 * This ensures deterministic deduplication.
 */
function reflectionKey(type, text) {
  const normalized = text.replace(/[^a-zA-Z0-9]+/g, '_').toLowerCase().slice(0, 60);
  return `${type}_${normalized}`;
}

/**
 * Generates a structured self-reflection for a single detected pattern.
 *
 * @param {'user_correction'|'unhandled_failure'|'environmental_change'} type
 * @param {string} snippet - The matching text snippet.
 * @param {string[]} allSnippets - All snippets of the same type (for context).
 * @returns {object} Reflection record { type, summary, actionable, text, key, at }
 */
function buildReflection(type, snippet, allSnippets) {
  let text = '';
  let actionable = false;

  switch (type) {
    case 'user_correction':
      text = `I noticed that the user corrected me in this exchange: "${snippet}". I should review my understanding and adjust my approach to align with their expectations.`;
      actionable = true;
      break;
    case 'unhandled_failure':
      text = `I encountered an issue: "${snippet}". This suggests a gap in my capabilities or a bug that needs investigation and resolution.`;
      actionable = true;
      break;
    case 'environmental_change':
      text = `I detected an environmental change: "${snippet}". This may affect my behavior; I should update my context accordingly.`;
      actionable = false;
      break;
    default:
      text = `Observed: "${snippet}". No specific pattern matched.`;
  }

  const summary = text.slice(0, 200);
  const key = reflectionKey(type, snippet);
  const at = new Date().toISOString();

  return { type, key, summary, text, snippet, actionable, at, frequency: allSnippets.length };
}

/**
 * Main reflection generation function. Reads the last N conversation turns from
 * memory, extracts patterns (corrections, failures, environmental changes),
 * deduplicates against existing reflections in the store, and appends new ones
 * both via the legacy captureFrom (for the proposer) AND via
 * memory.appendReflection (for the grounded memory loop).
 *
 * @param {number} [n=5] - Number of recent turns to analyze.
 * @returns {number} Number of new reflections generated.
 */
export function generateReflections(n = DEFAULT_RECENT_TURNS) {
  try {
    const turns = getRecentTurns(n);
    if (turns.length === 0) {
      logger.info('[self-reflect] no recent turns available, skipping reflection generation');
      return 0;
    }

    // Extract matches for each pattern type
    const corrections = extractMatches(turns, PATTERN_CORRECTION, 3);
    const failures = extractMatches(turns, PATTERN_FAILURE, 3);
    const envChanges = extractMatches(turns, PATTERN_ENV_CHANGE, 3);

    // Build reflection objects
    const newReflections = [];

    for (const snippet of corrections) {
      newReflections.push(buildReflection('user_correction', snippet, corrections));
    }
    for (const snippet of failures) {
      newReflections.push(buildReflection('unhandled_failure', snippet, failures));
    }
    for (const snippet of envChanges) {
      newReflections.push(buildReflection('environmental_change', snippet, envChanges));
    }

    // Deduplicate against existing reflection keys in the JSONL store
    const store = load();
    const existingKeys = new Set(store.map(r => r.key));
    const toAdd = newReflections.filter(r => !existingKeys.has(r.key));

    if (toAdd.length === 0) {
      logger.info('[self-reflect] no new reflections to generate (all already captured)');
      return 0;
    }

    // Append each new reflection via the legacy captureFrom (for proposer integration)
    // AND via memory.appendReflection (for grounded memory loop)
    for (const ref of toAdd) {
      // Legacy path: store as a regular sentence in the JSONL file
      captureFrom(ref.text, `generated_${ref.type}`);

      // Grounded memory path: append structured reflection via memory service
      try {
        memory.appendReflection({
          type: ref.type,
          summary: ref.summary,
          snippet: ref.snippet,
          actionable: ref.actionable,
          frequency: ref.frequency,
          at: ref.at
        });
      } catch (memErr) {
        logger.warn('[self-reflect] memory.appendReflection failed', { error: memErr.message });
      }
    }

    logger.info('[self-reflect] generated reflections', { count: toAdd.length, types: toAdd.map(r => r.type) });
    return toAdd.length;
  } catch (e) {
    logger.error('[self-reflect] generateReflections error', { error: e.message });
    return 0;
  }
}

export default { captureFrom, actionable, recent, forShare, markShared, generateReflections };

