const DATA_DIR = path.join(__dirname, '..', '..', 'data');
const DIGEST_PATH = path.join(DATA_DIR, 'digest.jsonl');

function ensureDirs() {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
}

function nowIso() { return new Date().toISOString(); }

class DigestQueue {
  constructor() {
    this.queue = [];
    this.lastFlushAt = 0;
    this.lastNotifyAt = 0;
    this.pendingTimer = null;
    this.DIGEST_VISIBILITY_MS = Number(process.env.DIGEST_VISIBILITY_MS || 60000);
    ensureDirs();
  }

  _isQuietHours() {
    const override = process.env.DIGEST_FORCE_MODE;
    if (override === 'quiet') return true;
    if (override === 'awake') return false;
    try {
      const { getAutonomy } = autonomyLib; const autonomy = getAutonomy();
      const policy = autonomy.getPolicy();
      // reuse quiet-hours check indirectly via shouldInterrupt logic; approximate with hour window
      const qh = policy.quiet_hours || {};
      if (!qh.enabled) return false;
      const now = new Date();
      const hh = String(now.getHours()).padStart(2, '0');
      const mm = String(now.getMinutes()).padStart(2, '0');
      const t = `${hh}:${mm}`;
      const start = qh.start || '22:00';
      const end = qh.end || '07:00';
      if (start <= end) return t >= start && t < end;
      return t >= start || t < end;
    } catch { return false; }
  }

  _dequeueEligibleItem() {
    const now = Date.now();
    const cutoff = now - this.DIGEST_VISIBILITY_MS;
    const idx = this.queue.findIndex(item => {
      const created = new Date(item.createdAt).getTime();
      return created <= cutoff;
    });
    if (idx === -1) return null;
    const [item] = this.queue.splice(idx, 1);
    return item;
  }

  _scheduleNextDequeue() {
    if (this.pendingTimer) {
      clearTimeout(this.pendingTimer);
      this.pendingTimer = null;
    }
    if (this.queue.length === 0) return;
    const now = Date.now();
    const oldestItem = this.queue.reduce((a,b) => {
      const at = new Date(a.createdAt).getTime();
      const bt = new Date(b.createdAt).getTime();
      return at < bt ? a : b;
    });
    const oldestAge = now - new Date(oldestItem.createdAt).getTime();
    const remaining = this.DIGEST_VISIBILITY_MS - oldestAge;
    const delay = remaining > 0 ? remaining : 0;
    this.pendingTimer = setTimeout(() => {
      if (this._isQuietHours()) {
        this._scheduleNextDequeue();
        return;
      }
      const item = this._dequeueEligibleItem();
      if (item) {
        const delivered = this.flush();
        this.setLastDelivered(delivered);
      }
      this._scheduleNextDequeue();
    }, delay);
  }

  enqueue(item) {
    const id = item.id || `dg-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
    const enriched = {
      id,
      createdAt: nowIso(),
      domain: item.domain || 'web_research',
      trigger: item.trigger || 'gap_detected',
      title: item.title || 'Digest Item',
      summary: item.summary || '',
      evidence: item.evidence || {},
      links: Array.isArray(item.links) ? item.links.slice(0, 5) : [],
      recommendedAction: item.recommendedAction || 'notify'
    };
    this.queue.push(enriched);
    try {
