// windowJanitor.js — AVA proactive active-window LRU housekeeper.
// Maintains a managed set of tracked window entries (id, label, timestamp),
// persists them to a JSONL file on flush, and provides export functions
// for all window-tracking routes. Replaces the old PowerShell-only janitor
// with a cross-platform, persistent, bounded LRU store.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const MAX_WINDOW_TRACK = Math.max(10, parseInt(process.env.AVA_MAX_WINDOW_TRACK || '100', 10));
const PRUNE_INTERVAL_MS = 60_000; // check every 60s
const PERSIST_PATH = path.join(__dirname, '..', '..', 'data', 'active_windows.jsonl');

// In-memory store: Map<id, { id, label, timestamp }>
const _store = new Map();

let _persistTimer = null;

/**
 * Load persisted entries from JSONL file on startup.
 */
function _loadPersisted() {
  try {
    if (!fs.existsSync(PERSIST_PATH)) return;
    const lines = fs.readFileSync(PERSIST_PATH, 'utf8').split('\n').filter(Boolean);
    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        if (entry && entry.id && entry.timestamp) {
          // Only load entries that are less than 24h old (prevent stale restores)
          if (Date.now() - entry.timestamp < 86_400_000) {
            _store.set(entry.id, entry);
          }
        }
      } catch {
        // skip malformed lines
      }
    }
  } catch (err) {
    logger.warn('[windowJanitor] failed to load persisted windows', { error: err.message });
  }
}

/**
 * Persist current store to JSONL file.
 */
function _persist() {
  try {
    const dir = path.dirname(PERSIST_PATH);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const lines = [];
    for (const entry of _store.values()) {
      lines.push(JSON.stringify(entry));
    }
    fs.writeFileSync(PERSIST_PATH, lines.join('\n') + '\n', 'utf8');
    logger.debug('[windowJanitor] persisted active windows', { count: _store.size, path: PERSIST_PATH });
  } catch (err) {
    logger.warn('[windowJanitor] failed to persist windows', { error: err.message });
  }
}

/**
 * Enforce LRU max size — evict oldest entries if store exceeds MAX_WINDOW_TRACK.
 */
function _enforceMax() {
  if (_store.size <= MAX_WINDOW_TRACK) return;
  const sorted = [..._store.values()].sort((a, b) => a.timestamp - b.timestamp);
  const toRemove = sorted.slice(0, _store.size - MAX_WINDOW_TRACK);
  for (const entry of toRemove) {
    _store.delete(entry.id);
  }
