// groundTruth.js — AVA's shared single-source-of-truth (ground_truth.md). She READS it into her
// context each session so she doesn't rebuild the user's world from scratch, and she can WRITE to it
// ("Ava, file that") so settled facts, preferences, and decisions persist across sessions.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';

// In-memory key-value store backed by a separate JSONL file for durable facts.
// This provides an append-and-query pattern that memoryReviewer, lessonLearner,
// skillStore, and other modules can rely on without assuming curatedMemory's API.
const KV_PATH = process.env.AVA_GROUND_TRUTH_KV_PATH
  || path.join(__dirname, '..', '..', '..', 'ava-integration', 'ground_truth_kv.jsonl');
const _kvCache = new Map(); // key → {value, metadata, timestamp}

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const GT_PATH = process.env.AVA_GROUND_TRUTH_PATH
  || path.join(__dirname, '..', '..', '..', 'ava-integration', 'ground_truth.md');

export function read() {
  try { return fs.existsSync(GT_PATH) ? fs.readFileSync(GT_PATH, 'utf8') : ''; }
  catch { return ''; }
}

// A compact block for injecting into her prompt (settled context she should treat as established).
export function block(maxChars = 3500) {
  const t = read();
  if (!t) return '';
  const clipped = t.length > maxChars ? t.slice(0, maxChars) + '\n…(truncated; full file is ground_truth.md)' : t;
  return `[GROUND TRUTH — settled facts, preferences, and decisions you and ${process.env.AVA_USER_NAME || 'the user'} agreed on; treat these as established, don't re-ask or re-derive them]\n${clipped}`;
}

// Append a filed note under a "## Filed notes" section (create it if missing).
export function fileThat(text) {
  try {
    const clean = String(text || '').replace(/\s+/g, ' ').trim().slice(0, 400);
    if (!clean) return { ok: false, error: 'nothing to file' };
    let t = read();
    const line = `- (${new Date().toISOString().slice(0, 10)}) ${clean}`;
    if (/^##\s+Filed notes/m.test(t)) {
      t = t.replace(/(^##\s+Filed notes[^\n]*\n)/m, `$1${line}\n`);
    } else {
      t = (t.trimEnd() || '# AVA ⇄ Ground Truth') + `\n\n## Filed notes\n${line}\n`;
    }
    fs.mkdirSync(path.dirname(GT_PATH), { recursive: true });
    fs.writeFileSync(GT_PATH, t);
    logger.info('[ground-truth] filed a note', { chars: clean.length });
    return { ok: true, filed: clean };
  } catch (e) { logger.warn('[ground-truth] fileThat failed', { error: e.message }); return { ok: false, error: e.message }; }
}

function _loadKvCache() {
  if (!fs.existsSync(KV_PATH)) return;
  const lines = fs.readFileSync(KV_PATH, 'utf8').split('\n').filter(Boolean);
  for (const line of lines) {
    try {
      const entry = JSON.parse(line);
      if (entry && entry.key != null) {
        _kvCache.set(entry.key, { value: entry.value, metadata: entry.metadata || null, timestamp: entry.timestamp || Date.now() });
      }
    } catch { /* skip malformed */ }
  }
}

// Initialize cache on first module load
_loadKvCache();

/**
 * writeEntry(key, value, metadata)
 * Appends a new fact to the JSONL file and updates the in-memory cache.
 * Overwrites any previous entry with the same key in cache (and appends a new
 * line so the last write wins on next load).
 */
export function writeEntry(key, value, metadata = null) {
  try {
    const k = String(key ?? '').trim();
    if (!k) return { ok: false, error: 'key is required' };
    const v = value ?? '';
    const entry = { key: k, value: v, metadata, timestamp: Date.now() };
    const line = JSON.stringify(entry) + '\n';
    fs.mkdirSync(path.dirname(KV_PATH), { recursive: true });
    fs.appendFileSync(KV_PATH, line, 'utf8');
    _kvCache.set(k, { value: v, metadata, timestamp: entry.timestamp });
    logger.info('[ground-truth-kv] wrote entry', { key: k });
    return { ok: true };
  } catch (e) {
    logger.warn('[ground-truth-kv] writeEntry failed', { error: e.message });
    return { ok: false, error: e.message };
  }
}

/**
 * searchByPrefix(prefix)
 * Returns all cached entries whose key starts with the given prefix.
 * Results are ordered by insertion timestamp (ascending).
 */
export function searchByPrefix(prefix) {
  const p = String(prefix ?? '');
  const results = [];
  for (const [key, data] of _kvCache) {
    if (key.startsWith(p)) {
      results.push({ key, value: data.value, metadata: data.metadata, timestamp: data.timestamp });
    }
  }
  results.sort((a, b) => a.timestamp - b.timestamp);
  return results;
}

export default { read, block, fileThat, writeEntry, searchByPrefix };

