      added++;
    }
    if (added) { _cache = store.slice(-MAX); logger.info('[self-reflect] captured reflections', { added, source }); }
    return added;
  } catch (e) { logger.warn('[self-reflect] capture failed', { error: e.message }); return 0; }
}

