// windowJanitor.js — AVA proactive housekeeping task (runs around the clock).
// Every interval it runs a hidden PowerShell sweep that closes ONLY non-foreground File Explorer
// windows and idle non-foreground Command Prompt consoles. Scoped to just those two apps, on
// purpose. Never force-kills, never touches the shell/taskbar, and skips the focused window and
// any console younger than 30s (so it won't interrupt a script that's actively running).
import { spawn } from 'child_process';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';
import toolsService from '../tools/toolsService.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PS1 = path.join(__dirname, '..', '..', 'scripts', 'windowJanitor.ps1');

const INTERVAL_SEC = Math.max(20, parseInt(process.env.AVA_WINDOW_JANITOR_SECONDS || '60', 10));
let timer = null;
let running = false;

// In-memory map of foreground window titles -> last seen timestamp
const windowIdleTracker = new Map();
const IDLE_THRESHOLD_MS = 30 * 60 * 1000; // 30 minutes

function sweep() {
  if (running) return; // never overlap sweeps
  running = true;
  let out = '';
  let ps;
  try {
    ps = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', PS1], { windowsHide: true });
  } catch (e) {
    running = false;
    logger.warn('[windowJanitor] spawn failed', { error: e.message });
    return;
  }
  ps.stdout.on('data', (d) => { out += d.toString(); });
  ps.stderr.on('data', () => {});
  ps.on('error', (e) => { running = false; logger.warn('[windowJanitor] powershell error', { error: e.message }); });
  ps.on('close', () => {
    running = false;
    const closed = out.split(/\r?\n/).filter((l) => l.startsWith('CLOSED:')).map((l) => l.replace('CLOSED:', '').trim());
    if (closed.length) logger.info('[windowJanitor] closed idle windows', { count: closed.length, windows: closed.slice(0, 10) });
    // After PowerShell sweep, attempt browser tab cleanup
    closeStaleBrowserTabs();
  });
}

// Closes idle/stale browser tabs via toolsService.executeTool
async function closeStaleBrowserTabs() {
  try {
    // Get currently open tabs (up to 20)
    const result = await toolsService.executeTool('browser_ops.get_tabs', { maxTabs: 20 });
    if (!result || !result.tabs || !Array.isArray(result.tabs)) {
      logger.debug('[windowJanitor] no browser tabs info returned');
      return;
    }
    // Close tabs that have not been active in over 60 minutes (heuristic: mark older tabs as stale)
    const now = Date.now();
    const staleTabs = result.tabs.filter(tab => {
      const age = tab.lastActive || 0;
      return age > 0 && (now - age) > 3600000; // older than 1 hour
    });
    if (staleTabs.length === 0) {
      logger.debug('[windowJanitor] no stale browser tabs to close');
      return;
    }
    for (const tab of staleTabs.slice(0, 5)) { // close up to 5 per sweep
      await toolsService.executeTool('browser_ops.close_tab', { tabId: tab.id });
      logger.info('[windowJanitor] closed stale browser tab', { url: tab.url || tab.title || tab.id });
    }
  } catch (e) {
    logger.warn('[windowJanitor] browser tab cleanup error', { error: e.message });
  }
}

// Checks per-window entropy: logs when a foreground window stays unchanged >30 min
function checkWindowEntropy() {
  try {
    toolsService.executeTool('window_ops.get_foreground_info', {}).then(info => {
      if (!info || !info.title) return;
      const now = Date.now();
      const key = `${info.title}::${info.process || 'unknown'}`;
      const prev = windowIdleTracker.get(key);
      if (prev) {
        const idleMs = now - prev;
        if (idleMs > IDLE_THRESHOLD_MS) {
          logger.info('[windowJanitor] window idle >30min', { title: info.title, process: info.process, idleMinutes: Math.floor(idleMs / 60000) });
          // Reset tracker to avoid repeated logs every sweep for the same prolonged idle window
          windowIdleTracker.set(key, now);
        }
      } else {
        windowIdleTracker.set(key, now);
      }
      // Keep map size bounded
      if (windowIdleTracker.size > 100) {
        const entriesToDelete = [...windowIdleTracker.entries()].slice(0, 50);
        for (const [k] of entriesToDelete) windowIdleTracker.delete(k);
      }
    }).catch(() => {});
  } catch (e) {
    logger.warn('[windowJanitor] entropy check error', { error: e.message });
  }
}

export function start() {
  if (String(process.env.AVA_WINDOW_JANITOR || '').toLowerCase() === 'off') { logger.info('[windowJanitor] disabled via AVA_WINDOW_JANITOR=off'); return; }
  if (process.platform !== 'win32') { logger.info('[windowJanitor] non-Windows platform, skipping'); return; }
  if (timer) return;
  setTimeout(sweep, 8000); // first pass shortly after boot
  timer = setInterval(sweep, INTERVAL_SEC * 1000);
  // Also run the entropy check on the same interval
  setInterval(checkWindowEntropy, INTERVAL_SEC * 1000);
  logger.info('[windowJanitor] started', { intervalSec: INTERVAL_SEC, targets: ['File Explorer windows', 'idle cmd consoles'] });
}
export function stop() { if (timer) { clearInterval(timer); timer = null; } }
export function sweepNow() { sweep(); }

export default { start, stop, sweepNow };

