import fs from 'fs';
import path from 'path';
import { spawn } from 'child_process';
import logger from '../utils/logger.js';
import evolutionLog from './selfImprove/evolutionLog.js';

let restartScheduled = false;

function dataDir() {
  return path.join(process.cwd(), 'data');
}

function writeRestartRecord(record) {
  try {
    fs.mkdirSync(dataDir(), { recursive: true });
    fs.writeFileSync(
      path.join(dataDir(), 'pending-server-restart.json'),
      JSON.stringify(record, null, 2),
      'utf8'
    );
  } catch {}
}

function scheduleServerRestart({ reason = 'approved self-modification', delayMs = 2500 } = {}) {
  if (process.env.AVA_SELF_RESTART_OFF === '1') {
    return { scheduled: false, reason: 'disabled by AVA_SELF_RESTART_OFF' };
  }
  if (restartScheduled) {
    return { scheduled: true, alreadyScheduled: true, reason: 'restart already scheduled' };
  }

  const serverEntry = path.join(process.cwd(), 'src', 'server.js');
  const helper = path.join(process.cwd(), 'scripts', 'restart-server-after-delay.cjs');
  if (!fs.existsSync(serverEntry) || !fs.existsSync(helper)) {
    return { scheduled: false, reason: 'restart helper or server entry not found' };
  }

  const record = {
    requestedAt: new Date().toISOString(),
    reason,
    parentPid: process.pid,
    serverEntry,
    delayMs
  };
  writeRestartRecord(record);

  try {
    const child = spawn(process.execPath, [helper, serverEntry, String(delayMs)], {
      cwd: process.cwd(),
      detached: true,
      stdio: 'ignore',
      env: { ...process.env, AVA_RESTART_PARENT_PID: String(process.pid) }
    });
    child.unref();
    restartScheduled = true;
    logger.warn('[selfRestart] server restart scheduled', record);

    // Schedule post-restart verification of the changed file
    if (reason && reason !== 'approved self-modification') {
      const changedFile = extractChangedFile(reason);
      if (changedFile) {
        setTimeout(() => _verifyAndLoadChangedFile(changedFile, reason), delayMs + 2000);
      }
    }

    setTimeout(() => process.exit(0), 700);
    return { scheduled: true, delayMs, reason };
  } catch (e) {
    logger.warn('[selfRestart] failed to schedule server restart', { error: e.message });
    return { scheduled: false, reason: e.message };
  }
}

function extractChangedFile(reason) {
  try {
    // The reason is typically a file path like 'modified: /src/services/memorySearch.js'
    const match = reason.match(/\b(?:\.\.?\/)?(?:src\/)?[\w/]+\.(?:js|mjs|ts)\b/);
    if (!match) return null;
    const relativePath = match[0];
    // If it's not absolute, resolve relative to cwd
    if (path.isAbsolute(relativePath)) return relativePath;
    const absolute = path.join(process.cwd(), relativePath);
    return fs.existsSync(absolute) ? absolute : null;
  } catch { return null; }
}

async function _verifyAndLoadChangedFile(filePath, reason) {
  try {
    logger.info('[selfRestart] verifying changed file', { file: filePath });
    // dynamic import to catch syntax/runtime errors at load time
    const mod = await import(filePath);
    // If the module exports a default function/object, try calling it
    if (mod.default && typeof mod.default === 'function') {
      await mod.default();
    }
    await evolutionLog.append({
      type: 'restart:file',
      status: 'ok',
      file: filePath,
      reason,
      verifiedAt: new Date().toISOString()
    });
    logger.info('[selfRestart] changed file verified OK', { file: filePath });
  } catch (err) {
    const errorMsg = err.message || String(err);
    logger.error('[selfRestart] changed file verification FAILED', { file: filePath, error: errorMsg });
    try {
      await evolutionLog.append({
        type: 'restart:file',
        status: 'broken',
        file: filePath,
        error: errorMsg,
        reason,
        verifiedAt: new Date().toISOString()
      });
    } catch { /* best effort */ }
  }
}

export { scheduleServerRestart, _verifyAndLoadChangedFile };
export default { scheduleServerRestart, _verifyAndLoadChangedFile };

