// Async "dreaming" memory reviewer.
// Periodically (every N turns, or on demand) reads recent conversation, extracts ONLY
// durable facts, scans them for prompt-injection/secrets, and writes them into the
// bounded curated memory (USER.md / MEMORY.md). Consolidates when near the cap.
// Pattern: Hermes "memory reviewer" + Claude Code "autodream" consolidation.
import fs from 'fs';
import path from 'path';
import logger from '../utils/logger.js';
import llmService from './llm.js';
import conversationLogger from './conversationLogger.js';
import curatedMemory from './curatedMemory.js';
import toolsService from '../tools/toolsService.js';

// Lesson-hash deduplication set — stores normalized keys derived from rejected
// proposal lessons so that the same mistake pattern is not re-proposed.
const lessonHashes = new Set();

// Normalize a lesson string into a stable hash key for deduplication.
function _lessonKey(lesson) {
  if (!lesson || typeof lesson !== 'string') return '';
  return lesson.replace(/\s+/g, ' ').trim().toLowerCase().slice(0, 120);
}

// Read the `prior_mistake_lessons` array from AVA state (passed as an array) and
// store deduplication keys. Accepts state.priorMistakeLessons or a direct array.
export function ingestMistakeLessons(lessons) {
  const list = Array.isArray(lessons) ? lessons : (lessons && lessons.priorMistakeLessons) || [];
  let count = 0;
  for (const entry of list) {
    const src = (entry && entry.source) || '';
    const lesson = (entry && entry.lesson) || '';
    const key = _lessonKey(src + '|' + lesson);
    if (key && !lessonHashes.has(key)) {
      lessonHashes.add(key);
      count++;
    }
  }
  return count;
}

// Check whether a proposal string matches any stored lesson pattern.
export function isLessonKnown(proposalText) {
  if (!proposalText || typeof proposalText !== 'string') return false;
  const probe = _lessonKey(proposalText);
  for (const key of lessonHashes) {
    // If the lesson key is a substring of the proposal (or vice versa) it's a repeat.
    if (probe.includes(key) || key.includes(probe)) return true;
  }
  return false;
}

// Path for conflict-log JSONL
const CONFLICT_LOG_PATH = path.join(process.cwd(), 'data', 'conflict-log.jsonl');

// Ensure conflict log directory exists
function _ensureConflictLogDir() {
  const dir = path.dirname(CONFLICT_LOG_PATH);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

/**
 * Find facts in curatedMemory that potentially conflict with a given target fact.
 * Searches via curatedMemory.search, then uses json_ops.diff_and_score to detect
 * contradiction (negative similarity score or low overlap). Returns an array of
 * conflict records with the conflicting fact, score, and snippet.
 */
export async function _findConflicts(targetFact) {
  if (!targetFact || typeof targetFact !== 'string' || targetFact.length < 5) return [];
  const results = curatedMemory.search(targetFact);
  if (!Array.isArray(results) || results.length === 0) return [];
  const conflicts = [];
  for (const entry of results) {
    const content = entry.fact || entry.content || '';
    if (!content || content === targetFact) continue;
    try {
      const resp = await toolsService.executeTool('json_ops', { action: 'diff_and_score', a: content, b: targetFact });
      const score = (resp && (resp.score !== undefined)) ? resp.score : null;
      // Treat negative scores or scores below -0.3 as contradictions
      if (score !== null && score < -0.3) {
        conflicts.push({
          conflictingFact: content,
          score,
          snippet: content.slice(0, 80),
          targetFact,
        });
      }
    } catch {
      // json_ops not available — skip
    }
  }
  return conflicts;
}

/**
 * Write a conflict report entry to the conflict-log JSONL file.
 */
export function _logConflictReport(sessionId, conflicts) {
  _ensureConflictLogDir();
  const entry = {
    timestamp: new Date().toISOString(),
    sessionId: sessionId || 'unknown',
    conflicts,
  };
  fs.appendFileSync(CONFLICT_LOG_PATH, JSON.stringify(entry) + '\n', 'utf8');
}

/**
 * Group facts by a topic prefix (first 2-3 words or first 20 chars) and merge
 * duplicates by keeping the fact with the latest updated timestamp. Returns a
 * result summary: { groupsFound, merged, reason }.
 */
export async function _findConsolidationTargets() {
  // Fetch all facts from curatedMemory by listing both targets
  const allFacts = [];
  try {
    const userFacts = curatedMemory.listByTarget('user') || [];
    const memoryFacts = curatedMemory.listByTarget('memory') || [];
    allFacts.push(...userFacts, ...memoryFacts);
  } catch {
    return { groupsFound: 0, merged: 0, reason: 'curatedMemory.listByTarget unavailable' };
  }
  if (allFacts.length < 2) return { groupsFound: 0, merged: 0, reason: 'too few facts' };

  // Group by topic prefix (first 3 words or first 20 chars)
  const groups = new Map();
  for (const f of allFacts) {
    const text = f.fact || f.content || (typeof f === 'string' ? f : '');
    if (!text) continue;
    const prefix = text.split(/\s+/).slice(0, 3).join(' ').slice(0, 20).toLowerCase();
    if (!prefix) continue;
    if (!groups.has(prefix)) groups.set(prefix, []);
    groups.get(prefix).push({ text, updated: f.updated || f.created || new Date().toISOString(), id: f.id || '' });
  }

  let merged = 0;
  for (const [, entries] of groups) {
    if (entries.length < 2) continue;
    // Sort by updated descending
    entries.sort((a, b) => new Date(b.updated) - new Date(a.updated));
    const best = entries[0];
    // Remove duplicates (all but latest)
    const toRemove = entries.slice(1);
    for (const dup of toRemove) {
      try {
        curatedMemory.removeFact(dup.id, dup.text);
        merged++;
      } catch {
        // ignore removal failures
      }
    }
    // Ensure the best fact is still present (re-add if needed)
    if (entries.length > 1) {
      try {
        curatedMemory.appendFact('memory', best.text);
      } catch { /* ignore */ }
    }
  }

  return { groupsFound: groups.size, merged };
}

/**
 * Run a full review: find conflicts and consolidation targets, log via
 * conversationLogger, return counts.
 */
export async function runReview(sessionId) {
  const report = { sessionId: sessionId || 'manual', conflictsFound: 0, mergesDone: 0, errors: [] };

  // Step 1: Fetch a sample of facts to check for conflicts (up to 10)
  let factsToCheck = [];
  try {
    const userFacts = curatedMemory.listByTarget('user') || [];
    const memoryFacts = curatedMemory.listByTarget('memory') || [];
    factsToCheck = [...userFacts.slice(0, 5), ...memoryFacts.slice(0, 5)];
  } catch (e) {
    report.errors.push('listByTarget: ' + e.message);
  }

  for (const f of factsToCheck) {
    const factText = f.fact || f.content || '';
    if (!factText) continue;
    try {
      const conflicts = await _findConflicts(factText);
      if (conflicts.length > 0) {
        _logConflictReport(sessionId, conflicts);
        report.conflictsFound += conflicts.length;
      }
    } catch (e) {
      report.errors.push('_findConflicts: ' + e.message);
    }
  }

  // Step 2: Consolidation
  try {
