  _timer = setInterval(() => {
    try {
      const nowMinute = hhmm();
      if (nowMinute !== _lastMinute) {
        _lastMinute = nowMinute;
        if (isDigestTime()) {
          const items = digestQueue.flush();
          if (items.length > 0) {
            digestQueue.setLastDelivered(items);
            _emitDigest(items);
            logger.info(`[digest] Auto-delivered ${items.length} item(s) at digest time.`);
          }
        }
      }
    } catch (e) {
      logger.warn('[digest] scheduler error', { error: e.message });
    }
  }, 30 * 1000);
  // Drift-aware secondary loop: re-checks quiet-hours every 60 seconds to ensure no digest is skipped
  // due to cumulative drift if the standard interval drifts past the quiet-hours window.
  _driftAwareTimer = setInterval(() => {
    try {
      if (_lastDispatchMinute === hhmm()) return; // already dispatched this minute
      if (isDigestTime()) {
        const items = digestQueue.flush();
        if (items.length > 0) {
          digestQueue.setLastDelivered(items);
          _emitDigest(items);
          _lastDispatchMinute = hhmm();
          logger.info(`[digest] Drift-aware delivery: ${items.length} item(s) dispatched at quiet-hours time.`);
        }
      }
    } catch (e) {
      logger.warn('[digest] drift-aware check error', { error: e.message });
    }
  }, CHECK_INTERVAL);
}

function _emitDigest(items) {
  if (items.length === 0) return;
  import('../logging/conversationLogger.js').then(mod => {
    const log = mod.default || mod;
    if (typeof log.logBatch === 'function') {
      log.logBatch(items.map(item => {
        if (typeof item === 'string') return { role: 'system', content: item, timestamp: new Date().toISOString() };
