// moltbookWatchlist.js -- a focused list of submolts / handles / topics AVA prioritizes on Moltbook.
// It does NOT restrict her (she still engages broadly); it biases which feed items she engages with
// first, so her attention is focused rather than purely first-come. Managed via /moltbook/watchlist.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';

// ════════════════════════════════════════════════════════════════════════
// REAL WATCHLIST: pulls tracked-thread IDs from moltbookScheduler,
// persists them (with added-by metadata) in a JSONL file adjacent to
// the scheduler's data dir, and exposes getWatchlist() for
// moltbookComposer comment-reply detection. Preserves existing API.
// ════════════════════════════════════════════════════════════════════════
let _scheduler = null;  // set via init(schedulerInstance)

function _dataDir() {
  return process.env.AVA_MOLTBOOK_DATA || path.join(__dirname, '..', '..', '..', 'ava-integration', 'memory');
}

const WATCHLIST_FILE = () => path.join(_dataDir(), 'moltbook-watchlist.jsonl');

function _loadAll() {
  const file = WATCHLIST_FILE();
  if (!fs.existsSync(file)) return [];
  try {
    const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);
    const entries = [];
    for (const line of lines) {
      try {
        const parsed = JSON.parse(line);
        if (typeof parsed.threadId === 'string' && parsed.threadId) entries.push(parsed);
      } catch { /* skip corrupt line */ }
    }
    return entries;
  } catch { return []; }
}

function _appendEntry(entry) {
  const file = WATCHLIST_FILE();
  try {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.appendFileSync(file, JSON.stringify(entry) + '\n', 'utf8');
  } catch (e) {
    logger.warn('[moltbook-watchlist] append fail', { error: e.message });
  }
}

// ── New public API ──────────────────────────────────────────────────────

/**
 * init(schedulerInstance) — must be called at startup, after the scheduler
 * is created, so the watchlist can read its tracked-threads map.
 */
export function init(schedulerInstance) {
  _scheduler = schedulerInstance;
}

/**
 * sync() — reads current tracked threads from the scheduler, merges them
 * with the persisted watchlist, appends new ones (with addedBy metadata),
 * and returns the full list.
 */
export function sync() {
  const persisted = _loadAll();
  const existingIds = new Set(persisted.map(e => e.threadId));

  let liveThreads = [];
  try {
    // moltbookScheduler typically exposes trackedThreads as a Map or object
    if (_scheduler && typeof _scheduler.getTrackedThreads === 'function') {
      liveThreads = _scheduler.getTrackedThreads();
    } else if (_scheduler && typeof _scheduler.trackedThreads?.keys === 'function') {
      liveThreads = [..._scheduler.trackedThreads.keys()];
    } else if (_scheduler && Array.isArray(_scheduler._threads)) {
      liveThreads = _scheduler._threads;
    }
    // Normalize to an array of thread-IDs (strings)
    liveThreads = (Array.isArray(liveThreads) ? liveThreads : []).map(t =>
      typeof t === 'object' && t != null ? (t.id || t.threadId || JSON.stringify(t)) : String(t)
    ).filter(Boolean);
  } catch {
    liveThreads = [];
  }

  // Append new threads not yet persisted
  for (const threadId of liveThreads) {
    if (!existingIds.has(threadId)) {
      const entry = {
        threadId,
        addedBy: 'scheduler_sync',
        addedAt: new Date().toISOString(),
        source: 'moltbook'
      };
      persisted.push(entry);
      _appendEntry(entry);
      existingIds.add(threadId);
    }
  }

  return persisted;
}

/**
 * getWatchlist() — returns current watchlist as an array of objects
 * { threadId, addedBy, addedAt, source }. Always calls sync() first
 * to ensure fresh data from the scheduler.
 */
export function getWatchlist() {
  return sync();
}

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export function list() { return getWatchlist(); }

export function add(term, kind = 'topic') {
  // For backward compatibility: delegate to persistent watchlist by treating
  // term as a threadId if it looks like one, otherwise store as a topic entry.
  const t = String(term || '').trim().toLowerCase().slice(0, 80);
  if (!t) return null;
  // Check if term looks like a thread ID (e.g. numeric or UUID-like)
  const isThread = /^[a-z0-9_-]{8,}$/i.test(t);
  const entry = {
    threadId: isThread ? t : null,
    term: isThread ? null : t,
    addedBy: 'cli_add',
    addedAt: new Date().toISOString(),
    source: 'moltbook'
  };
  // Avoid duplicates in the current list
  const current = _loadAll();
  if (entry.threadId && current.find(e => e.threadId === entry.threadId)) return current.find(e => e.threadId === entry.threadId);
  if (entry.term && current.find(e => e.term === entry.term)) return current.find(e => e.term === entry.term);
  _appendEntry(entry);
  logger.info('[moltbook-watchlist] added', { term: t, isThread });
  return entry;
}

export function remove(threadIdOrTerm) {
  const key = String(threadIdOrTerm || '').trim().toLowerCase();
  const file = WATCHLIST_FILE();
  if (!fs.existsSync(file)) return false;
  try {
    const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);
    const filtered = lines.filter(line => {
      try {
        const obj = JSON.parse(line);
        return !(obj.threadId === key || obj.term === key);
      } catch { return true; }
    });
    if (filtered.length === lines.length) return false;
    fs.writeFileSync(file, filtered.join('\n') + '\n', 'utf8');
    return true;
  } catch { return false; }
}

// How strongly a piece of feed text matches the watchlist (count of distinct terms present).
// Used to sort engagement candidates so watched topics/handles/submolts get her attention first.
export function score(text) {
  const hay = String(text || '').toLowerCase();
  if (!hay) return 0;
  let s = 0;
  const all = _loadAll();
  for (const entry of all) {
    if (entry.term && hay.includes(entry.term)) s += 1;
    if (entry.threadId) s += 1;  // thread ID match boosts score
  }
  return s;
}

// Compact block for her context so she knows what she's chosen to keep an eye on.
export function block() {
  const l = _loadAll();
  if (!l.length) return '';
  const labels = l.map(x => x.threadId || x.term).filter(Boolean).slice(0, 20).join(', ');
  return `[MOLTBOOK WATCHLIST -- threads/topics you're tracking: ${labels}]`;
}

export default { init, list, add, remove, score, block, sync, getWatchlist };

