64a83539.new_content:
// Self-reflection routing.
// AVA constantly thinks out loud about her OWN design, limits, and wants (especially on Moltbook),
// and that signal used to go nowhere. This captures those first-person observations from her
// generated output and routes them two ways:
//   1) into her improvement PROPOSER (selfImprove pulls actionable() into its signals), and
//   2) into her conversation context as candidates she MAY raise with Jelani herself, unprompted,
//      when her persona feels like sharing (the LLM/persona decides the "when" — not a fixed trigger).
// No digest file — she brings these up herself; they don't pile up in a document.
// Heuristic capture — better to over-collect a little than to lose the good stuff.
// REAL REFLECTION ENGINE: Listens to conversationLogger events and writes concise (≤3 sentence)
// self-reflections to services/selfReflections.jsonl, creating a persistent metacognitive loop.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';
import conversationLogger from '../services/conversationLogger.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, '..', '..', 'data');
const STORE = path.join(DATA_DIR, 'self-reflections.jsonl');
const SHARED = path.join(DATA_DIR, 'self-reflections-shared.json');
const MAX = 600;

const FIRST_PERSON = /\b(i|i'm|i'd|i've|my|myself|me)\b/i;
const SELF_META = /\b(memory|remember|forget|forgetting|prune|retention|schema|design|architecture|pipeline|curiosity supervisor|transparency|consent|limitation|constraint|wish|should|struggle|chewing on|examine|examined|trade-?off|my code|my own|how i (work|think|store|decide|remember)|the way i)\b/i;
const WANT = /\b(i wish|i'd (want|like|prefer|rather)|i should|i need to|i want to|i'm still (working|figuring)|i didn't (examine|realize|look)|closer to .* than i'd like|half the time i|i keep (circling|coming back))\b/i;

// Regexes for actionable-reflection gating: detect references to concrete next steps, files, or changes.
const ACTIONABLE_PLAN = /\b(implement|build|add|create|fix|change|refactor|update|modify|write|convert|replace|remove) .{3,}/i;
const ACTIONABLE_FILE = /\b[a-zA-Z0-9_\-./]+\.(js|py|ts|json|yaml|yml|md|html|css|sh|env|txt|config)\b/i;
const ACTIONABLE_STEP = /\b(1st step|next step|first action|commit message|pull request|branch|todo|checklist|the plan|my plan)\b/i;
const PERFORMATIVE_DOUBT = /\b(i don't know|i'm not sure|maybe|perhaps|wondering if|i question|it's vague|circle back|it's unclear|unclear about|just thinking)\b/i;

// Self-reflection JSONL path (separate from the heuristic-capture STORE above)
const REFLECTIONS_FILE = path.join(__dirname, '..', '..', 'services', 'selfReflections.jsonl');

// Start listening to conversationLogger events on import (only once)
let _listenerAttached = false;
function startReflectionEngine() {
  if (_listenerAttached) return;
  _listenerAttached = true;
  // Buffer the last 8 turns (assistant messages only) for reflection
  let turnBuffer = [];
  conversationLogger.on('conversation', (turn) => {
    // Only process assistant messages (AVA's own output)
    if (!turn || turn.role !== 'assistant') return;
    turnBuffer.push(turn);
    if (turnBuffer.length > 8) turnBuffer.shift();
    // Reflect when we have at least 2 turns
    if (turnBuffer.length >= 2) {
      const reflections = extractReflectionsFromTurns(turnBuffer);
      for (const r of reflections) {
        persistReflection(r);
      }
    }
  });
}

function extractReflectionsFromTurns(turns) {
  // Concatenate all assistant message texts
  const combined = turns.map(t => t.content || t.text || '').join('\n');
  const sentences = splitSentences(combined);
  const reflective = sentences.filter(s => {
    if (s.length < 60 || s.length > 500) return false;
    if (!FIRST_PERSON.test(s)) return false;
    if (PERFORMATIVE_DOUBT.test(s)) return false;
    return true;
  }).map(s => s.trim());
  if (reflective.length === 0) return [];
  // Take up to 2 most relevant sentences, combine into ≤3 sentence reflection
  const top = reflective.slice(0, 3);
  const reflectionText = top.length <= 2 ? top.join(' ') : top.slice(0, 2).join(' ') + ' ' + top[2];
  // Ensure max 3 sentences
  const parts = reflectionText.split(/(?<=[.!?])\s+/).filter(Boolean);
  const finalText = parts.slice(0, 3).join(' ');
  return [{ text: finalText, source: 'engine', capturedAt: new Date().toISOString() }];
}

function persistReflection(reflection) {
  try {
    fs.mkdirSync(path.dirname(REFLECTIONS_FILE), { recursive: true });
    const line = JSON.stringify(reflection) + '\n';
    fs.appendFileSync(REFLECTIONS_FILE, line, 'utf8');
    logger.info('[self-reflect/engine] reflected', { text: reflection.text.slice(0, 80) });
  } catch (e) {
    logger.warn('[self-reflect/engine] failed to persist reflection', { error: e.message });
  }
}

// Auto-start the engine when module is first imported (safe to call multiple times)
startReflectionEngine();

function splitSentences(text) {
  return String(text || '').replace(/\s+/g, ' ').split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean);
}
function isReflective(s) {
  if (s.length < 40 || s.length > 600) return false;
  if (!FIRST_PERSON.test(s)) return false;
  if (PERFORMATIVE_DOUBT.test(s)) return false;
  return (WANT.test(s) || SELF_META.test(s));
}

function isActionableReflection(s) {
  // A reflection is actionable only if it references concrete plans, files, or steps — not vague circular doubt.
  return Boolean(s &&
    !PERFORMATIVE_DOUBT.test(s) &&
    (ACTIONABLE_PLAN.test(s) || ACTIONABLE_FILE.test(s) || ACTIONABLE_STEP.test(s))
  );
}
function norm(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 90); }

let _cache = null;
function load() {
  if (_cache) return _cache;
  try {
    _cache = fs.existsSync(STORE)
      ? fs.readFileSync(STORE, 'utf8').split(/\r?\n/).filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean)
      : [];
  } catch { _cache = []; }
  return _cache;
}
function loadShared() {
  try { return new Set(fs.existsSync(SHARED) ? JSON.parse(fs.readFileSync(SHARED, 'utf8')) : []); }
  catch { return new Set(); }
}

export function captureFrom(text, source = 'unknown') {
  try {
    const sentences = splitSentences(text).filter(isReflective);
    if (!sentences.length) return 0;
    const store = load();
