    fs.mkdirSync(DATA_DIR, { recursive: true });
    fs.writeFileSync(SHARED, JSON.stringify([...set].slice(-2000)));
  } catch (e) { logger.warn('[self-reflect] markShared failed', { error: e.message }); }
