// Simple relevance scoring helpers for curiosity tasks
// Augmented with execution-history context for per-agent decay-based bonus

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

// Stores per-agent execution results: agentId -> [{success:bool, timestamp:ms}]
const executionHistory = new Map();

// Stores topic scores derived from recent conversation turns: topic -> {score:number, lastSeen:number}
const topicScores = new Map();

// Reference to conversationLogger's event buffer (set by hookConversationLogger)
let _conversationBuffer = [];
let _bufferMaxSize = 50;

/**
 * Hooks into conversationLogger's 'line' events to maintain a rolling buffer
 * of recent conversation lines for topic extraction.
 * @param {import('events').EventEmitter} logger - conversationLogger instance
 */
export function hookConversationLogger(logger) {
  if (!logger || typeof logger.on !== 'function') return;
  logger.on('line', (line) => {
    if (line && typeof line === 'string') {
      _conversationBuffer.push({ text: line, timestamp: Date.now() });
      if (_conversationBuffer.length > _bufferMaxSize) _conversationBuffer.shift();
    }
  });
}

// Records an execution outcome for a given agent for later scoring influence
/**
 * @param {string} agentId
 * @param {boolean} success
 */
export function recordExecution(agentId, success) {
  if (!agentId) return;
  if (!executionHistory.has(agentId)) {
    executionHistory.set(agentId, []);
  }
  const entries = executionHistory.get(agentId);
  // Keep last 20 entries for scoring
  entries.push({ success, timestamp: Date.now() });
  if (entries.length > 20) entries.shift();
}

/**
 * Extracts significant topic keywords from a line of conversation text.
 * Filters out common stopwords and short tokens.
 */
function _extractTopics(text) {
  const stopwords = new Set(['the','a','an','is','are','was','were','be','been','being','have','has','had','do','does','did','will','would','can','could','shall','should','may','might','must','to','of','in','for','on','with','at','by','from','as','into','through','during','before','after','above','below','between','out','off','over','under','again','further','then','once','here','there','when','where','why','how','all','each','every','both','few','more','most','other','some','such','no','nor','not','only','own','same','so','than','too','very','just','because','but','and','or','if','while','about','up','it','its','that','this','these','those','i','me','my','we','our','you','your','he','him','his','she','her','they','them','their','what','which','who','whom']);
  const tokens = tokenize(text);
  const freq = new Map();
  for (const t of tokens) {
    if (t.length < 3 || stopwords.has(t)) continue;
    freq.set(t, (freq.get(t) || 0) + 1);
  }
  // Return top tokens with frequency >= 2 as topics
  const result = [];
  for (const [word, count] of freq) {
    if (count >= 2) result.push(word);
  }
  return result;
}

/**
 * Internal: scores the query by comparing against recent conversation topics
 * using TF overlap with exponential recency decay.
 * @param {string} query - the curiosity query to score
 * @returns {number} score 0..1
 */
function _scoreByRecentConversation(query) {
  if (!query || _conversationBuffer.length === 0) return 0.5;
  const queryTokens = new Set(tokenize(query));
  if (queryTokens.size === 0) return 0.5;
  const now = Date.now();
  const HALF_LIFE_MS = 120_000; // 2 minutes
  let weightedOverlap = 0;
  let totalWeight = 0;
  for (const entry of _conversationBuffer) {
    const age = now - entry.timestamp;
    if (age < 0) continue;
    // Exponential decay: weight = 0.5^(age / halfLife)
    const weight = Math.pow(0.5, age / HALF_LIFE_MS);
    if (weight < 0.01) continue; // skip negligible
    const lineTokens = tokenize(entry.text);
    if (lineTokens.length === 0) continue;
    const overlap = [...queryTokens].filter(t => lineTokens.includes(t)).length;
    const overlapRatio = overlap / Math.max(queryTokens.size, lineTokens.length);
    weightedOverlap += overlapRatio * weight;
    totalWeight += weight;
  }
  if (totalWeight <= 0) return 0.5;
  const raw = weightedOverlap / totalWeight;
  // Store topic tags from the most overlapping line for state
  const bestEntry = _conversationBuffer.reduce((best, entry) => {
    const age = now - entry.timestamp;
    const w = Math.pow(0.5, age / HALF_LIFE_MS);
    return w > best.weight ? { entry, weight: w } : best;
  }, { entry: null, weight: 0 });
  if (bestEntry.entry) {
    const topics = _extractTopics(bestEntry.entry.text);
    for (const t of topics) {
      if (queryTokens.has(t)) {
        topicScores.set(t, { score: raw, lastSeen: now });
      }
    }
  }
  return Math.max(0, Math.min(1, raw));
}

// Clears execution history for a given agent (useful for reset or testing)
export function clearHistory(agentId) {
  if (agentId) {
    executionHistory.delete(agentId);
  } else {
    executionHistory.clear();
  }
}

// Get the decay-based modifier from execution history: reward recent successes, penalize consecutive failures
function _getHistoryModifier(agentId) {
  if (!agentId || !executionHistory.has(agentId)) return 0;
  const entries = executionHistory.get(agentId);
  // Apply time-based decay: recent 60s = full weight, older entries fade linearly
  const now = Date.now();
  const DECAY_MS = 60_000;
  let weightedSuccess = 0;
  let totalWeight = 0;
  for (const e of entries) {
    const age = now - e.timestamp;
    const weight = age <= DECAY_MS ? (1 - age / DECAY_MS) : 0;
    if (weight <= 0) continue;
    weightedSuccess += (e.success ? 1 : 0) * weight;
    totalWeight += weight;
  }
  // Count consecutive failures at the tail (most recent entries, up to last 5)
  let consecutiveFailures = 0;
  for (let i = entries.length - 1; i >= 0 && i >= entries.length - 5; i--) {
    if (!entries[i].success) consecutiveFailures++;
    else break;
  }
  // Decay penalty: -0.15 per consecutive failure beyond 3
  const failPenalty = consecutiveFailures > 3 ? (consecutiveFailures - 3) * -0.15 : 0;
  // Boost if most recent weighted success ratio is high (>80%)
  let successRatio = totalWeight > 0 ? weightedSuccess / totalWeight : 0.5;
  const boostBonus = successRatio > 0.8 ? 0.2 : 0;
  return failPenalty + boostBonus;
}

export function computeRelevanceScore(text = '', query = '', agentId = '') {
  if (!text || !query) return 0.5; // neutral
  // Base score from direct jaccard similarity
  const base = jaccardSim(text, query); // 0..1
  // Boost from recent conversation topics (evidence-backed)
  const conversationScore = _scoreByRecentConversation(query);
  // History modifier from execution outcomes
  const modifier = _getHistoryModifier(agentId); // -0.6 .. +0.2
  // Blend: 40% direct similarity, 40% conversation evidence, 20% history modifier
  const blended = (base * 0.4) + (conversationScore * 0.4) + (modifier * 0.2);
  const result = Math.max(0, Math.min(1, blended));
  return result;
}

export default { tokenize, jaccardSim, computeRelevanceScore, recordExecution, clearHistory, hookConversationLogger, topicScores };

