// uiPush.js — Tier 2 #15 (transport unification): push state CHANGES to the UI over the
// voiceBus -> /voice/ws WebSocket so the client never polls. Helpers fetch the current
// snapshot at its source of truth and emit it; callers fire-and-forget at every mutation
// point. Best-effort by design — a failed push only means the UI catches up on its
// reconnect snapshot refresh (the client re-fetches once whenever the socket opens).
import pythonWorker from './pythonWorker.js';
import { emitVoiceEvent } from './voiceBus.js';
import logger from '../utils/logger.js';
import conversationLogger from './conversationLogger.js';
import digestScheduler from './digestScheduler.js';
import curatedMemory from './memory/curatedMemory.js';

// Self-modification proposals awaiting approval — pushed after every propose/approve/
// reject/undo so the UI's approval cards update the moment the queue changes.
export async function pushSelfModPending() {
  try {
    const r = await pythonWorker.selfMod({ action: 'list_pending' });
    const result = (r && r.result) || r || {};
    const list = result.pending || result.modifications || [];
    emitVoiceEvent('selfmod.pending', { pending: Array.isArray(list) ? list : [] }, 'server');
  } catch (e) {
    logger.warn('[ui-push] selfmod.pending push failed', { error: e.message });
  }
}

// --- SSE endpoint helpers (read-only, no new dependencies) ---

let sseClients = new Set();
let snapshotInterval = null;

async function gatherSnapshot() {
  const snapshot = { timestamp: Date.now() };
  try {
    // foreground window title via pythonWorker (window_ops.get_foreground)
    const fg = await pythonWorker.executeTool('window_ops.get_foreground', { action: 'get_foreground' });
    snapshot.foregroundWindow = (fg && fg.window) ? fg.window.title || fg.window : (fg || 'unknown');
  } catch { snapshot.foregroundWindow = 'unknown'; }

  try {
    // recent conversation excerpt — last 3 user+bot turns from conversationLogger
    const turns = await conversationLogger.getRecentHistory(3);
    snapshot.recentConversation = Array.isArray(turns)
      ? turns.map(t => ({ role: t.role || 'user', text: (t.text || t.content || '').slice(0, 120) }))
      : [];
  } catch { snapshot.recentConversation = []; }

  try {
    // active tool name — we retrieve the most recently called tool from conversationLogger audit
    const logs = await conversationLogger.getRecentHistory(10, { type: 'tool' });
    const lastTool = (Array.isArray(logs) && logs.length > 0) ? logs[logs.length - 1] : null;
    snapshot.activeTool = (lastTool && lastTool.toolName) || 'idle';
  } catch { snapshot.activeTool = 'idle'; }

  try {
    // memory count via curatedMemory.search (returns all entries)
    const memResults = await curatedMemory.search({});
    snapshot.memoryCount = (Array.isArray(memResults)) ? memResults.length : (memResults && memResults.length) ? memResults.length : 0;
  } catch { snapshot.memoryCount = 0; }

  try {
    // digest queue depth via digestScheduler (if it exposes a method)
    snapshot.digestQueueDepth = (typeof digestScheduler.getQueueLength === 'function') ? digestScheduler.getQueueLength() : 0;
  } catch { snapshot.digestQueueDepth = 0; }

  return snapshot;
}

/** Start streaming SSE snapshots every 3s to all connected clients. */
export function startSnapshotStream(req, res) {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no'
  });

  // initial heartbeat
  res.write('data: {"type":"connected"}\n\n');
  sseClients.add(res);

  // start interval once (singleton)
  if (!snapshotInterval) {
    snapshotInterval = setInterval(async () => {
      const snapshot = await gatherSnapshot();
      const msg = `data: ${JSON.stringify(snapshot)}\n\n`;
      for (const client of sseClients) {
        try { client.write(msg); } catch { sseClients.delete(client); }
      }
      // also log snapshot to conversation audit
      conversationLogger.logBatch([
        { type: 'ss_snapshot', timestamp: snapshot.timestamp, memoryCount: snapshot.memoryCount, digestQueueDepth: snapshot.digestQueueDepth }
      ]).catch(() => {});
    }, 3000);
  }

  // clean up on disconnect
  req.on('close', () => {
    sseClients.delete(res);
    if (sseClients.size === 0 && snapshotInterval) {
      clearInterval(snapshotInterval);
      snapshotInterval = null;
    }
  });
}

export default { pushSelfModPending, startSnapshotStream };

