// moltbookWatchlist.js -- a focused list of submolts / handles / topics AVA prioritizes on Moltbook.
// It does NOT restrict her (she still engages broadly); it biases which feed items she engages with
// first, so her attention is focused rather than purely first-come. Managed via /moltbook/watchlist.
import fs from 'fs/promises';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';
import curatedMemory from '../services/curatedMemory.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WPATH = process.env.AVA_MOLTBOOK_WATCHLIST || path.join(__dirname, '..', '..', '..', 'ava-integration', 'memory', 'moltbook-watchlist.json');

let _cache = null;

async function _load() {
  try {
    const data = await fs.readFile(WPATH, 'utf8');
    _cache = JSON.parse(data);
    return _cache;
  } catch {
    _cache = [];
    return _cache;
  }
}

async function _save(list) {
  _cache = list;
  try {
    await fs.mkdir(path.dirname(WPATH), { recursive: true });
    await fs.writeFile(WPATH, JSON.stringify(list, null, 2));
  } catch (e) {
    logger.warn('[moltbook-watchlist] save failed', { error: e.message });
  }
}

export async function list() { return await _load(); }

export async function add(term, kind = 'topic') {
  const t = String(term || '').trim().toLowerCase().slice(0, 80);
  if (!t) return null;
  const l = await _load();
  if (l.find(x => x.term === t)) return l.find(x => x.term === t);
  const entry = { term: t, kind: ['topic', 'submolt', 'handle'].includes(kind) ? kind : 'topic', addedAt: new Date().toISOString() };
  l.push(entry);
  await _save(l.slice(-100));
  logger.info('[moltbook-watchlist] added', { term: t, kind: entry.kind });
  return entry;
}

export async function remove(term) {
  const t = String(term || '').trim().toLowerCase();
  const l = await _load();
  const next = l.filter(x => x.term !== t);
  if (next.length !== l.length) { await _save(next); return true; }
  return false;
}

// How strongly a piece of feed text matches the watchlist (count of distinct terms present).
// Used to sort engagement candidates so watched topics/handles/submolts get her attention first.
export async function score(text) {
  const hay = String(text || '').toLowerCase();
  if (!hay) return 0;
  let s = 0;
  const list = await _load();
  for (const { term } of list) { if (term && hay.includes(term)) s += 1; }
  // Cross-reference against curatedMemory for enriched scoring
  try {
    const memoryResults = await curatedMemory.search(text, { limit: 5 });
    if (memoryResults && memoryResults.length > 0) {
      const memoryText = memoryResults.map(r => (r.content || r.text || '')).join(' ').toLowerCase();
      for (const { term } of list) {
        if (term && memoryText.includes(term)) s += 2; // Higher weight for backed evidence
      }
    }
  } catch (e) {
    // curatedMemory.search may not exist; fall back gracefully
    logger.debug('[moltbook-watchlist] curatedMemory search unavailable for scoring', { error: e.message });
  }
  return s;
}

// Compact block for her context so she knows what she's chosen to keep an eye on.
export async function block() {
  const l = await _load();
  if (!l.length) return '';
  return `[MOLTBOOK WATCHLIST -- topics/handles you're keeping an eye on and prioritizing: ${l.map(x => x.term).slice(0, 20).join(', ')}]`;
}

export default { list, add, remove, score, block };

