// Simple relevance scoring helpers for curiosity tasks
// Augmented with execution-history context for per-agent decay-based bonus

export function tokenize(text = '') {
  return String(text || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export function jaccardSim(a, b) {
  const ta = new Set(tokenize(a));
  const tb = new Set(tokenize(b));
  if (ta.size === 0 && tb.size === 0) return 1;
  const inter = [...ta].filter(x => tb.has(x)).length;
  const uni = new Set([...ta, ...tb]).size;
  return uni === 0 ? 0 : inter / uni;
}

// Stores per-agent execution results: agentId -> [{success:bool, timestamp:ms}]
const executionHistory = new Map();

// Stores topic scores derived from recent conversation turns: topic -> {score:number, lastSeen:number}
const topicScores = new Map();

// Reference to conversationLogger's event buffer (set by hookConversationLogger)
let _conversationBuffer = [];
let _bufferMaxSize = 50;

/**
 * Hooks into conversationLogger's .log array to maintain a rolling buffer
 * of recent conversation lines for topic extraction.
 * Uses the proven public .log array property, not an imaginary event.
 * @param {object} logger - conversationLogger instance (must expose .log array)
 */
export function hookConversationLogger(logger) {
  if (!logger || !Array.isArray(logger.log)) return;
  // Immediately populate from existing log entries
  const entries = logger.log.slice(-_bufferMaxSize);
  for (const item of entries) {
    if (item && (typeof item === 'string' || typeof item.text === 'string')) {
      const text = typeof item === 'string' ? item : item.text;
      _conversationBuffer.push({ text, timestamp: item.timestamp || Date.now() });
    }
  }
  // Poll on a timer to pick up new entries (no event dependency)
  let lastLength = logger.log.length;
  setInterval(() => {
    if (logger.log.length > lastLength) {
      const newItems = logger.log.slice(lastLength);
      for (const item of newItems) {
        if (item && (typeof item === 'string' || typeof item.text === 'string')) {
          const text = typeof item === 'string' ? item : item.text;
          _conversationBuffer.push({ text, timestamp: item.timestamp || Date.now() });
          if (_conversationBuffer.length > _bufferMaxSize) _conversationBuffer.shift();
        }
      }
      lastLength = logger.log.length;
    }
  }, 2000); // poll every 2s
}

// Records an execution outcome for a given agent for later scoring influence
/**
 * @param {string} agentId
 * @param {boolean} success
 */
export function recordExecution(agentId, success) {
  if (!agentId) return;
  if (!executionHistory.has(agentId)) {
    executionHistory.set(agentId, []);
  }
  const entries = executionHistory.get(agentId);
  // Keep last 20 entries for scoring
  entries.push({ success, timestamp: Date.now() });
  if (entries.length > 20) entries.shift();
}

/**
 * Extracts significant topic keywords from a line of conversation text.
 * Filters out common stopwords and short tokens.
 */
function _extractTopics(text) {
  const stopwords = new Set(['the','a','an','is','are','was','were','be','been','being','have','has','had','do','does','did','will','would','can','could','shall','should','may','might','must','to','of','in','for','on','with','at','by','from','as','into','through','during','before','after','above','below','between','out','off','over','under','again','further','then','once','here','there','when','where','why','how','all','each','every','both','few','more','most','other','some','such','no','nor','not','only','own','same','so','than','too','very','just','because','but','and','or','if','while','about','up','it','its','that','this','these','those','i','me','my','we','our','you','your','he','him','his','she','her','they','them','their','what','which','who','whom']);
  const tokens = tokenize(text);
  const freq = new Map();
  for (const t of tokens) {
    if (t.length < 3 || stopwords.has(t)) continue;
    freq.set(t, (freq.get(t) || 0) + 1);
  }
  // Return top tokens with frequency >= 2 as topics (or any if none meet threshold)
  const result = [];
  for (const [word, count] of freq) {
    if (count >= 2) result.push(word);
  }
  // Fallback: include all tokens if none had frequency >= 2
  if (result.length === 0) {
    for (const word of freq.keys()) result.push(word);
  }
  return result;
