        for (const d of docTfs) if (d.tf[qt] > 0) df++;
        idf[qt] = df > 0 ? Math.log(n / df) + 1 : 0;
      }
      // Score each document: sum(tf * idf) for each query term + bonus for exact phrase presence
      for (const d of docTfs) {
