  const summary = top.length
    ? top.map((r) => (r.source === 'conversation' ? `[${r.date} ${r.time || ''} ${r.who}] ${r.text}` : `[${r.label}] ${r.text}`)).join('\n')
    : `No matches for "${query}".`;
  return { status: 'ok', query, count: top.length, results: top, summary };
}

