      const lines = raw.split('\n').filter(l => l.trim());
      for (const line of lines) {
        try {
          const entry = JSON.parse(line);
          if (entry && entry.timestamp && entry.role && entry.content) {
            _memory.push({ timestamp: entry.timestamp, role: entry.role, content: entry.content });
