 * Append a structured entry to the in-memory log and persist to JSONL.
 * @param {string|number} timestamp - ISO string or unix ms
 * @param {string} role - e.g. 'user', 'assistant', 'system'
 * @param {string} content - the text payload
 * @returns {{ ok: boolean, entry?: object, error?: string }}
 */
export function addEntry(timestamp, role, content) {
  if (!role || typeof role !== 'string') return { ok: false, error: 'invalid_role' };
  if (content === undefined || content === null) return { ok: false, error: 'missing_content' };
  const ts = timestamp || Date.now();
  const entry = { timestamp: typeof ts === 'string' ? ts : new Date(ts).toISOString(), role, content: String(content) };
  _memory.push(entry);

  // Persist to JSONL (fire-and-forget, non-blocking)
  try {
    const line = JSON.stringify(entry) + '\n';
    fs.appendFileSync(_JSONL_PATH, line, 'utf8');
  } catch (e) {
    logger?.warn?.('[curatedMemory] JSONL append failed', { error: e.message });
  }

  return { ok: true, entry };
}

/**
 * Get the most recent N entries from the in-memory log.
 * @param {number} [count=10] - number of entries to return
 * @returns {Array<{timestamp: string, role: string, content: string}>}
 */
export function getRecent(count = 10) {
  const n = Math.max(0, Math.min(count, _memory.length));
  return _memory.slice(-n);
}

export default { buildMemoryBlock, appendFact, reload, storeEngagementSignal, getTopicEngagement, addEntry, getRecent, paths: { userPath, memoryPath } };

