export async function scoreTopicsFromLog(jsonlPath, opts = {}) {
  const maxLines = opts.maxLines || 100;
  const halfLife = opts.recencyHalfLifeMs || 120_000;
  const result = new Map(); // topic -> { count, lastTimestamp, interestHits, penaltyCount }

  try {
    const exists = await fs.promises.access(jsonlPath).then(() => true).catch(() => false);
    if (!exists) return [];

    const content = await fs.promises.readFile(jsonlPath, 'utf8');
    const lines = content.trim().split('\n').filter(Boolean);
    const recentLines = lines.slice(-maxLines);

    const now = Date.now();

    for (const line of recentLines) {
      let text = '';
      let timestamp = now;

      try {
        const parsed = JSON.parse(line);
        text = parsed.text || parsed.content || parsed.message || '';
        timestamp = parsed.timestamp || parsed.ts || now;
      } catch {
        text = line;
        timestamp = now;
      }

      if (!text) continue;

      const lowerText = text.toLowerCase();

      // Detect explicit interest cues
      const hasInterestCue = INTEREST_CUES.some(cue => lowerText.includes(cue));

      // Tokenize and count significant words
      const tokens = tokenize(text);
      const freq = {};
      for (const t of tokens) {
        if (t.length < 3) continue;
        freq[t] = (freq[t] || 0) + 1;
      }

      // Detect repeated mentions in this line (repetition within same utterance)
      const repeatedMentions = new Set();
      let match;
      REPETITION_REGEX.lastIndex = 0;
      while ((match = REPETITION_REGEX.exec(line)) !== null) {
        repeatedMentions.add(match[1].toLowerCase());
      }

      for (const [word, count] of Object.entries(freq)) {
        if (count < 1) continue;
        if (!result.has(word)) {
          result.set(word, { count: 0, lastTimestamp: 0, interestHits: 0, repetitionCount: 0 });
        }
        const entry = result.get(word);
        entry.count += count;
        entry.lastTimestamp = Math.max(entry.lastTimestamp, timestamp);
        if (hasInterestCue) entry.interestHits += 1;
        if (repeatedMentions.has(word)) entry.repetitionCount += 1;
      }
    }
  } catch (err) {
    console.error('[curiosityScoring] Error reading conversation log:', err.message);
    return [];
  }

  // Compute final score per topic
  const scoredTopics = [];
  const now = Date.now();
  for (const [topic, data] of result) {
    // Recency component: exponential decay
    const age = Math.max(0, now - data.lastTimestamp);
    const recencyWeight = Math.pow(0.5, age / halfLife);

    // Frequency component: normalize to [0, 1] using log scaling
    const freqRaw = Math.log(1 + data.count) / Math.log(1 + maxLines);
    const freqWeight = Math.min(1, freqRaw);

    // Interest cue boost: each hit adds 0.2, cap at 1
    const interestBoost = Math.min(1, data.interestHits * 0.25);

    // Repetition bonus: each repeated mention within a line adds 0.1, cap at 0.5
    const repBonus = Math.min(0.5, data.repetitionCount * 0.1);

    // Combine: 40% recency, 30% frequency, 20% interest, 10% repetition
    const blended = (recencyWeight * 0.4) + (freqWeight * 0.3) + (interestBoost * 0.2) + (repBonus * 0.1);
    const score = Math.max(0, Math.min(1, blended));

    if (score > 0.05) {
      scoredTopics.push({ topic, score: Math.round(score * 1000) / 1000 });
    }
  }

  // Sort descending by score
  scoredTopics.sort((a, b) => b.score - a.score);

  // Also update internal topicScores map
  for (const st of scoredTopics) {
    topicScores.set(st.topic, { score: st.score, lastSeen: now });
  }

  return scoredTopics;
}

