 * Starts a background poller that periodically calls scoreTopicsFromLog
 * and updates the internal topicScores map. Cleans up automatically.
 * @param {string} jsonlPath - path to conversation JSONL file
 * @param {number} [pollIntervalMs=15000] - how often to rescan
 * @returns {() => void} stop function
 */
export function startTopicPolling(jsonlPath, pollIntervalMs = 15_000) {
  if (_jsonlPollTimer) {
    clearInterval(_jsonlPollTimer);
  }
  _jsonlPath = jsonlPath;

  // Do an immediate first scan
  scoreTopicsFromLog(jsonlPath).catch(err => {
    console.error('[curiosityScoring] initial topic scan failed:', err.message);
  });

  _jsonlPollTimer = setInterval(() => {
    scoreTopicsFromLog(jsonlPath).catch(err => {
      console.error('[curiosityScoring] topic poll failed:', err.message);
    });
  }, pollIntervalMs);

  return () => {
    if (_jsonlPollTimer) {
      clearInterval(_jsonlPollTimer);
      _jsonlPollTimer = null;
    }
  };
}

export default { tokenize, jaccardSim, computeRelevanceScore, recordExecution, clearHistory, hookConversationLogger, topicScores, scoreTopic, getScoredTopics, scoreTopicsFromLog, startTopicPolling };

