    if (!this.currentSession) {
      this.startSession();
    }
    const logEntry = {
      sessionId: this.currentSession,
      timestamp: new Date().toISOString(),
      unixTime: Date.now(),
      type: 'message',
      direction: 'command',
      content: `execute ${commandName}`,  // canonical command string
      metadata: {
        commandName,
        args,
        result,
        messageId: `cmd-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`,
        ...metadata
      }
    };
    this._writeLogEntry(logEntry);
    return logEntry.metadata.messageId;
  }

