// turnGuard.js -- clean task-switch / interrupt handling, plus turn-boundary validation (veto) against conversation history.
// Each conversational turn for a session gets a monotonically increasing token. If a NEWER turn
// begins for the same session while an older one is still working (barge-in, or the user types
// while voice is mid-thought), the older turn detects it's been superseded at its emit point and
// drops its now-stale reply instead of speaking over the new one. In-memory only, per session.
const _gen = new Map();
const _pending = new Map(); // sessionId -> Set<token>

export function begin(sessionId) {
  const s = String(sessionId || 'default');
  const n = (_gen.get(s) || 0) + 1;
  _gen.set(s, n);
  // Track this token as pending; any prior pending tokens for this session remain tracked
  // but will be auto-dropped when they emit and fail isCurrent. Also clean up old pending.
  if (!_pending.has(s)) _pending.set(s, new Set());
  _pending.get(s).add(n);
  return n;
}

// True if `token` is still the latest turn for this session (i.e. not superseded).
export function isCurrent(sessionId, token) {
  return (_gen.get(String(sessionId || 'default')) || 0) === token;
}

// Register that a completion (belonging to `token`) has finished emitting (success or discard).
// This removes it from the pending set to allow eventual GC of the session's pending set.
export function complete(sessionId, token) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  if (set) {
    set.delete(token);
    if (set.size === 0) _pending.delete(s);
  }
}

// Returns the number of pending (in-flight) completions for a session, useful for diagnostic logging.
export function pendingCount(sessionId) {
  const s = String(sessionId || 'default');
  const set = _pending.get(s);
  return set ? set.size : 0;
}

// ---------------------------------------------------------------------------
// Turn-boundary validator: inspects last 2 conversation turns from sessionLogger JSONL
// and rejects repetitive, self-contradictory, or off-topic responses before they are spoken.
// Uses proven execSync('powershell') pattern — no nonexistent API calls.
import { execSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import path from 'path';

// Resolve the JSONL log directory same way sessionLogger does (APPDATA / .ava ).
function _logDir() {
  const base = process.env.APPDATA || process.env.HOME || '.';
  const dir = path.join(base, '.ava');
  return dir;
}

// Read last N JSONL lines from a file (most recent first).
function _tailJsonl(filePath, n) {
  if (!existsSync(filePath)) return [];
  try {
    const raw = readFileSync(filePath, 'utf8').trim();
    if (!raw) return [];
    const lines = raw.split('\n').filter(Boolean);
    const tail = lines.slice(-n).reverse(); // newest first
    return tail.map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  } catch {
    return [];
  }
}

// Find the most recent conversation log file matching pattern 'conversation-*.jsonl'.
function _findLatestLog() {
  const dir = _logDir();
  if (!existsSync(dir)) return null;
  try {
    const files = readFileSync(path.join(dir, 'session-index.txt'), 'utf8')
      .split('\n')
      .filter(Boolean)
      .map(f => path.join(dir, f))
      .filter(f => existsSync(f) && f.endsWith('.jsonl') && f.includes('conversation'));
    if (files.length === 0) return null;
    // files are listed newest-first or we sort by mtime
    files.sort((a,b) => require('fs').statSync(b).mtimeMs - require('fs').statSync(a).mtimeMs);
    return files[0];
  } catch {
    return null;
  }
}

// Return an array of the last 2 conversation turn objects, or empty array.
function _lastTwoTurns() {
  const logFile = _findLatestLog();
  if (!logFile) return [];
  const turns = _tailJsonl(logFile, 2);
  return turns; // newest first
}

// Check two consecutive turns (newer, older) for repetition, contradiction, or off-topic drift.
// Returns null if ok, or a string reason to veto.
function _vetoReason(newerTurn, olderTurn) {
  if (!newerTurn || !olderTurn) return null;

  const newerText = (newerTurn.text || newerTurn.content || '').toLowerCase().trim();
  const olderText = (olderTurn.text || olderTurn.content || '').toLowerCase().trim();
  if (!newerText || !olderText) return null;

  // 1. Repetition: if the two turns are more than 70% similar (simple word overlap)
  const newerWords = new Set(newerText.split(/\s+/).filter(Boolean));
  const olderWords = new Set(olderText.split(/\s+/).filter(Boolean));
  if (newerWords.size > 0 && olderWords.size > 0) {
    const intersection = new Set([...newerWords].filter(w => olderWords.has(w)));
    const overlap = intersection.size / Math.max(newerWords.size, olderWords.size);
    if (overlap >= 0.7) {
      return 'repetitive: new turn is >70% similar to prior turn';
    }
  }

  // 2. Self-contradiction: check common contradictory pairs
  const contradictionPatterns = [
    [/\byes\b/, /\bno\b/],
    [/\bcan('t|not)?\b.*\bcan('t|not)?\b/, /\bcannot\b/],
    [/\bwill\b/, /\bwon('t| not)?\b/],
    [/\bis\b/, /\bis not\b/],
    [/\bgood\b/, /\bbad\b/],
    [/\bright\b/, /\bwrong\b/],
  ];
  for (const [p1, p2] of contradictionPatterns) {
    // Check if one turn affirms and the other negates
    const newerMatch1 = p1.test(newerText);
    const olderMatch2 = p2.test(olderText);
    const olderMatch1 = p1.test(olderText);
    const newerMatch2 = p2.test(newerText);
    if ((newerMatch1 && olderMatch2) || (olderMatch1 && newerMatch2)) {
      return 'self-contradictory: conflicting stance on a topic between consecutive turns';
    }
  }

  // 3. Off-topic / topic drift: check if newer turn shares very few significant words
  //    with the older turn (indicating potentially ignoring prior context).
  //    Use a stop-word filter to reduce noise.
  const stopWords = new Set(['the','a','an','is','are','was','were','i','you','he','she','it','they','we','and','or','but','in','on','at','to','for','of','with','that','this','from','by','as','be','been','being','have','has','had','do','does','did','will','would','can','could','shall','should','may','might','must','not','no','yes','so','if','then','else','when','where','why','how','all','each','every','both','few','more','most','some','any','such','only','own','same','very','just','about','up','out','off','over','after','before','between','under','again','further','once','here','there','what','which','who','whom','whose']);
  const significantNewer = newerText.split(/\s+/).filter(w => !stopWords.has(w) && w.length > 2);
  const significantOlder = olderText.split(/\s+/).filter(w => !stopWords.has(w) && w.length > 2);
  if (significantNewer.length >= 3 && significantOlder.length >= 3) {
    const shared = significantNewer.filter(w => significantOlder.includes(w));
    const ratio = shared.length / Math.max(significantNewer.length, significantOlder.length);
    if (ratio < 0.15) {
      return 'off-topic: new turn shares <15% significant vocabulary with prior turn';
    }
  }

  return null;
}

// Validate a prospective new response against the last 2 conversation turns.
// Returns null if acceptable, or a reason string that serves as veto/lesson.
export function validateResponse(responseText, sessionId) {
  if (!responseText || typeof responseText !== 'string') return null;
  const turns = _lastTwoTurns();
  if (turns.length < 2) return null; // not enough history to validate
  return _vetoReason(turns[0], turns[1]);
}

export default { begin, isCurrent, complete, pendingCount, validateResponse };

