// moltbookWatchlist.js -- a focused list of submolts / handles / topics AVA prioritizes on Moltbook.
// It does NOT restrict her (she still engages broadly); it biases which feed items she engages with
// first, so her attention is focused rather than purely first-come. Managed via /moltbook/watchlist.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import logger from '../utils/logger.js';
import { query } from '../memory/ftsIndex.js';

// JSONL file for scored watchlist results
const SCORES_PATH = path.join(__dirname, '..', '..', '..', 'ava-integration', 'memory', 'moltbook-scores.jsonl');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WPATH = process.env.AVA_MOLTBOOK_WATCHLIST || path.join(__dirname, '..', '..', '..', 'ava-integration', 'memory', 'moltbook-watchlist.json');

function _load() {
  try { return fs.existsSync(WPATH) ? JSON.parse(fs.readFileSync(WPATH, 'utf8')) : []; } catch { return []; }
}
function _save(list) {
  try { fs.mkdirSync(path.dirname(WPATH), { recursive: true }); fs.writeFileSync(WPATH, JSON.stringify(list, null, 2)); }
  catch (e) { logger.warn('[moltbook-watchlist] save failed', { error: e.message }); }
}

export function list() { return _load(); }

export function add(term, kind = 'topic') {
  const t = String(term || '').trim().toLowerCase().slice(0, 80);
  if (!t) return null;
  const l = _load();
  if (l.find(x => x.term === t)) return l.find(x => x.term === t);
  const entry = { term: t, kind: ['topic', 'submolt', 'handle'].includes(kind) ? kind : 'topic', addedAt: new Date().toISOString() };
  l.push(entry); _save(l.slice(-100));
  logger.info('[moltbook-watchlist] added', { term: t, kind: entry.kind });
  return entry;
}

export function remove(term) {
  const t = String(term || '').trim().toLowerCase();
  const l = _load();
  const next = l.filter(x => x.term !== t);
  if (next.length !== l.length) { _save(next); return true; }
  return false;
}

// Map of term -> { score: number, evidence: string[], lastUpdated: string }
const _scores = new Map();

// Load persisted scores from JSONL file on startup
function _loadScores() {
  try {
    if (!fs.existsSync(SCORES_PATH)) return;
    const lines = fs.readFileSync(SCORES_PATH, 'utf8').split('\n').filter(Boolean);
    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        if (entry && entry.term) {
          _scores.set(entry.term, { score: entry.score || 0, evidence: entry.evidence || [], lastUpdated: entry.lastUpdated || entry.addedAt });
        }
      } catch { /* skip malformed */ }
    }
  } catch { /* ignore */ }
}

// Persist a single score entry to JSONL (append)
function _persistScore(term, scoreVal, evidence) {
  try {
    fs.mkdirSync(path.dirname(SCORES_PATH), { recursive: true });
    fs.appendFileSync(SCORES_PATH, JSON.stringify({ term, score: scoreVal, evidence: evidence.slice(0, 5), lastUpdated: new Date().toISOString(), addedAt: _scores.get(term)?.lastUpdated || new Date().toISOString() }) + '\n');
  } catch (e) {
    logger.warn('[moltbook-watchlist] score persist failed', { error: e.message });
  }
}

// How strongly a piece of feed text matches the watchlist (count of distinct terms present).
// Used to sort engagement candidates so watched topics/handles/submolts get her attention first.
// Real implementation: queries the FTS index and session logs for recent evidence of each term.
export function score(text) {
  const hay = String(text || '').toLowerCase();
  if (!hay) return 0;
  let s = 0;
  const watchlist = _load();
  for (const { term } of watchlist) { if (term && hay.includes(term)) s += 1; }
  // Boost score by FTS relevance evidence
  for (const { term } of watchlist) {
    if (!term) continue;
    try {
      const results = query(term, { limit: 5 });
      if (Array.isArray(results) && results.length > 0) {
        const relevance = results.reduce((acc, r) => acc + (typeof r.score === 'number' ? r.score : 0), 0) / results.length;
        const evidenceLinks = results.map(r => r.path || r.id || r.text?.slice(0, 60)).filter(Boolean);
        _scores.set(term, { score: relevance, evidence: evidenceLinks, lastUpdated: new Date().toISOString() });
        _persistScore(term, relevance, evidenceLinks);
        s += relevance * 0.5; // blend FTS relevance into final score (50% weight)
      }
    } catch { /* FTS unavailable, skip */ }
  }
  return s;
}

// Load scores on module init
_loadScores();

// Compact block for her context so she knows what she's chosen to keep an eye on.
export function block() {
  const l = _load();
  if (!l.length) return '';
  return `[MOLTBOOK WATCHLIST -- topics/handles you're keeping an eye on and prioritizing: ${l.map(x => x.term).slice(0, 20).join(', ')}]`;
}

// Get the latest computed scores for all watched terms
// Returns a Map<string, {score: number, evidence: string[], lastUpdated: string}>
export function getScores() {
  // Refresh scores from current watchlist terms
  const watchlist = _load();
  const result = new Map();
  for (const { term } of watchlist) {
    if (term && _scores.has(term)) {
      result.set(term, _scores.get(term));
    }
  }
  return result;
}

// Get top N scored watched terms for scheduling/prioritization
export function getTopScores(n = 5) {
  const entries = [...getScores().entries()]
    .map(([term, data]) => ({ term, score: data.score, evidence: data.evidence, lastUpdated: data.lastUpdated }))
    .sort((a, b) => b.score - a.score)
    .slice(0, n);
  return entries;
}

export default { list, add, remove, score, block, getScores, getTopScores };

