// windowJanitor.js — AVA proactive housekeeping task (runs around the clock).
// Also provides pollActiveWindow() for real-time foreground-window awareness.
// Every interval it runs a hidden PowerShell sweep that closes ONLY non-foreground File Explorer
// windows and idle non-foreground Command Prompt consoles. Scoped to just those two apps, on
// purpose. Never force-kills, never touches the shell/taskbar, and skips the focused window and
// any console younger than 30s (so it won't interrupt a script that's actively running).
import { spawn, execSync } from 'child_process';
import path from 'path';
import { fileURLToPath } from 'url';
import { EventEmitter } from 'events';
import logger from '../utils/logger.js';
import { execCommand } from '../python/pythonWorker.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PS1 = path.join(__dirname, '..', '..', 'scripts', 'windowJanitor.ps1');

const INTERVAL_SEC = Math.max(20, parseInt(process.env.AVA_WINDOW_JANITOR_SECONDS || '60', 10));
let timer = null;
let running = false;
const _foregroundEmitter = new EventEmitter();
let _lastForeground = null;

/**
 * pollActiveWindow — retrieves the active window title and process name via PowerShell's
 * GetForegroundWindow API. Uses execSync (synchronous, but fast: <50ms). Stores result in
 * _lastForeground and emits 'foreground-window' with { title, process, timestamp }.
 * Returns the window object or null on failure.
 */
export function pollActiveWindow() {
  if (process.platform !== 'win32') return null;
  try {
    const raw = execSync(
      `powershell -NoProfile -NonInteractive -Command "$h=Add-Type -MemberDefinition '[DllImport(\"user32.dll\")]public static extern IntPtr GetForegroundWindow();' -Name Win32 -Namespace Win32 -PassThru; $hwnd=$h::GetForegroundWindow(); $p=Get-Process | Where-Object {$_.MainWindowHandle -eq $hwnd} | Select-Object -First 1; if($p){Write-Output \"TITLE:$($p.MainWindowTitle)|PROCESS:$($p.ProcessName)\"}else{Write-Output 'TITLE:|PROCESS:'}"`,
      { encoding: 'utf8', timeout: 10000 }
    ).trim();
    const match = raw.match(/^TITLE:(.*)\|PROCESS:(.*)$/m);
    if (!match) return null;
    const title = match[1].trim();
    const process = match[2].trim();
    const windowInfo = { title, process, timestamp: Date.now() };
    _lastForeground = windowInfo;
    _foregroundEmitter.emit('foreground-window', windowInfo);
    return windowInfo;
  } catch (e) {
    logger.warn('[windowJanitor] pollActiveWindow failed', { error: e.message });
    return null;
  }
}

export function getLastForeground() { return _lastForeground; }
export function onForegroundChange(listener) { _foregroundEmitter.on('foreground-window', listener); return () => _foregroundEmitter.off('foreground-window', listener); }

function sweep() {
  pollActiveWindow();
  if (running) return; // never overlap sweeps
  running = true;
  let out = '';
  let ps;
  try {
    ps = spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', PS1], { windowsHide: true });
  } catch (e) {
    running = false;
    logger.warn('[windowJanitor] spawn failed', { error: e.message });
    return;
  }
  ps.stdout.on('data', (d) => { out += d.toString(); });
  ps.stderr.on('data', () => {});
  ps.on('error', (e) => { running = false; logger.warn('[windowJanitor] powershell error', { error: e.message }); });
  ps.on('close', () => {
    running = false;
    const closed = out.split(/\r?\n/).filter((l) => l.startsWith('CLOSED:')).map((l) => l.replace('CLOSED:', '').trim());
    if (closed.length) logger.info('[windowJanitor] closed idle windows', { count: closed.length, windows: closed.slice(0, 10) });
  });
}

export function start() {
  if (String(process.env.AVA_WINDOW_JANITOR || '').toLowerCase() === 'off') { logger.info('[windowJanitor] disabled via AVA_WINDOW_JANITOR=off'); return; }
  if (process.platform !== 'win32') { logger.info('[windowJanitor] non-Windows platform, skipping'); return; }
  if (timer) return;
  setTimeout(sweep, 8000); // first pass shortly after boot
  timer = setInterval(sweep, INTERVAL_SEC * 1000);
  logger.info('[windowJanitor] started', { intervalSec: INTERVAL_SEC, targets: ['File Explorer windows', 'idle cmd consoles'] });
}
export function stop() { if (timer) { clearInterval(timer); timer = null; } }
export function sweepNow() { sweep(); }

export default { start, stop, sweepNow };

