// Uses a simple word-count heuristic (no external tokenizer) and always keeps system messages.
// Returns the pruned conversation array and adds a system note about pruned count.
function compressConversation(messages, budgetTokens = 6000) {
  if (!Array.isArray(messages) || messages.length < 2) return messages;
  // Always keep all system messages
  const systemMsgs = messages.filter((m) => m?.role === 'system');
  const nonSystem = messages.filter((m) => m?.role !== 'system');
  if (!nonSystem.length) return messages;
  // Simple token estimate: 1 token ≈ 4 characters (safe for English)
  const estimateTokens = (text) => Math.ceil((text || '').length / 4);
  let totalTokens = 0;
  let keepStartIdx = 0;
  // Walk from newest to oldest, accumulating until budget is reached
  for (let i = nonSystem.length - 1; i >= 0; i--) {
    const tokens = estimateTokens(nonSystem[i].content || '');
    if (totalTokens + tokens > budgetTokens) {
      // This message exceeds remaining budget — keep only what we have so far
      keepStartIdx = i + 1;
      break;
    }
    totalTokens += tokens;
  }
  // If we can keep everything, no change needed
  if (keepStartIdx === 0) return messages;
  const keepNonSystem = nonSystem.slice(keepStartIdx);
  const prunedCount = keepStartIdx;
  const pruned = [...systemMsgs, ...keepNonSystem];
  // Add a system message noting the pruning (for context-window awareness)
  if (prunedCount > 0) {
    pruned.unshift({
      role: 'system',
      content: `[System: ${prunedCount} older message(s) pruned to stay within token budget. Continuing from message ${keepStartIdx + 1} of ${nonSystem.length} non-system messages.]`
    });
  }
  // Reflect the change in the original array (for callers that rely on mutation)
  messages.length = 0;
  messages.push(...pruned);
  return pruned;
}

// Token-aware compressor: fetches recent conversation turns via conversationLogger and truncates
// newest-first until within the specified token budget. Returns the truncated array.
async function compressRecentTurns(budgetTokens = 3000) {
  try {
    // Use getRecentHistoryAcrossDays(400) as the available method returning {role, content} objects
    const allTurns = conversationLogger.getRecentHistoryAcrossDays ? conversationLogger.getRecentHistoryAcrossDays(400) : [];
    if (!Array.isArray(allTurns) || allTurns.length === 0) return [];

    const turns = allTurns.map(t => ({
      role: t.role || (t.direction === 'assistant' ? 'assistant' : 'user'),
      content: t.content || ''
    }));

    // Accumulate tokens newest-first until budget is reached
    const result = [];
    let totalTokens = 0;

    for (let i = turns.length - 1; i >= 0; i--) {
      const t = turns[i];
      const tokenCount = await _countTokens(t.content);
      if (totalTokens + tokenCount > budgetTokens) break;
      totalTokens += tokenCount;
      result.unshift(t); // prepend to maintain chronological order
    }

    return result;
  } catch (e) {
    try {
      logger.warn('[compress] compressRecentTurns failed', { error: e.message });
    } catch { /* ignore */ }
    return [];
  }
}

export { summaryFor, lineage, maybeCompress, compressConversation, compressRecentTurns };
export default { summaryFor, lineage, maybeCompress, compressRecentTurns };

