                        "visible": win.visible,
                        "minimized": win.isMinimized,
                        "maximized": win.isMaximized,
                        "active": win.isActive
                    })

            return {
                "status": "ok",
                "message": f"Found {len(window_list)} windows",
                "windows": window_list,
