 * animateExpression(emotion, intensity = 1) — Plays a pre-defined sequence of
 * facial expression morphs (pitch/yaw/roll are kept neutral) for the given
 * emotion label. Uses the existing avatar.expression event pathway. Intensity
 * [0..1] scales morph values and timing; 0.5 is subtle, 1.5 is exaggerated.
 * Returns the total animation duration in ms (for scheduling follow-up).
 * Supported emotions: happy, sad, surprised, angry, neutral, thinking,
 * nodding, confused. Unknown labels silently fall back to neutral.
 */
export function animateExpression(emotion, intensity = 1) {
  const seq = EMOTION_MAPS[String(emotion).toLowerCase()] || EMOTION_MAPS.neutral;
  const i = clampIntensity(intensity);
  let totalMs = 0;
  for (const step of seq) {
    const holdMs = durationForIntensity(step.duration, i);
    const scaled = {};
    for (const [k, v] of Object.entries(step.morphs)) {
      scaled[k] = Math.min(v * i, 1);
    }
    emitVoiceEvent('avatar.expression', { morphs: scaled, hold_ms: holdMs }, 'ava-body');
    totalMs += holdMs;
  }
  return totalMs;
}

export default { applyDirective, extract, strip, extractAndApply, safeLength, animateExpression };

