    const r = await llmService.chatSelfMod(
      [{ role: 'system', content: editSys }, { role: 'user', content: editUser }],
      { temperature: 0.1, max_tokens: 1800, model: process.env.AVA_SELFMOD_MODEL || 'claude-opus-4-8' }
