 * Caches the result in `_cachedActiveWindow` for low-cost synchronous polling.
 * @returns {Promise<string|null>} The title string, or null on failure.
 */
export async function getActiveWindow() {
  try {
    const result = await pythonWorker.execCommand('app_control', {
      action: 'get_active_window'
    });
    // Expected response formats:
    //   { ok: true, result: { title: '...' } }
    //   { ok: true, result: { status: 'ok', title: '...' } }
    //   { result: '...' } (raw string)
    let title = null;
    if (result && typeof result === 'object') {
      if (result.ok && result.result) {
        if (typeof result.result === 'string') {
          title = result.result;
        } else if (result.result.title) {
          title = result.result.title;
        } else if (result.result.status === 'ok' && result.result.title) {
