import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import digestQueue from './digestQueue.js';
import autonomyLib from './autonomyPolicy.js';
import logger from '../utils/logger.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function integrationDir() {
  // Derive integration directory from project root (two levels up from services/)
  return path.resolve(__dirname, '..', '..', 'integration');
}

const MAX_LINES_BEFORE_COMPACT = 2000;
const KEEP_AFTER_COMPACT = 1000;

function getDigestQueuePath() {
  return path.join(integrationDir(), 'digest_queue.jsonl');
}

function maybeCompact() {
  try {
    const qPath = getDigestQueuePath();
    if (!fs.existsSync(qPath)) return;
    const raw = fs.readFileSync(qPath, 'utf8').trim();
    if (!raw) return;
    const lines = raw.split('\n');
    if (lines.length <= MAX_LINES_BEFORE_COMPACT) return;
    // Parse entries, deduplicate by id (keep latest for each id)
    const seen = new Map();
    for (let i = lines.length - 1; i >= 0; i--) {
      try {
        const entry = JSON.parse(lines[i]);
        if (entry && entry.id) {
          if (!seen.has(entry.id)) seen.set(entry.id, entry);
        }
      } catch { /* skip malformed */ }
    }
    let deduped = Array.from(seen.values());
    // Keep only the most recent KEEP_AFTER_COMPACT entries (those last in file order, which are newest)
    if (deduped.length > KEEP_AFTER_COMPACT) {
      deduped = deduped.slice(deduped.length - KEEP_AFTER_COMPACT);
    }
    const newContent = deduped.map(e => JSON.stringify(e)).join('\n') + '\n';
    fs.writeFileSync(qPath, newContent, 'utf8');
    logger.info(`[digest] Compacted queue: ${lines.length} → ${deduped.length} entries`);
  } catch (e) {
    logger.warn('[digest] compact error', { error: e.message });
  }
