// In-memory announcement queue with a proactive tick() that dispatches to user-facing channels.
// pushAnnouncement() — add a short message (spoken by voice runner).
// tick(maxPop=2) — dequeue up to maxPop items and deliver via presenter.say() and uiPush.send().
// drainAnnouncements() / pendingCount() — legacy voice-runner interface.
import avatarBody from './avatarBody.js';
import * as presenter from './presenter.js';
import * as uiPush from './uiPush.js';

const _q = [];
const MAX = 20;

export function pushAnnouncement(text) {
  // Native embodiment: announcements are her words too — execute + strip any
  // inline <move> directives so the runner never speaks a raw tag.
  let t = String(text || '').trim();
  try { t = avatarBody.extractAndApply(t).trim(); } catch { /* keep original */ }
  if (!t) return;
  _q.push(t);
  while (_q.length > MAX) _q.shift();
}

/**
 * Dequeue up to maxPop announcements and dispatch them to the user via
 * presenter.say() (spoken) and uiPush.send() (in-app toast). Logs each
 * delivery. Returns the number actually sent (0 ≤ n ≤ maxPop).
 */
export function tick(maxPop = 2) {
  const limit = Math.min(Math.max(1, Number(maxPop) || 2), _q.length);
  let sent = 0;
  for (let i = 0; i < limit; i++) {
    const msg = _q.shift();
    if (!msg) break;
    try {
      presenter.say(msg);
    } catch {
      // presenter unavailable — fall back to uiPush only
    }
    try {
      uiPush.send({ type: 'announcement', payload: msg });
    } catch {
      // uiPush unavailable — still spoken (if presenter worked)
    }
    sent++;
  }
  return sent;
}

export function drainAnnouncements() {
  return _q.splice(0, _q.length);
}

