}

// Generate a latest structured reflection by reading the last 5 conversation turns,
// running them through heuristic reflective detection, and writing to reflections.jsonl.
// If LLM is available, enrich the reflection with an LLM-generated insight.
// Returns the newly created reflection entry or null.
export async function generateLatestReflection(topic = 'self-awareness') {
  try {
    // Conversation turns from proven getRecentHistory (last 5)
    const history = typeof getRecentHistory === 'function' ? getRecentHistory(5) : [];
    if (!Array.isArray(history) || history.length === 0) {
      logger.info('[self-reflect] No conversation history available for reflection generation');
      return null;
    }

    // Heuristic: extract reflective sentences from conversation text
    const conversationText = history
      .map(turn => (typeof turn === 'object' ? (turn.text || turn.content || turn.message || '') : String(turn)))
      .join('\n');

    const sentences = splitSentences(conversationText).filter(isReflective);
    const bestSentence = sentences.length > 0 ? sentences.sort((a, b) => b.length - a.length)[0] : null;

    let reflectionText = bestSentence || `Reflection on topic "${topic}" from recent conversation — no strong self-signal found.`;

    // If LLM is available, enrich the reflection
    if (typeof llmAsk === 'function') {
      try {
        const prompt = JSON.stringify({
          task: 'Generate a brief, honest self-reflection sentence from AVA\'s perspective based on the following conversation excerpt.',
          topic,
          excerpt: conversationText.slice(0, 1500),
        });
        const llmResponse = await llmAsk(prompt, { system: 'You are an AI generating synthetic reflections for self-monitoring. Be concise and insightful.', maxTokens: 100 });
        if (llmResponse && typeof llmResponse === 'string' && llmResponse.trim().length > 10) {
          reflectionText = llmResponse.trim();
        }
      } catch {
        // Fall through to heuristic text
      }
    }

    // Confirm the integration directory path and write
    const reflectionsDir = path.join(DATA_DIR, '..', '..', 'data', 'integrations');
    const reflectionsJsonl = path.join(reflectionsDir, 'reflections.jsonl');

    const entry = {
      key: norm(reflectionText) || 'reflection-' + Date.now(),
      text: reflectionText,
      source: 'generateLatestReflection',
      topic,
      actionable: isActionableReflection(reflectionText),
      at: new Date().toISOString(),
    };

    try {
      fs.mkdirSync(reflectionsDir, { recursive: true });
      fs.appendFileSync(reflectionsJsonl, JSON.stringify(entry) + '\n');
    } catch (writeErr) {
      logger.warn('[self-reflect] Failed to write to reflections.jsonl', { error: writeErr.message });
    }

    // Also update in-memory cache
    const store = load();
    store.push(entry);
    _cache = store.slice(-MAX);

    logger.info('[self-reflect] Generated latest reflection', { topic, length: reflectionText.length });

    return entry;
  } catch (e) {
    logger.warn('[self-reflect] generateLatestReflection failed', { error: e.message });
    return null;
  }
}

export default { captureFrom, actionable, recent, forShare, markShared, aggregateReflections, getRecentReflections, generateLatestReflection };

