                        "count": len(results),
                        "locations": results
                    }
                else:
                    return {
                        "status": "ok",
                        "message": "Image not found on screen",
                        "count": 0,
                        "locations": []
                    }
            except Exception as e:
                return {"status": "error", "message": f"Image location error: {str(e)}"}

