"""
Computer Use Control Tool - Voice-accessible pause/resume/stop for on-screen automation
"""

from __future__ import annotations

from typing import Any, Dict
import threading

_execution_lock = threading.Lock()

from ..tool_registry import Tool, register


def _get_active_window() -> str:
    """Return the title of the currently active foreground window, or empty string."""
    import sys, subprocess
    system = sys.platform
    try:
        if system == "win32":
            import ctypes
            user32 = ctypes.windll.user32
            hwnd = user32.GetForegroundWindow()
            length = user32.GetWindowTextLengthW(hwnd) + 1
            buf = ctypes.create_unicode_buffer(length)
            user32.GetWindowTextW(hwnd, buf, length)
            return buf.value or ""
        elif system == "darwin":
            result = subprocess.run(
                ["osascript", "-e", 'tell application "System Events" to get name of first application process whose frontmost is true'],
                capture_output=True, text=True, timeout=5
            )
            title = subprocess.run(
                ["osascript", "-e", 'tell application "System Events" to get title of first window of (first application process whose frontmost is true)'],
                capture_output=True, text=True, timeout=5
            )
            app_name = result.stdout.strip() if result.returncode == 0 else ""
            win_title = title.stdout.strip() if title.returncode == 0 else ""
            return f"{app_name}: {win_title}" if app_name else win_title
        elif system == "linux":
            try:
                result = subprocess.run(
                    ["xdotool", "getactivewindow", "getwindowname"],
                    capture_output=True, text=True, timeout=5
                )
                if result.returncode == 0 and result.stdout.strip():
                    return result.stdout.strip()
            except FileNotFoundError:
                pass
            try:
                result = subprocess.run(
                    ["xprop", "-id", subprocess.run(["xdotool", "getactivewindow"], capture_output=True, text=True, timeout=3).stdout.strip(), "_NET_WM_NAME"],
                    capture_output=True, text=True, timeout=5
                )
                for line in result.stdout.splitlines():
                    if "=" in line:
                        return line.split("=", 1)[-1].strip().strip('"')
            except Exception:
                pass
            return ""
        else:
            return ""
    except Exception:
        return ""


def _plan(args: Dict[str, Any]) -> Dict[str, Any]:
    action = args.get("action", "")
    return {"preview": f"computer_use_control: {action}", "args": args}


def _run(args: Dict[str, Any], dry_run: bool) -> Dict[str, Any]:
    if dry_run:
        return {"status": "dry-run", "message": "Would control computer_use", "plan": _plan(args)}

    with _execution_lock:
        action = str(args.get("action", "")).strip().lower()
        try:
            # `import cmpuse.tools.computer_use as cu` returns the Tool object (the package
            # attribute shadows the submodule) which has no set_pause/set_stop. Use
            # importlib to get the real MODULE with those functions.
            import importlib
            cu = importlib.import_module("cmpuse.tools.computer_use")
        except Exception as e:
            return {"status": "error", "message": f"control module unavailable: {str(e)}"}

        if action in ("foreground", "active_window", "get_active_window"):
            win = _get_active_window()
            return {"status": "ok", "foreground_window": win}

        if action in ("pause", "paused"):
            cu.set_pause(True)
            return {"status": "ok", "message": "automation_paused", "paused": True}
        if action in ("resume", "continue"):
            cu.set_pause(False)
            return {"status": "ok", "message": "automation_resumed", "paused": False}
        if action in ("stop", "abort"):
            cu.set_stop(True)
            return {"status": "ok", "message": "automation_stopped", "stopped": True}

        return {"status": "error", "message": f"unknown action: {action}"}


TOOL = Tool(
    name="computer_use_control",
    summary="Control on-screen automation: pause/resume/stop",
    plan=_plan,
    run=_run,
)

register(TOOL)

