/**
 * Record a lesson (a rule/insight) into the JSONL lessons file, using the same path as addLesson.
 * This replaces the previous stub that did nothing.
 */
export function recordLesson({ rule, source = '' } = {}) {
  const r = String(rule || '').trim();
  if (!r) return { ok: false, error: 'rule is required' };
  const dir = lessonsDir();
  try {
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(lessonsFile(), JSON.stringify({ ts: Date.now(), source: String(source).slice(0, 120), rule: r.slice(0, 600) }) + '\n');
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

/**
 * Get the most recent n mutations from evolution_log.jsonl (stored in the integrationDir).
 * Returns an array of parsed JSON objects (latest first). If the file does not exist, returns [].
 */
export function getRecentMutations(n = 10) {
  try {
    const integrationRoot = avaPaths.integrationDir();
    // The evolution_log is stored at integration/evolution_log.jsonl
    const logPath = path.join(integrationRoot, 'evolution_log.jsonl');
    if (!fs.existsSync(logPath)) return [];
    const lines = fs.readFileSync(logPath, 'utf8').split(/\r?\n/).filter(Boolean);
    const parsed = [];
    for (const line of lines.slice(-Math.max(n, 200))) { // read up to 200 lines to get latest n
      try {
        parsed.push(JSON.parse(line));
      } catch { /* skip malformed */ }
    }
    return parsed.slice(-n).reverse();
  } catch {
    return [];
  }
}

