import fs from 'fs';
import path from 'path';
import { spawn, execFileSync } from 'child_process';
import logger from '../utils/logger.js';
import avaPaths from '../utils/paths.js';

let restartScheduled = false;
let restartInProgress = false;
let lastRestartStatus = {
  status: 'idle',
  reason: null,
  changedFiles: [],
  error: null,
  timestamp: null
};

function writeRestartRecord(record) {
  try {
    fs.mkdirSync(avaPaths.dataDir(), { recursive: true });
    fs.writeFileSync(
      path.join(avaPaths.dataDir(), 'pending-server-restart.json'),
      JSON.stringify(record, null, 2),
      'utf8'
    );
  } catch {}
}

function updateStatus(partial) {
  lastRestartStatus = {
    ...lastRestartStatus,
    ...partial,
    timestamp: new Date().toISOString()
  };
  return lastRestartStatus;
}

function getBackupPath(filePath) {
  const dir = path.dirname(filePath);
  const base = path.basename(filePath);
  return path.join(dir, `${base}.bak`);
}

function ensureBackup(filePath) {
  try {
    const backupPath = getBackupPath(filePath);
    if (!fs.existsSync(backupPath) && fs.existsSync(filePath)) {
      fs.copyFileSync(filePath, backupPath);
    }
  } catch (e) {
    logger.warn('[selfRestart] failed to create backup before syntax check', {
      filePath,
      error: e.message
    });
  }
}

function revertFile(filePath) {
  const backupPath = getBackupPath(filePath);
  if (fs.existsSync(backupPath)) {
    try {
      fs.copyFileSync(backupPath, filePath);
      logger.warn('[selfRestart] reverted file from backup after syntax failure', { filePath });
      return true;
    } catch (e) {
      logger.warn('[selfRestart] failed to revert file from backup', {
        filePath,
        error: e.message
      });
    }
  }
  return false;
}

function checkSyntaxForFile(filePath) {
  try {
    // Ensure we have a backup before we consider activating this version
    ensureBackup(filePath);
    execFileSync(process.execPath, ['--check', filePath], {
      stdio: 'ignore'
    });
    return { ok: true };
  } catch (e) {
    return {
      ok: false,
      error: e.message || String(e)
    };
  }
}

function scheduleServerRestart({ reason = 'approved self-modification', delayMs = 2500 } = {}) {
  if (process.env.AVA_SELF_RESTART_OFF === '1') {
    return { scheduled: false, reason: 'disabled by AVA_SELF_RESTART_OFF' };
  }
  if (restartScheduled || restartInProgress) {
    // Coalesce multiple requests into a single pending restart
    updateStatus({
      status: 'pending',
      reason,
      error: null
    });
    return { scheduled: true, alreadyScheduled: true, reason: 'restart already scheduled' };
  }

  const serverRoot = avaPaths.serverDir();
  const serverEntry = path.join(serverRoot, 'src', 'server.js');
  const helper = path.join(serverRoot, 'scripts', 'restart-server-after-delay.cjs');
  if (!fs.existsSync(serverEntry) || !fs.existsSync(helper)) {
    const failureReason = 'restart helper or server entry not found';
    updateStatus({
      status: 'failed',
      reason,
      error: failureReason
    });
    return { scheduled: false, reason: failureReason };
  }

  const record = {
    requestedAt: new Date().toISOString(),
    reason,
    parentPid: process.pid,
    serverEntry,
    delayMs
  };
  writeRestartRecord(record);

  try {
    restartScheduled = true;
    restartInProgress = true;
    updateStatus({
      status: 'in-progress',
      reason,
      error: null
    });

    const child = spawn(process.execPath, [helper, serverEntry, String(delayMs)], {
      cwd: serverRoot,
      detached: true,
      stdio: 'ignore',
      env: { ...process.env, AVA_RESTART_PARENT_PID: String(process.pid) }
    });
    child.unref();
    logger.warn('[selfRestart] server restart scheduled', record);

    // Mark as completed just before this process exits; the new process
    // will start with a fresh idle status.
    setTimeout(() => {
      updateStatus({ status: 'completed' });
      process.exit(0);
    }, 700);

    return { scheduled: true, delayMs, reason };
  } catch (e) {
    restartScheduled = false;
    restartInProgress = false;
    logger.warn('[selfRestart] failed to schedule server restart', { error: e.message });
    updateStatus({
      status: 'failed',
      reason,
      error: e.message
    });
    return { scheduled: false, reason: e.message };
  }
}

async function requestRestart({ reason = 'approved self-modification', changedFiles = [], delayMs = 2500 } = {}) {
  const uniqueChanged = Array.from(new Set(changedFiles || []));

  if (process.env.AVA_SELF_RESTART_OFF === '1') {
    return updateStatus({
      status: 'skipped',
      reason,
      changedFiles: uniqueChanged,
      error: 'disabled by AVA_SELF_RESTART_OFF'
    });
  }

  // Syntax check all provided .js files before scheduling a restart.
  const failures = [];
  for (const filePath of uniqueChanged) {
    if (typeof filePath !== 'string') continue;
    if (!filePath.endsWith('.js')) continue;
    if (!fs.existsSync(filePath)) continue;

    const result = checkSyntaxForFile(filePath);
    if (!result.ok) {
      failures.push({ file: filePath, error: result.error });
      // Attempt revert immediately on failure
      revertFile(filePath);
    }
  }

  if (failures.length > 0) {
    const error = {
      type: 'syntax-error',
      message: 'Syntax check failed for one or more files; changes reverted where possible.',
      details: failures
    };
    logger.warn('[selfRestart] syntax check failed, restart skipped', error);
    return updateStatus({
      status: 'skipped',
      reason,
      changedFiles: uniqueChanged,
      error
    });
  }

  // All syntax checks (if any) passed; schedule a canonical restart.
  const scheduleResult = scheduleServerRestart({ reason, delayMs });

  if (!scheduleResult.scheduled) {
    return updateStatus({
      status: 'failed',
      reason,
      changedFiles: uniqueChanged,
      error: scheduleResult.reason || 'failed to schedule restart'
    });
  }

  const status = restartScheduled || restartInProgress ? 'pending' : 'in-progress';
  return updateStatus({
    status,
    reason,
    changedFiles: uniqueChanged,
    error: null
  });
}

function getRestartStatus() {
  return lastRestartStatus;
}

export { scheduleServerRestart, requestRestart, getRestartStatus };
export default { scheduleServerRestart, requestRestart, getRestartStatus };

